SELECT 'moj-all-verified-judgments-review-002-chunk-112' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0dc1c76d-59f1-5fb3-bb73-325d8b2dcdc5","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -وجود سوابق على املدعى عليه -إقرار املدعى عليه -تغليظ العقوبة -تعزير بالسجن واجللد -اإلقرار حجة معتبرة شرع ا .","document_number":"34271857","case_number":"33393127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بأن احلكم قليل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/18","year":"1434","subject":"اعتداء -ضرب -وجود سوابق على املدعى عليه -إقرار املدعى عليه -تغليظ العقوبة -تعزير بالسجن واجللد -اإلقرار حجة معتبرة شرع ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34271857 :‬تاريخه‪1434/07/18:‬هـ‬\n                    ‫رقم الدعوى‪33393127:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34358482‬تاريخه‪1434/11/12:‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬وجــود ســوابق علــى املدعــى عليــه ‪ -‬إقــرار املدعــى‬\n                   ‫عليــه ‪ -‬تغليــظ العقوبــة ‪ -‬تعزيــر بالســجن واجللــد‬\n\n\n\n\n                                             ‫‪ -‬اإلقرار حجة معتبرة شرع ًا ‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــي عليــه بتوجيــه االتهــام لــه بضــرب آخــر‬\n‫عمــد ًا نتــج عــن ذلــك إصابتــه‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة ‪،‬‬\n‫مت القبــض علــى املدعــي عليــه بنــاء علــى شــكوى مــن شــخص تعــرض‬\n‫ـاء‬\n‫للضــرب وأصيــب بجــرح قطعــي باجلبهــة ومــدة الشــفاء ســبعة أيــام بنـ ً‬\n‫علــى التقريــر الطبــي ‪ ،‬مت اســتجواب املدعــي عليــه وأقــر بضــرب املجني‬\n‫عليــه وإصابتــه‪ ،‬مت عــرض الدعــوى على املدعى عليه وأنكر الدعوى‪،‬‬\n‫بنــاء علــى إقــراره لــدى هيئــة التحقيــق واالدعــاء العــام ولوجــود ســوابق‬\n‫فقــد صــدر احلكــم بثبــوت إدانتــه مبــا نســب إليــه واحلكــم بســجنه ســتة‬\n‫أشــهر وجلــده ثالثــن جلــدة تكــرر عليــه أربــع مــرات علــى دفعــات‪ ،‬مت‬\n‫رفــع احلكــم حملكمــه االســتئناف بنــاء علــى معارضــة املدعــي العــام ‪،‬‬\n‫صــدق قــرار محكمــة االســتئناف بــأن احلكــم قليــل‪ ،‬مت زيــادة مــدة‬\n‫الســجن شــهرين ليكــون كامــل املــدة ثمانيــة أشــهر وجعــل اجللــد‬\n\n                                                                                   ‫‪98‬‬\n\f     ‫خمســن جلــدة تكــرر علــى أربــع مــرات بينهــا أســبوع ‪ ،‬صــدق احلكــم‬\n                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫باملدينة املنورة وبناء على املعاملة املقيدة باحملكمة برقم ‪331090662‬‬\n     ‫وتاريــخ ‪ 1433/06/10‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/28‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 9 : 00‬وفيهــا حضــر املدعــي العــام ‪........‬‬\n     ‫ســعودي مبوجــب الســجل املدنــي رقــم (‪ )........‬والتعميــد رقــم (‪)........‬‬\n     ‫يف ‪1434/6/12‬ه ـ مــن اإلدعــاء العــام باملدينــة املنــورة وادعــى علــى‬\n     ‫‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬قائــا يف‬\n     ‫حتريــر أنــه بتاريــخ ‪1434/5/6‬ه ـ أبلــغ ‪........ /‬شــرطة ‪ ..........‬عــن تعرضه‬\n     ‫للضــرب مــن قبــل املدعــى عليــه املذكــور أعــاه ممــا نتــج عنــه إصابتــه‬\n     ‫بجــرح قطعــي يف اجلبهــه ومــدة الشــفاء ســبعة أيــام إســتنادا للتقريــر‬\n     ‫الطبــي الصــادر مــن مستشــفى اإلنصــار برقــم (‪ )........‬يف ‪1434/5/6‬ه ـ‬\n     ‫وبســماع أقــوال املدعــى عليــه أعتــرف أنــه ضــرب املدعــي وأنــه املتســبب‬\n     ‫يف إصابتــه وانتهــى التحقيــق الــى إتهامــه بضــرب ‪........‬عمــدا ممــا نتــج‬\n     ‫عنــه إصابتــه الــواردة يف التقريــر الطبــي املرفــق وذلــك لألدلــة التاليــة ‪-1‬‬\n     ‫إعترافــه املنــوه عنــه ‪ -2‬التقريــر الطبــي املشــار اليــه وحيــث أن ماأقــدم‬\n     ‫عليــه املتهــم فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبات ماأســند اليه‬\n     ‫واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ماأقــدم عليــه مــع طلــب تشــديد‬\n     ‫العقوبــة بحقــه لقــاء تعــدد ســوابقه اجلنائيــة علمــا بــأن احلــق اخلــاص‬\n     ‫اليــزال قائمــا ثــم أحضــر املتهــم مــن الســجن وبســؤاله عمــا نســب اليــه‬\n\n‫‪99‬‬\n\f‫إجــاب أنكــر ضــرب املدعــي والــذي حصــل أننــا متاســكت معــه عنــد‬\n‫بــاب إحــدى العمائــر وضربنــي وضربتــه وملــا هربــت وركبــت ســيارتي‬\n‫حلقنــي يجــري وارتطــم رأســه بالســيارة فحصلــت اإلصابــة وليــس لدي ما‬\n‫يثبــت ذلــك ولــم يحضــر املدعــي باحلــق اخلــاص رغــم الطلبــات املتكــررة‬\n‫وعليــه وبنــاء علــى مــا جــاء بالئحــة االتهــام والتــي انتهــى فيهــا التحقيــق‬\n‫الــى توجيــه االتهــام الــى ‪ ........‬ســعودي اجلنســية ‪ 30‬ســنه بضــرب ‪........‬‬\n‫عمــدا ممــا نتــج عنــه اصابتــه الــواردة يف التقريــر الطبــي املرفــق ولكــون‬\n‫مــا اقــدم عليــه فعــل محــرم ومعاقــب عليــه شــرعا طلــب املدعــي العــام‬\n‫اثبــات مااســند اليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مااقــدم عليــه‬\n‫مــع طلــب تشــديد العقوبــة لقــاء تعــدد ســوابقه اجلنائيــة علمــا بــان احلــق‬\n‫اخلــاص اليــزال قائمــا وبنــاء علــى مــا أجــاب بــه املتهــم حيــث انكــر‬\n‫تهمــة الضــرب واعتــرف بانــه متاســك مــع املدعــي عنــد احــدى العمائــر‬\n‫وتضاربــا وانــه أي املتهــم هــرب فلحــق بــه املدعــي وارتطــم راســه بالســيارة‬\n‫فحصلــت االصابــة وليــس لديــه اثبــات علــى ذلــك وحيــث جــرى االطــاع‬\n‫علــى اقوالــه لــدى هيئــة التحقيــق واالدعــاء العــام فوجــد معترفــا بضــرب‬\n‫املدعــي وانــه املتســبب يف اصابتــه وحيــث ان االقــرار حجــة معتبــرة‬\n‫شــرعا فيعامــل مبتقضــى اقــراره املعتبــر شــرعا ألنــه اقــرار اخــذ امــام‬\n‫جهــة رســمية مخولــه يف اخــذه ونظــرا لتعــدد ســوابقه مــن اجــل ماتقــدم‬\n‫حكمــت بادانــة املتهــم مبــا نســب اليــه واحلكــم بســجنه ســتة اشــهر‬\n‫اعتبــارا مــن مــدة توقيفــه وبجلــده ثالثــن جلــده تكــرر عليــه اربــع مــرات‬\n‫بينهــا اســبوع بــذا صــدر احلكــم وافهــم حســب االصــول فقــرر املتهــم‬\n‫قناعتــه وقــرر املدعــي العــام االعتــراض بالئحــة وصلــى اهلل علــى ســيدنا‬\n                 ‫ونبينــا محمــد وعلــى الــه وصحبــه حــرريف ‪1434/7/09‬ه ـ‬\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي انــا ‪........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة ففــي يــوم اخلميــس املوافــق ‪1434/10/8‬ه ـ أفتتحــت‬\n      ‫اجللســة الســاعة العاشــرة صباحــا وفيهــا جــرى اإلطــاع علــى قــرار‬\n      ‫املالحظــة رقــم ‪ 34316560‬يف ‪1434/9/10‬ه ـ الصــادر عــن أصحــاب‬\n      ‫الفضيلــة قضــاة اإلســتئناف الدائــرة اجلزائيــة الرابعــة مبكــة املكرمــة‬\n      ‫املشــتمل علــى املالحظــة علــى احلكــم الصــادر عنــا برقــم ‪341189434‬‬\n      ‫يف ‪1434/8/14‬ه ـ املتعلــق بدعــوى املدعــي العــام ضــد ‪........‬املتهــم يف‬\n      ‫ضــرب ‪........‬ومضمــون املالحظــة أن احلكــم علــى املدعــى عليــه مــن‬\n      ‫ســجن وجلــد قليــل وذلــك إلدانتــه بهــذه الدعــوى وملــا لــه مــن ســوابق‬\n      ‫ثمــان كلهــا يف املخــدرات والســرقات واإلعتــداء ومقاومــة رجــل االمــن‬\n      ‫لــذا يلــزم إعــادة النظــر وزيــادة عقوبتــه فاألحــكام الضعيفــه ألصحــاب‬\n      ‫الســوابق غيــر مجديــه واهلل املوفــق وبعــرض ذلــك علــى املتهــم أجــاب‬\n      ‫أمتســك باحلكم الصادر يف حقي وبعرض ذلك على املدعي العام ‪........‬‬\n      ‫أجــاب أمتســك مبــا جــاء بالالئحــة االعتراضيــه وعليــه ومتشــيا مــع ماجــاء‬\n      ‫مبالحظــة أصحــاب الفضيلــة قضــاة اإلســتئناف ولوجاهــة ماذكــر فقــد‬\n      ‫تقــرر زيــادة مــدة الســجن وزيــادة اجللــد وذلــك بجعل الســجن ثمانية أشــهر‬\n      ‫إعتبــارا مــن مــدة توقيفــه وبجعــل اجللــد خمســن جلــده تكــرر عليــه أربــع‬\n      ‫مــرات بينهــا أســبوع بــذا صــدر احلكــم وأفهــم حســب االصــول فقــرر‬\n      ‫املتهــم قناعتــه وقــرر املدعــي العــام ببقائــه علــى إعتراضــه ويلحــق ذلــك‬\n      ‫بالقرار رقم ‪ 34271857‬يف ‪1434/7/18‬هـ واهلل املســتعان وصلى اهلل‬\n                               ‫علــى ســيدنا ونبينــا محمــد حــرر يف ‪1434/10/8‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪........‬رئيــس احملكمــة اجلزائيــة باملدينــة‬\n      ‫املنــورة والقائــم بعمــل القاضــي ‪........‬أثنــاء إجازتــه ففــي يــوم االربعــاء‬\n\n\n‫‪101‬‬\n\f‫املوافــق ‪1434/12/3‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا‬\n‫وقــد عــادت املعاملــة مــن محكمــة اإلســتئناف مبكــة املكرمــة بالرقــم‬\n‫(‪ )341189434‬يف ‪1434/11/20‬ه ـ وبرفقــه احلكــم الصــادر مــن‬\n‫فضيلتــه بالرقــم (‪ )34271857‬يف ‪1434/7/18‬ه ـ واملتضمــن املصادقــة‬\n‫علــى احلكــم بالقــرار رقــم (‪ )34358482‬يف ‪1434/11/12‬ه ـ واملتعلــق‬\n‫باملتهــم ‪........‬املتهــم يف إيــذاء الغيــر ولكــي ال يخفــى جــرى التهميــش‬\n                                             ‫حــرر يف ‪1434/12/3‬ه ـ‬\n\n\n\n\n                                                                                 ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":98,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fde94e967d7766bdfd6f8cd789c86bdb10319f85dd39f62097c7eeb49228cba6","normalized_text_hash":"bbf5d335146dae2fac6e80902cd01124e2c64a799e61e707904ac3d09ed32b8b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p98-34271857"},{"id":"8258e5f2-82e5-5c2f-966b-0c450cc75489","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوجة زوجها -ثبوت إدانة املدعى عليها - تعزير بالسجن واجللد .","document_number":"3462879","case_number":"33397208","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"اعتداء -ضرب -ضرب الزوجة زوجها -ثبوت إدانة املدعى عليها - تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3462879 :‬تاريخه‪1434/3/15 :‬هـ‬\n                          ‫رقم الدعوى‪33397208:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34196942‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب‪ -‬ضــرب الزوجــة زوجهــا ‪ -‬ثبــوت إدانــة املدعــى عليهــا ‪-‬‬\n                                                        ‫تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪-1‬االعتــداء اجلســدي علــى اآلخريــن بالضــرب ونحــوه بــا مقتضــى‬\n                        ‫شــرعي موجــب للتعزيــر يف احلــق العــام واخلــاص‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليهــا بقيامهــا بضــرب‬\n      ‫زوجهــا بــكأس زجــاج علــى رأســه ‪ ،‬أدى لتمــزق بفــروة الــرأس بطــول‬\n      ‫عشــرة ســنتيمتر ‪ ،‬ومــدة الشــفاء أســبوع ‪ ،‬وطلــب إثبــات مــا أســند إليهــا‬\n      ‫وإيقــاع العقوبــة التعزيريــة عليهــا ‪ ،‬أقــرت املدعــى عليهــا بأنهــا قامــت‬\n      ‫بضــرب زوجهــا علــى وفــق مــا هــو مبــن آنف ـ ًا ‪ ،‬وذلــك لغضبهــا بعدمــا‬\n      ‫رفــض زوجهــا حضورهــا خلطبــة ابنتهــا ‪ ،‬وقيامــه بإنزالهــا مــن ســيارة‬\n      ‫األجــرة ‪ ،‬وأن املدعــي بعــد هــذه الواقعــة طلقهــا ‪ ،‬حضــر املدعــي اخلــاص‬\n      ‫وقــرر بــأن املدعيــة كانــت زوجتــه ومنعهــا مــن الذهــاب يف ســيارة‬\n      ‫األجــرة فلمــا دخــل البيــت قامــت بضربــه بــكأس زجاجــي علــى رأســه‬\n      ‫‪ ،‬ممــا أحــدث فيــه اإلصابــة وطلــب احلكــم عليهــا بتأديبهــا‪ ،‬جــرى‬\n      ‫محاولــة الصلــح بينهمــا ورفضــا الصلــح‪ ،‬باالطــاع علــى التقريــر الطبــي‬\n\n‫‪103‬‬\n\f‫املتضمــن الكشــف علــى املدعــى عليــه ووجــود متــزق بفــروة الــرأس طولــه‬\n‫ـاء علــى مــا‬\n           ‫عشــرة ســنتيمتر بآلــة غيــر حــادة ومــدة الشــفاء أســبوع‪ ،‬بنـ ً‬\n‫تقــدم مــن دعــوى املدعــي العــام واخلــاص فقــد قــررت احملكمــة ثبــوت‬\n‫إدانــة املدعــى عليهــا بضــرب املدعــي اخلــاص بــكأس زجــاج علــى رأســه‬\n‫أدى حلــدوث إصابــة بــه وحكمــت عليهــا بســجنها خمســة أيــام وجلدهــا‬\n‫خمــس جلــدات للحــق العــام ‪ ،‬وســجنها خمســة أيــام وجلدهــا خمــس‬\n‫جلــدات مقابــل احلــق اخلــاص‪ ،‬قــرر املدعــي العــام عــدم االعتــراض كمــا‬\n‫قــرر املدعــي اخلــاص القناعــة بينمــا اعترضــت املدعيــة وطلبــت اســتئناف‬\n‫احلكــم بالئحــة فأفهمــت بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                  ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/3/15‬ه ـ لــدي أنــا‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫‪........‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )33397208‬وتاريــخ ‪1433/6/11‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــرت ‪........‬ســعودية اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ( ‪ )..........‬واملعــرف بهــا مــن قبــل ابنهــا ‪........‬ســعودي اجلنســية‬\n‫مبوجــب ســجل مدنــي رقــم (………) وقــدم املدعــي العــام الئحــة‬\n‫االدعــاء املتضمنــة بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع‬\n‫الهيئــة باملنطقــة الشــرقية أدعــي علــى املذكــورة أعــاه فباالطــاع علــى‬\n‫تقريــر األحــوال األمنيــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدمــام‬\n‫تبــن أنــه بتاريــخ ‪1433/5/5‬ه ـ وردهــم بــاغ مــن أحــد املواطنــن يدعــى‬\n‫‪ -........ /‬ســعودي اجلنســية ‪ -‬يفيــد فيــه عــن تعرضــه للضــرب مــن قبــل‬\n                                                                                            ‫‪104‬‬\n\f      ‫زوجتــه املدعــى عليهــا اثــر ســوء تفاهم معها حيــث قامت بضربه بكأس‬\n      ‫وعمــل لــه ســبع غــرز وبســماع أقــوال‬\n                                             ‫زجــاج علــى رأســه وحلقــت بــه إصابــة ُ‬\n      ‫املدعــى عليهــا أفــادت عــن قيــام زوجهــا مــن منعهــا مــن حضــور خطوبــة‬\n      ‫ابنتهــا وقــام بدفعهــا مــن ســيارة الليموزيــن وإنزالهــا منــه بالقــوة وعنــد‬\n      ‫دخولهمــا البيــت عصبــت منــه وقامــت برميــه بكوب زجاج وباســتجوابها‬\n      ‫أفــادت مبثــل مــا ورد يف ســماع أقوالهــا األوليــة مضيفــة بــأن مــا ذكــر‬\n      ‫زوجهــا صحيــح حيــث قامــت بضربــه بــكأس زجــاج يف رأســه ممــا‬\n      ‫تســبب لــه بتمــزق بفــروة الــرأس ألنــه منعهــا مــن حضــور خطبــة ابنتهــا‬\n      ‫وقــد صــدر بحــق املدعــي ‪........ /‬التقريــر الطبــي رقــم (‪ )........‬الصــادر‬\n      ‫مــن مجمــع امللــك فهــد الطبــي العســكري املتضمــن أنــه بالكشــف‬\n      ‫عليــه اثــر ادعــاء مضاربــة وجــد مصابـ ًا بتمــزق بفــروة الــرأس حوالــي ‪10‬‬\n      ‫ســم بآلــة غيــر حــادة ومــدة الشــفاء أســبوع واحــد وانتهــى التحقيــق إلــى‬\n      ‫اتهــام املدعــى عليهــا برمــي زوجهــا بــكأس زجــاج علــى رأســه ممــا أدى‬\n      ‫إلــى حــدوث اإلصابــات املوضحــة يف التقريــر الطبــي املشــار إليــه وذلــك‬\n                                                            ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬مــا ورد يف اســتجوابها املرفــق علــى اللفتــن رقــم (‪ . )8-7‬وســماع‬\n      ‫أقوالهــا األوليــة املدونــة علــى الصفحتــن رقــم (‪ )12-11‬مــن محضــر‬\n                                          ‫االســتدالل املرفــق علــى اللفــة رقــم (‪.)1‬‬\n      ‫‪ -2‬التقريــر الطبــي املنــوه عنــه واملرفــق علــى اللفتــن رقــم (‪ ))3.2‬وحيــث‬\n      ‫إن مــا أقدمــت عليــه املدعــى عليهــا وهــي بكامــل أهليتهــا املعتبرة شــرع ًا‬\n      ‫ـب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتهــا مبــا ُنســب‬          ‫فعــلٌ محـ ٌ‬\n                                                                    ‫ـرم ومعاقـ ٌ‬\n      ‫إليهــا واحلكــم عليهــا بعقوبــة تعزيريــة تزجرهــا وتــردع غيرهــا وبــاهلل‬\n      ‫التوفيــق وبســؤال املدعــى عليهــا أجابــت بقولهــا مــا ذكــره املدعــي‬\n\n\n‫‪105‬‬\n\f‫العــام مــن ضربــي للمدعــي بــكأس مــن زجــاج علــى رأســه ممــا أدى إلــى‬\n‫حــدوث إصابــات بــه فهــذا صحيــح وذلــك ألنــه رفــض ذهابــي إلــى خطبــة‬\n‫ابنتــي وقــام بإنزالــي مــن ســيارة األجــرة فغضبــت عليــه وضربتــه وقــد قــام‬\n‫املدعــي بتطليقــي هــذه إجابتــي ويف نفــس اجللســة حضــر املدعــي باحلــق‬\n‫اخلــاص ‪........‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )........‬وبســؤاله عــن‬\n‫دعــواه ادعــى بقولــه إن املدعــى عليهــا كانــت زوجتــي ويف يــوم مــن األيــام‬\n‫منعتهــا مــن الذهــاب يف ســيارة أجــرة ثــم ملــا دخلــت البيــت قامــت بضربــي‬\n‫بــكأس زجاجــي علــى رأســي ممــا أحــدث فيــه إصابــة أطلــب احلكــم‬\n‫بتأديبهــا لقــاء اعتداءهــا علــي بالضــرب هــذه دعــواي وبســؤال املدعــى‬\n‫عليهــا أجابــت بقولهــا مــا ذكــره املدعــي صحيــح فقــد قمــت بضربــه‬\n‫علــى رأســه بــكأس مــن زجــاج لقــاء منعــه لــي مــن الذهــاب إلــى حفلــة‬\n‫ابنتــي هــذه إجابتــي وبعــد تدويــن مــا ســبق جــرى محاولــة اإلصــاح بــن‬\n‫الطرفــن ومت بــذل الوســع يف ذلــك وســبق أن مت تأجيــل اجللســة الســابقة‬\n‫حملاولــة اإلصــاح بينهمــا عــن طريــق مكتــب الصلــح باحملكمــة ولكن‬\n‫بــا فائــدة حيــث رفضــا الصلــح وعليــه جــرى االطــاع علــى التقريــر‬\n‫الطبــي الصــادر مــن مجمــع امللــك فهــد الطبــي العســكري برقــم (‪)........‬‬\n‫واملتضمــن أنــه بالكشــف علــى ‪........‬تبــن وجــود متــزق بفــروة الــرأس‬\n‫حوالــي (‪10‬ســم) بآلــة غيــر حــادة ومــدة الشــفاء أســبوع واحــد فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــرت املدعــى عليهــا بضــرب‬\n‫املدعــي باحلــق اخلــاص واملــرء مؤاخــذ بإقــراره و حيــث بــاءت جميــع‬\n‫محــاوالت الصلــح بالفشــل وبنــاء علــى التقريــر الطبــي املشــار إليــه أعــاه‬\n‫وحيــث إن مــا قامــت بــه املدعــى عليهــا فعــل محــرم وفيــه اعتــداء علــى‬\n‫ســامة اآلخريــن وأمنهــم وحيــث إن موجــب ذلــك التعزيــر وحيــث حصــر‬\n\n\n                                                                                     ‫‪106‬‬\n\f      ‫املدعــي باحلــق اخلــاص مطالبتــه بتأديــب املدعــى عليهــا لــذا فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليهــا بضــرب املدعــي باحلــق اخلــاص بــكأس زجــاج‬\n      ‫علــى رأســه ممــا أدى إلــى حــدوث إصابــات بــه وحكمــت عليهــا مبــا يلي ‪:‬‬\n      ‫‪ /1‬ســجنها خمســة أيــام وجلدهــا خمــس جلــدات للحــق العــام ‪ /2‬ســجنها‬\n      ‫خمســة أيــام وجلدهــا خمــس جلــدات للحــق اخلــاص وبعــرض احلكــم‬\n      ‫علــى أطــراف الدعــوى قــرر املدعــي باحلــق اخلــاص قناعتــه بــه بينمــا‬\n      ‫قــررت املدعــى عليهــا عــدم القناعــة وطلبــت االســتئناف فأجيبــت لطلبهــا‬\n      ‫وأفهمــت باملراجعــة يــوم الثالثــاء املوافق ‪1434/3/17‬هـ الســتالم نســخة‬\n      ‫مــن احلكــم وتقــدمي اعتراضهــا عليــه خــال مهلــة ثالثــن يومــا وأنــه إذا‬\n      ‫انتهــت هــذه املهلــة ولــم تتقــدم باعتراضهــا ســقط حقهــا يف ذلــك وســوف‬\n      ‫يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة وقــرر املدعــي‬\n      ‫العــام عــدم االعتــراض وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه‬\n      ‫حــرر يف ‪1434/3/15‬هــ‪.‬ويف يــوم األحــد املوافــق ‪1434/5/5‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة الثامنــة وخمــس وأربعــن دقيقــة وقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف برقــم (‪ )34/969294‬وتاريــخ ‪1434/4/29‬ه ـ‬\n      ‫املتعلقــة بدعــوى املدعــي العــام واملدعــي اخلــاص ضــد‪ ......../‬وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم (‪ )34196942‬وتاريــخ‬\n      ‫‪1434/4/24‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى إحلــاق ذلــك‬\n      ‫حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه أجمعــن ‪ .‬احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n      ‫الدائ ــرة اجلـزائي ــة الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫علــى املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/969294‬ج‪2‬وتاريــخ‬\n      ‫‪1434/4/21‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة‬\n\n\n‫‪107‬‬\n\f‫الدمــام برقــم ‪ 331103132‬وتاريــخ ‪1434/4/15‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪........ /‬املســجل برقــم‬\n‫‪ 3462879‬وتاريــخ ‪1434/3/15‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫واملدعــي اخلــاص ضــد‪......../‬يف قضيــة ضــرب زوجهــا وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                           ‫وســلم‪ .‬حــرر يف ‪1434/4/23‬هــ‪.‬‬\n\n\n\n\n                                                                                ‫‪108‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":103,"source_page_end":108,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1f3c63258442ba5ed1db040731d84bcc932fea816fcb5a70e9599ad495432a41","normalized_text_hash":"7b220ca8f3a1a5c688c48e8746c9692e85d3b5de15c181221ae86d1a4776ab03","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p103-3462879"},{"id":"282be075-721d-5bee-b117-435bf1bd712c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -سب يف مجلس احلكم -الدفع املقدم مبواجهة دعوى قائمة أمام قاض ليس هو من قبيل الشتم أو التنقص أمام الغير - التعزير إمنا يكون بثبوت كذب الدفع ال مبجرد عدم قدرة اخلصم على إثباته -صرف النظر عن دعوى املدعية.","document_number":"33434658","case_number":"33409909","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة :أنها مصابة باضطرابات عقلية وأنها حاولت االنتحار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/22","year":"1434","subject":"إيذاء -سب يف مجلس احلكم -الدفع املقدم مبواجهة دعوى قائمة أمام قاض ليس هو من قبيل الشتم أو التنقص أمام الغير - التعزير إمنا يكون بثبوت كذب الدفع ال مبجرد عدم قدرة اخلصم على إثباته -صرف النظر عن دعوى املدعية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33434658 :‬تاريخه‪1433/10/22:‬هـ‬\n                          ‫رقم الدعوى‪33409909:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3439781‬تاريخه‪1434/2/8 :‬هـ‬\n\n\n\n      ‫إيــذاء‪ -‬ســب يف مجلــس احلكــم ‪ -‬الدفــع املقــدم مبواجهــة دعــوى قائمــة‬\n      ‫أمــام قــاض ليــس هــو مــن قبيــل الشــتم أو التنقــص أمــام الغيــر ‪-‬‬\n      ‫التعزيــر إمنــا يكــون بثبــوت كــذب الدفــع ال مبجــرد عــدم قــدرة اخلصــم‬\n                            ‫علــى إثباتــه ‪ -‬صــرف النظــر عــن دعــوى املدعيــة‪.‬‬\n\n\n\n\n      ‫‪-‬مــا جــاء يف أســنى املطالــب‪) :)177/20( :‬ومنهــا أن أحــد اخلصمــن إذا‬\n      ‫قــال لصاحبــه ‪ :‬إنــه ظالــم أو فاجــر أو نحــوه يف حــال املخاصمــة يحتمــل‬\n               ‫ذلــك منــه أي وال يعــزر عليــه ذكــره النــووي يف شــرح مســلم)‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة أن املدعــى عليــه اتهمهــا أثنــاء نظــر قضيــة حضانــة‬\n      ‫أوالدهمــا املنظــورة يف احملكمــة العامــة‪ :‬أنهــا مصابــة باضطرابــات‬\n      ‫عقليــة وأنهــا حاولــت االنتحــار‪ ،‬وأن ناظــر القضيــة خاطــب مستشــفى‬\n      ‫الصحــة النفســية ثــم حكــم لهــا باحلضانــة ‪ -‬تطلــب تأديــب املدعــى‬\n      ‫عليــه علــى ذلــك ‪ -‬بعــرض الدعــوى علــى املدعــى عليــه أجــاب أن هــذا‬\n      ‫ليــس اتهــام بــل هــو حقيقــة وأن مطلقتــه املدعيــة كانــت تشــتكي ممــا‬\n      ‫ذكــر وعنــده تقاريــر طبيــة تثبــت مــا ذكــره وقــد قدمهــا لناظــر دعــوى‬\n      ‫احلضانــة وهــو بــدوره قدمهــا للمستشــفى وقــد ورد جــواب املستشــفى‬\n\n‫‪109‬‬\n\f‫بــأن مــا جــاء يف التقريــر صحيــح لكــن احلالــة قدميــة ومتاثلــت للشــفاء‬\n‫ولديــه تقريــر املستشــفى هكــذا أجــاب‪ ،‬جــرى االطــاع علــى صــورة‬\n‫مــن احلكــم املشــار لــه املبــرز مــن املدعيــة املتضمــن ورود جــواب مجمــع‬\n‫األمــل املتضمــن‪ ،‬اطــاع اللجنــة الطبيــة علــى التقاريــر املقدمــة مــن‬\n‫الــزوج الســابق والصــادرة بحــق املــرأة واملتضمــن أنهــا تعانــي مــن قرابــة‬\n‫ســبع ســنوات مــن أعــراض اكتئابيــة وأنهــا حاليــا ال تعانــي مــن أمــراض‬\n‫عقليــة‪ ،‬نظــر ًا ألنــه جــاء يف التقريــر الطبــي مــا يشــير إلــى حالــة مرضيــة‬\n‫ســابقة متاثلــت للشــفاء‪ ،‬وألن دفــع املدعــى عليــه بــأن املدعيــة مريضــة‬\n‫نفســيا دفــع قــدم مبواجهــة دعــوى قائمــة أمــام قــاض شــرعي للنظــر يف‬\n‫األحــق بحضانــة أوالدهمــا وليــس هــو مــن قبيــل الشــتم أو التنقــص أمــام‬\n‫الغيــر يف املجالــس ونحوهــا وبنــاء علــى أنــه يحــق للمتداعيــن الدفــاع عــن‬\n‫حقوقهمــا مبــا ال يتضمــن اخلــروج عــن احلــدود الشــرعية يف الدفــاع وهــذا‬\n‫الدفــع ال خــروج فيــه عــن احلــدود الشــرعية‪ ،‬والتعزيــر إمنــا يكــون بثبــوت‬\n‫كــذب الدفــع ال مبجــرد عــدم قــدرة اخلصــم علــى إثباتــه لذلــك كلــه مت‬\n‫احلكــم بصــرف النظــر عــن الدعــوى لعــدم االســتحقاق وبعــرض احلكــم‬\n‫علــى املدعيــة قــررت عــدم القناعــة وطلبــت اإلســتئناف فأجيبــت لطلبها‪،‬‬\n            ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33409909‬وتاريــخ ‪ 1433/06/17‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331144256‬وتاريــخ ‪ 1433/06/17‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/10/17‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيها حضرت ‪ ........‬نســبة ملطلقها الســابق باكســتانية اجلنسية مبوجب‬\n      ‫جــواز الســفر رقم‪........‬الصــادر مــن باكســتان ومعهــا زوجهــا حســب‬\n      ‫تعريفهمــا ‪........‬باكســتاني اجلنســية هويــة رقــم ‪ ........‬وحضــر حلضورهــا‬\n      ‫‪ ........‬باكســتاني اجلنســية هويــة رقــم ‪........‬كمــا حضــر املترجــم‬\n      ‫الرســمي ‪........‬هنــدي اجلنســية بالهويــة رقــم ‪ ........‬وادعــت ‪ ......‬قائلــة أثناء‬\n      ‫خصومــة بينــي وبــن املدعــى عليــه يف احملكمــة العامــة بالريــاض علــى‬\n      ‫حضانــة أوالدنــا قــام املدعــى عليــه باتهامــي باننــي مصابــة باضطرابــات‬\n      ‫عقليــة وحاولــت االنتحــار حــن كنــا يف…‪ ..‬وســجل هــذا االتهــام يف‬\n      ‫احلكــم الصــادر مــن احملكمــة برقــم ‪ 32177946‬يف ‪1432/7/24‬‬\n      ‫مــن احملكمــة العامــة وقــد خاطــب ناظــر القضيــة مستشــفى الصحــة‬\n      ‫النفســية ثــم حكــم لــي باحلضانــة أطلــب تأديبــه علــى قذفــه لــي هــذه‬\n      ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا هــذا ليــس‬\n      ‫اتهــام هــذا حقيقــة ومطلقتــي كانــت تشــتكي ممــا ذكــر ولــي تقاريــر‬\n      ‫طبيــة تثبــت مــا ذكرتــه وقــد قدمتهــا لناظــر دعــوى احلضانــة وهــو بــدوره‬\n      ‫قدمهــا للمستشــفى وقــد ورد جــواب املستشــفى بــأن مــا جــاء يف التقريــر‬\n      ‫صحيــح لكــن احلالــة قدميــة ومتاثلــت للشــفاء ولــدي تقريــر املستشــفى‬\n\n‫‪111‬‬\n\f‫هكــذا أجــاب وجــرى اطالعــي علــى صــورة مــن احلكــم املشــار لــه علــى‬\n‫لســان الطرفــن والصــورة قدمــت لــي مــن املدعية فوجدتهــا تتضمن ورود‬\n‫جــواب املديــر التنفيــذي ملجمــع االمــل رقــم ‪........‬يف ‪ 1432/6/26‬ومــن‬\n‫ضمــن مــا جــاء اطــاع اللجنــة الطبيــة علــى التقاريــر املقدمــة مــن الــزوج‬\n‫الســابق والصــادرة بحــق املــرأة وجــاء يف التقريــر مــا نصــه تبــن أنهــا‬\n‫تعانــي مــن قرابــة ســبع ســنوات مــن أعــراض اكتئابيــة ســابقة كمــا جــاء‬\n‫يف التقريــر أن املذكــورة حالي ـ ًا ال تعانــي مــن أمــراض عقليــة انتهــى مــا‬\n‫يحتــاج إليــه بنــاء علــى مــا تقــدم وحيــث قــد جــاء يف التقريــر الطبــي مــا‬\n‫يشــير الــى حالــة مرضيــة ســابقة متاثلــت للشــفاء وهــذا لوحــده كاف يف‬\n‫احلكــم ولــو لــم يوجــد هــذا اجلــواب يف التقريــر الطبــي فــإن دفــع املدعــى‬\n‫عليــه بــأن املدعيــة مريضــة نفســيا دفــع قــدم مبواجهــة دعــوى قائمــة أمــام‬\n‫قــاض شــرعي للنظــر يف االحــق بحضانــة أوالدهمــا وليــس هــو مــن قبيــل‬\n‫الشــتم أو التنقــص أمــام الغيــر يف املجالــس ونحوهــا وبنــاء علــى أنــه يحــق‬\n‫للمتداعيــن الدفــاع عــن حقوقهمــا مبــا ال يتضمــن اخلــروج عــن احلــدود‬\n‫الشــرعية يف الدفــاع وهــذا الدفــع ال خــروج فيــه عــن احلــدود الشــرعية‬\n‫جــاء يف أســنى املطالــب ‪( -‬ج ‪ / 20‬ص ‪ )177‬ومنهــا أن أحــد اخلصمــن‬\n‫إذا قــال لصاحبــه ‪ :‬إنــه ظالــم أو فاجــر أو نحــوه يف حــال املخاصمــة‬\n‫يحتمــل ذلــك منــه أي وال يعــزر عليــه ذكــره النــووي يف شــرح مســلم)‬\n‫انتهــى والتعزيــر امنــا يكــون بثبــوت كــذب الدفــع ال مبجــرد عــدم قــدرة‬\n‫اخلصــم علــى إثباتــه لذلــك كلــه حكمــت بصــرف النظــر عــن الدعــوى‬\n‫لعــدم االســتحقاق وبعــرض احلكــم علــى املدعيــة قــررت عــدم القناعــة‬\n‫وطلبــت االســتئناف فأجبتهــا لطلبهــا وأفهمتهــا بنظــام االعتــراض ثالثــن‬\n‫يومــا مــن تاريــخ طباعــة احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n                                                                                      ‫‪112‬‬\n\f      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/17‬ه ـ احلمــد‬\n      ‫هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪ 1433/11/13‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 01:45‬وقــد ســلمت املدعــى عليهــا الئحــة اعتراضية ورد‬\n      ‫فيهــا أنهــا تطعــن يف التقريــر الطبــي بأنــه مــزور وأنهــا طلبــت صــورة منــه‬\n      ‫مــن قاضــي احملكمــة العامــة ولــم يعطهــا وقدمــت قرائــن تــدل علــى أنــه‬\n      ‫مــزور مــن قبــل اســتحصالها علــى رخصــة قيــادة وعمــل ونحــوه وهــي أدلــة‬\n      ‫ال أرى أنهــا تــدل علــى التزويــر كمــا إن املدعــى عليها ذكرت بأن لديها‬\n      ‫شــهودا علــى أنهــا ليســت مريضــة نفســيا وهــذه أيضــا ال تأثيــر لهــا علــى‬\n      ‫احلكــم فشــهود النفــي هنــا شــهادتهم نفي مطلــق يف الزمان واملكان وال‬\n      ‫تقبــل لذلــك وبنــاء علــى أن التعزيــر إمنــا يكــون بثبــوت كــذب الدعــوى ال‬\n      ‫مبجــرد عــدم قــدرة اخلصــم علــى إثباتهــا لذلــك الزلــت علــى مــا حكمــت‬\n      ‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪ 1433/11/13‬ه ـ احلمــد هلل وحــده وبعــد ‪ ...‬فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة‬\n      ‫االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 331144256‬وتاريــخ ‪1434/1/12‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪........ /‬‬\n      ‫املســجل برقــم ‪ 33434658‬وتاريــخ ‪1433/10/22‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعيــة املــرأة ‪........ /‬ضــد ‪ (........ /‬باكســتانيي اجلنســية ) بشــأن مــا‬\n      ‫تدعــي بــه املدعيــة مــن قيــام املدعــى عليــه بالتلفــظ عليهــا وتطلــب تأديبــه‬\n      ‫علــى النحــو املوضــح بالصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل بــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n\n\n‫‪113‬‬\n\f‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                ‫‪114‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":109,"source_page_end":114,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cd158ba7bcaa8daa5af604b8fd09a3d3fabdb196b1948e6ac9cf463e8a664891","normalized_text_hash":"20841d91e97267d9292acb57e060337f08a2690c97161ca8718d907ecee02c45","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p109-33434658"},{"id":"82cd02b9-1cef-5751-98da-e86a9ded5e49","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعتداء -إتاف ملك الغير -انتحال شخصية الغير -دعوى عامة وخاصة -رجوع عن إقرار -وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا","document_number":"34234520","case_number":"33458139","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"إعتداء -إتاف ملك الغير -انتحال شخصية الغير -دعوى عامة وخاصة -رجوع عن إقرار -وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك ‪34234520 :‬تاريخه‪1434/6/7:‬هـ‬\n                          ‫رقم الدعوى‪33458139:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34279806‬تاريخه‪1434/7/25:‬هـ‬\n\n\n\n      ‫إعتــداء ‪ -‬إتــاف ملــك الغيــر ‪ -‬انتحــال شــخصية الغيــر ‪ -‬دعــوى عامــة‬\n      ‫وخاصــة ‪ -‬رجــوع عــن إقــرار ‪ -‬وجــود ســوابق قضائيــة ‪ -‬ثبــوت إدانــة‬\n      ‫املدعــى عليــه ‪ -‬تعزيــر بالســجن واجللــد وأخــذ تعهــد بعــدم العــودة ملــا‬\n                                                                           ‫بــدر منــه‪.‬‬\n\n\n\n      ‫‪-1‬قــول النبــي صلــى اهلل عليــه وســلم « كل املســلم علــى املســلم حــرام‬\n                                                ‫دمــه ومالــه وعرضــه» أخرجــه مســلم ‪.‬‬\n      ‫‪ -2‬حديــث جابــر ‪ -‬رضــي اهلل عنــه‪ -‬أن النبــي صلــى اهلل عليــه وســلم‬\n                          ‫قــال‪« :‬إن دماءكــم وأموالكــم حــرام» أخرجــه مســلم‪.‬‬\n      ‫‪-3‬حديــث أبــي هريــرة ‪-‬رضــي اهلل عنــه‪: -‬أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫تلع ُنــه ح َّتــى وإن‬            ‫قــال‪« :‬مــن أشــار إلــى أخيــه بحديــد ٍة ‪ ،‬فـ َّ‬\n                         ‫ـإن املالئك ـ َة َ‬\n                                          ‫وأمــه» أخرجــه مســلم‪.‬‬\n                                                              ‫كان أخــاه ألبيــه ِّ‬\n\n\n\n      ‫جــرى توجيــه اإلتهــام مــن اإلدعــاء العــام للمدعــى عليــه ‪ ،‬بعــد تلقــي‬\n      ‫بــاغ مــن املعتــدى عليــه واإلنتقــال للموقــع ومشــاهدة اإلطــارات مقطعــة‬\n      ‫واســتجوابه وســماع شــهادة الشــاهد ‪،‬لقيامــه بإتــاف إطــارات ســيارة‬\n      ‫املدعــي وقطــع التيــار الكهربائــي عــن منزلــه وانتحــال شــخصية الغيــر‬\n\n‫‪115‬‬\n\f‫‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة‬\n‫وادعــى عطفـ ًا علــى مــا ا ّدعــى بــه املدعــي‬\n                                             ‫عليــه ‪ ،‬حضــر املدعــي اخلــاص ّ‬\n‫العــام وطلــب إيقــاع العقوبــة التعزيريــة عليــه علــى قيامــه بقطــع التيــار‬\n‫الكهربائــي عنــه وطلــب إلزامــه بدفــع قيمــة اإلطــارات وقيمــة حتميــل‬\n‫ســيارته للورشــة ‪ ،‬رفــض املدعــى عليــه يف أول جلســة اإلجابــة وطلــب‬\n‫إحالــة املعاملــة إلــى أمــارة املنطقــة للتحقيــق يف القضيــة للشــفافية يف‬\n‫إجــراءات التحقيــق ‪ ،‬تقــدم أحــد الشــهود للشــهادة وأفــاد بقيــام املدعــى‬\n‫عليــه بالتعــدي علــى املجنــي عليــه وإحــداث تلفيــات ‪ ،‬قــام املدعــى عليــه‬\n‫بانتحــال شــخصية أخــرى حــن قبــض عليــه ‪ ،‬رجــع املدعــى عليــه عــن‬\n‫إقــراره بإنــكار الفعــل املؤثــم ‪ ،‬طلــب املدعــى اخلــاص تأديــب املدعــى‬\n‫عليــه وأفــاد بتنازلــه عــن قيمــة اإلطــارات ولكثــرة ســوابق املدعــى‬\n‫عليــه ممــا يســتوجب تشــديد العقوبــة عليــه وملجمــوع مــا تقــدم قــررت‬\n‫احملكمــة إثبــات إدانــة املدعــى عليــه باإلعتــداء علــى املدعــي اخلــاص‬\n‫بتقطيــع إطــارات ســيارته وإطفــاء الكهربــاء عــن منزلــه وانتحــال‬\n‫شــخصية غيــره وقــررت تعزيــره ألجلــه ولكثــرة ســوابقه بســجنه ســنة‬\n‫مــن تاريــخ إيقافــه مناصفــة بــن احلــق العــام واخلــاص يبــدأ أوال باحلــق العام‬\n‫ثــم اخلــاص وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات متســاوية‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا خمســة عشــر‬\n‫يومــا مناصفــة أيضــا بــن احلــق العــام واخلــاص ويبــدأ أوال باحلــق العــام‬\n‫كمــت ‪،‬‬   ‫وأخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه ومبــا ســبق َح َ‬\n‫بعــرض احلكــم علــى األطــراف قــرر املدعــي اخلــاص القناعــة بينمــا قــرر‬\n‫املدعــي العــام اإلعتــراض بــدون الئحــة وأمــا املدعــى عليــه فاإلعتــراض‬\n                       ‫بالئحــة ‪ ،‬صــدق احلكــم مــن محكمــة اإلســتئناف‪.‬‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33458139‬وتاريــخ ‪ 1433/12/26‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331297260‬وتاريــخ ‪ 1433/07/12‬ه ـ ففــي يــوم‬\n      ‫السبت املوافق‪ 1434/01/10‬هـ افتتحت اجللسة الساعة ‪ 09 : 45‬وفيها‬\n      ‫حضــر املدعــي العــام ‪ ..............‬ولــم يحضــر املدعــى عليــه لعــدم تبلغــه‬\n      ‫مبوعــد اجللســة لــذا رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي العام‬\n      ‫‪ ..........‬وادعــى قائــا‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة عنيــزة أدعــي علــى‪ ................ :‬البالــغ مــن العمــر (‪)48‬‬\n      ‫عامــا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )..........‬عــزب‬\n      ‫‪ ،‬متعلــم ‪ ،‬يقيــم يف محافظــة عنيــزة قبــض عليــه بتاريــخ ‪1433/5/4‬ه ـ‬\n      ‫وأفــرج عنــه بالكفالــة بتاريخ ‪1433/5/26‬هـ ‪.‬إنــه بتاريخ ‪1433/5/3‬هـ‬\n      ‫ورد بــاغ لشــرطة احملافظــة مــن املواطــن ‪ ، ........... /‬مفــاده ‪ /‬تعــرض‬\n      ‫إطــارات ســيارته للقطــع بســكني وإطفــاء طبلــون الكهربــاء عــن منزلــه‬\n      ‫مــن قبــل املدعــى عليــه ‪.‬وباالنتقــال للموقــع وجــدت ســيارة املدعــي مــن‬\n      ‫نــوع ‪ ...........‬ولوحــظ أن إطاراتهــا األربعــة مقطوعــة بســكني ‪.‬وبســماع‬\n      ‫شــهادة املواطــن ‪ ، ........... /‬أفــاد بأنــه شــاهد املدعــى عليــه يقــوم بتنســيم‬\n      ‫كفــرات املدعــي بســكني وقيامــه بإطفــاء الكهربــاء عــن منــزل‬\n      ‫املدعي‪.‬وباســتجوابه ‪ :‬أقــر بتقطيــع إطــارات ســيارة املدعــي وإطفــاء‬\n      ‫الكهربــاء عــن منزلــه وانتحــال شــخصية شــخص يدعــى ‪.............. /‬‬\n      ‫وانتهــى التحقيــق معــه إلــى اتهامــه بإتــاف إطــارات ســيارة املدعــي وقطع‬\n\n‫‪117‬‬\n\f‫الكهربــاء عــن منزلــه وانتحــال شــخصية الغير‪.‬وذلــك لألدلــة و القرائــن‬\n‫التاليــة ‪ -1:‬اعترافــه مبــا أســند إليــه املــدون علــى الصفحــة رقــم (‪)8‬‬\n‫مــن ملــف إجــراءات االســتالل رقــم (‪-2.)1‬شــهادة الشــاهد املدونــة علــى‬\n‫الصفحــة رقــم (‪ )3‬مــن اللفــة (‪-3.)1‬إقــراره املرفــق لفــه (‪-4.)6‬محضــر‬\n‫االنتقــال و املعاينــة املــدون علــى الصفحــة رقــم (‪ )1‬مــن ملــف إجــراءات‬\n‫االســتدالل لفــه رقــم (‪.)1‬وبالبحــث عمــا إذا كان لــه ســوابق عثر له على‬\n‫ثمــان ســوابق منهــا أربــع ســوابق ســرقة وأربــع ســوابق شــرب مســكر ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫‪ ،‬أطلــب إثبــات إدانتــه مبــا أســند إليــه و احلكــم عليــه بعقوبــة تعزيريــة‬\n‫تزجــره وتــردع غيــره وتشــديد العقوبــة عليــه لقــاء ســوابقه التــي لــم تردعه‬\n‫عقوبتهــا ‪.‬علمــا بــأن احلــق اخلــاص لــم ينتــه‪ .‬وادعــى املدعــي اخلــاص بقولــه‬\n‫أننــي أضــم دعــواي مــع املدعــي العــام وأطلــب معاقبتــه لقــاء مــا قــام به من‬\n‫إطفــاء الكهربــاء وقيمــة إتــاف اإلطــارات وقيمــة حتميــل ســيارتي إلــى‬\n‫الورشــة هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫أجــاب بقولــه أننــي أرفــض اإلجابــة علــى دعــوى املدعــي العــام واملدعــي‬\n‫اخلــاص وأطلــب إرســال معاملتــي إلــى إمــارة منطقــة القصيــم للتحقيــق‬\n‫يف املوضــوع هكــذا أجــاب ويف نفــس اجللســة حضــر ‪ .............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬وبســؤاله عمــا لديــه مــن‬\n‫شــهادة شــهد هلل بأنــه بالتاريــخ املذكــور يف الدعــوى وبعــد صــاة الظهــر‬\n‫بزمــن ســمعت صــوت طــق قــوي فلمــا خرجــت مــن بيتــي وجــدت املدعــى‬\n‫عليــه يقــوم بتقطيــع كفــرات ســيارة املدعــى اخلــاص فلمــا انتهــى قــام‬\n‫بطــرق بــاب جــاري وهــو املدعــي اخلــاص بســكن فلمــا ذهــب الغضــب‬\n‫عنــه مســكته وقــال أننــي ســأقتل صاحــب املنــزل هكــذا شــهد ولتأمــل‬\n\n\n                                                                                       ‫‪118‬‬\n\f      ‫القضيــة رفعــت اجللســةويف جلســة أخــرى حضراملدعــى العــام واملدعــى‬\n      ‫اخلــاص وحضــر حلضــوره املدعــى عليــه وجــرى ســؤال املدعــى عليــه هــل‬\n      ‫أحضــر إجابــة علــى الدعــوى فأبــرز ورقتــن هــذا نصهــا فأننــي أتقــدم‬\n      ‫لســماحتكم يف النظــر مبوضوعــي بعــن احلــق والعــدل واملســاوا ة وذلــك‬\n      ‫حيــث انــه قــد مت النظــر يف هــذه القضيــة مــن قبــل رئيــس احملكمــة يف‬\n      ‫‪1433 /9 /26‬هـ وقد مت توجيه رئيس احملكمة بخطاب رســمي وذلك‬\n      ‫للتحقيــق بدعــواي ضــد جــاري ‪ .....‬ملــا يوجــد لــدي مــن شــهود ضــده وهــم‬\n      ‫عســكري يف الشــرطة لقيامــة بســرقة منزلــي وأنــا موقــوف يف الشــرطة‬\n      ‫علــى ذمــة قضيــة بنشــر ســيارته املتوقفــة أمــام منزلــي علما بأننــي تقدمت‬\n      ‫إلــى عــدة ضبــاط ‪ 2‬وثالثهــم ضابــط الــذي قــد حقــق معــي ورفــض دعــواي‬\n      ‫عــدة مــرات ملــا بينــي ويوضــح معرفتــه خلصمــي والــدالل كثيــرة عليــه مبا‬\n      ‫يخــص حتيــزه وعــدم تنفيــذ االجــراءات القانونيــة وعــدم التحقيــق معــه‬\n      ‫وإشــعار جميــع الضبــاط بذلــك لــذى فانــي ارفــع تظلمــي إليكــم وأطالب‬\n      ‫برفــع كامــل األوراق إلــى أمــارة منطقــة القصيــم إلجــراء التحقيــق معــي‬\n      ‫ومــع ضبــاط القضيــة ‪ ........‬وخصمــي ‪ .........‬إلظهــار كافــة احلقــوق‬\n      ‫مــن كل جانــب وليــس مــن بــاب الواســطة واملعرفــة وقيامــه بتخريــب‬\n      ‫ممتلكاتــي وتكســير مواســير امليــاه بداخــل منزلــي وإتــاف إقفــال‬\n      ‫األبــواب اخلارجيــة عــدد ‪ 3‬أبــواب وإتــاف صحــن االســتقبال ورمــي‬\n      ‫حجــارة خرســانة وقــد رميــت مــن منزلــه علــى منزلــي وهــي موجــودة إلــى‬\n      ‫اآلن وكذلــك ســرقته خــزان امليــاه مــن داخــل منزلــي بواســطة رافعــة‬\n      ‫وكذلــك إفســاده زواجــي وهدمــه ملــا احــل اهلل مــن حــال باألكاذيــب‬\n      ‫وذلــك ألجــل االســتيالء علــى منزلــي باإلكــراه هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــى العــام واملدعــي اخلــاص أفــاد كل واحــد مبفــرده‬\n\n\n‫‪119‬‬\n\f‫إننــا مازلنــا علــى طلبنــا الســابق هكــذا أفــادوا ولتأمــل القضيــة رفعــت‬\n‫اجللســة احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n‫العامــة بعنيــزة افتتحــت اجللســة الســاعة احلاديــة عشــرة والنصــف صباحــا‬\n‫وفيهــا حضــر املدعــي العــام واملدعــي باحلــق اخلــاص واملدعــى عليــه‬\n‫وبتصفحــي للمعاملــة اطلعــت علــى محضــر االنتقــال واملعاينــة املــدون‬\n‫علــى الصفحــة ‪ 1‬مــن اللفــة ‪ 1‬مــن املعاملــة فوجدتــه يتضمــن مــا نصــه‬\n‫إنــه يف متــام الســاعة الرابعــة والنصــف يف مســاء يــوم االثنــن املوافــق‬\n‫‪1433/5/3‬ه ـ مت االنتقــال إلــى حــي الفيحــاء بعنيــزة وذلــك لوجــود بــاغ‬\n‫‪ ...........‬بشــأن تعــرض إطــارات ســيارته للقطــع بســكني وباالنتقــال‬\n‫وجــدت الســيارة مــن نــوع ‪ ...........‬واتضــح أن الكفــرات األربــع مقطوعــة‬\n‫بســكني وجميعهــن يف وضــع التنســيم ومت تصويرهــن ولــم يعثــر علــى‬\n‫آثــار تفيــد التحقيــق وحفظــا للواقــع جــرى إعــداد هــذا احملضــر انتهــى‬\n‫رقيــب ‪ .............‬توقيعــه نقيــب ‪ ................‬توقيعــه وعنــد وصــول القضيــة‬\n‫لهــذا احلــد رفعــت اجللســة للنطــق باحلكــم ‪ .‬احلمــد هلل وحــده وبعــد فلــدي‬\n‫أنــا ‪ ...............‬رئيــس احملكمــة العامــة بعنيــزة القائــم بعمــل فضيلــة‬\n‫القاضــي ‪ ..................‬أثنــاء تكليفــه بــدورة رســمية ففــي يــوم االثنــن‬\n‫املوافــق ‪ 1434/05/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ ............‬واملدعــي اخلــاص ‪ ..............‬واملدعــى عليــه‬\n‫وصــادق املدعيــان علــى مــا نســب لهمــا يف الدعــوى وجــرى ســؤال املدعــى‬\n‫عليــه عمــا ورد يف دعــوى املدعيــان فأجــاب قائــا مــا ذكــره املدعيــان يف‬\n‫دعواهمــا فكلــه غيــر صحيــح فلــم أتعــرض جلــاري املدعــي ‪ ...........‬بــأي‬\n‫ســوء وهــذه دعــوى كيديــه مــن أجــل أن يجبرنــي علــى بيــع اســتراحتي‬\n‫هكــذا أجــاب فســألت املدعيــان هــل لديهمــا زيــادة بينــة فأجابــا بأنــه‬\n\n\n                                                                                        ‫‪120‬‬\n\f      ‫ليــس لديهمــا ســوى مــا قدمــاه يف هــذه الدعــوى ويكتفيــان بــه هكــذا‬\n      ‫أجابــا وللتأمــل رفعــت اجللســة احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...............‬‬\n      ‫القاضــي املنتــدب املكلــف باملكتــب القضائــي اخلامــس يف احملكمــة‬\n      ‫العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بعنيــزة برقــم ‪ 33458139‬وتاريــخ ‪ 1433/12/26‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331297260‬وتاريــخ ‪ 1433/07/12‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/06/03‬ه ـ افتتحــت اجللســة الســابعة وفيهــا‬\n      ‫حضــر جميــع االطــراف املدعــي باحلــق العــام واملدعــي باحلــق اخلــاص‬\n      ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬واملدعــى‬\n      ‫عليــه وقــد جــرى منــي تــاوة مــامت ضبطــه ســابقا علــى جميــع أطــراف‬\n      ‫الدعــوى فصادقــوا عليــه جميعــا وقــرر املدعيــان باحلــق العــام واحلــق‬\n      ‫اخلــاص بقولهمــا إننــا مازلنــا علــى طلبنــا بتأديبــه لقــاء هــذه األعمــال‬\n      ‫كمــا أضــاف املدعــي باحلــق اخلــاص أننــي أطالــب بتعويضــي عــن‬\n      ‫تلفيــات اإلطــارات وقيمــة حمــل ســيارتي وأمــا بالنســبة للمدعــى عليــه‬\n      ‫فقــد صــادق علــى إنــكاره وقــرر قائــا ماذكــره املدعيــان يف دعواهمــا‬\n      ‫ضــدي فغيــر صحيــح جملــة وتفصيــا ثــم جــرى منــي ســؤال املدعــى عليــه‬\n      ‫عــن شــهادة الشــاهد فقــال غيــر صحيحــه فســألته عــن الشــاهد فقــال‬\n      ‫لــم أشــاهده يصلــي يف املســجد إطالقــا فســألته هــل بينــك وبينــه أي‬\n      ‫عــداوة فقــال ال فســألت املدعــي باحلــق اخلــاص هــل لديــك زيــادة بينــه‬\n      ‫فقــال ليــس لــدي ســوى مــا أحضــرت ومــا جــاء يف الئحــة املدعــي العــام‬\n      ‫فطلبــت منــه معدلــن لشــاهده فوعــد بإحضارهــم يف اجللســة القادمــة ثــم‬\n      ‫جــرى منــي االطــاع علــى أدلــة املدعــى العــام ومــن ذلــك إقــرار املدعــى‬\n      ‫عليــه املــدون علــى الصفحــة رقــم ‪ 8‬مــن اللفــة رقــم (‪ )1‬وهــذا نصــه (( أقــر‬\n\n\n‫‪121‬‬\n\f‫أنــا ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...........‬بأننــي‬\n‫انتحلــت شــخصية ‪ ............. /‬وذلــك ألنــه مت القبــض علــي وأنــا بحالــة‬\n‫غيــر طبيعيــة واخبرتهــم بــأن أســمي ‪ ................‬وهــذا غيــر صحيــح ألننــي‬\n‫أعــرف هــذا الشــخص حيــث كان يعمــل معــي بحــراج الريــاض وأعــرف‬\n‫أســمه رباعيــا وليــس لــي أي قصــد مــن هــذا كمــا أقــر وأعتــرف بأننــي‬\n‫قمــت بتقطيــع إطــارات ســيارة املدعــو‪ .........../‬األربــع وإطفــاء الكهربــاء‬\n‫علــى منزلــه وذلــك بســبب إيقــاف ســيارته أمــام االســتراحة اخلاصــة بــي‬\n‫وهــذا إقــرار منــي بذلــك وعليــه جــرى التوقيــع )) بصمتــه وبعرضــه علــى‬\n‫املدعــى عليــه قــال مــاورد فيــه غيــر صحيــح فســألته عــن ذلــك فقــال‬\n‫لــم أقــل مــا فيــه وقــد وقعــت عليــه ولــم أقــرأ مــا فيــه كمــا جــرى منــي‬\n‫عــرض اســتجوابه املــدون علــى الصفحــة رقــم ‪ 6‬مــن اللفــة رقــم ‪ 1‬وهــذا‬\n‫نصــه ((س‪ /‬ملــاذا قمــت بقطــع إطــارات ســيارة املدعــو ‪ .......‬؟ ج‪ /‬بســبب‬\n‫وقوفــه أمــام اســتراحتي وقــد حذرتــه بعــدم الوقــوف وهــو يرغــب بشــراء‬\n‫االســتراحة بالغصــب منــي وأنــا أرفــض ذلــك ‪ .‬س‪ /‬هــل قمــت بإطفــاء‬\n‫الكهربــاء عليــه ؟ ج‪ /‬نعــم ‪.‬س‪ /‬ملــاذا قمــت بتقطيــع الكفرات بســكني‬\n‫؟ ج‪ /‬ألنــه يرفــض اخلــروج وإخــراج ســيارته عــن بــاب اســتراحتي وقمــت‬\n‫بتقطيــع كفــرات ســيارته وإطفــاء الكهربــاء عليــه )) بصمتــه وبعرضــه‬\n‫عليــه قــال بصمــت عليــه ولــم أقــرأ مــا فيــه ومــا ورد فيــه غيــر صحيــح‬\n                        ‫هكــذا أجــاب والنتهــاء وقــت اجللســة رفعــت اجللســة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬ويف هــذه اجللســة حضــر جميــع‬\n‫األطــراف ثــم جــرى منــي ســؤال املدعــي باحلــق اخلــاص ‪ ............‬عــن‬\n‫ال مــن ‪ ...........‬ســعودي اجلنســية مبوجــب‬   ‫معدلــن للشــاهد فأحضــر ك ً‬\n‫الســجل املدنــي رقــم ‪...........‬و ‪ .............‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n                                                                                          ‫‪122‬‬\n\f      ‫املدنــي رقــم ‪ ..............‬وبســؤالهما عمــا لديهمــا شــهد كل واحــد منهمــا‬\n      ‫مبفــرده بقولــه أشــهد بــاهلل إن الشــاهد ثقــة عــدل مقبــول الشــهادة‬\n      ‫ا إننــي متنــازل عــن‬    ‫هكــذا شــهدا ثــم قــرر املدعــي باحلــق اخلــاص قائ ـ ً‬\n      ‫قيمــة إطــارات الســيارة وقيمــة حملهــا إلــى الورشــة وأطلــب فقــط تأديبــه‬\n      ‫علــى ذلــك هكــذا قــرر فبعــد ســماع الدعــوى واإلجابــة واالطــاع علــى‬\n      ‫أوراق املعاملــة ونظــر ًا إلنــكار املدعــى عليــه لدعــوى املدعــي العــام جملــة‬\n      ‫ا وبالنظــر ملــا قدمــه املدعــي العــام مــن بينــات موصلــة علــى‬            ‫وتفصي ـ ً‬\n      ‫دعــواه متمثلــة يف إقــرارات املدعــى عليــه حتقيق ـ ًا والتــي دون مضمونهــا‬\n      ‫يف اجللســة الســابقة وقــد جــرى منــي عرضهــا علــى املدعــى عليــه أال أنــه‬\n      ‫دفــع بعــدم صحتهــا وأنــه وقــع عليهــا ولــم يقــرأ مــا فيهــا وألن مــا دفــع‬\n      ‫بــه املدعــى عليــه دفــع وا ٍه وضعيــف وال ميكــن األخــذ بــه إذ لــو أخــذ بــه‬\n      ‫لضاعــت احلقــوق وألصبــح مثــل هــذا منهج ـ ًا لضعــاف النفــوس إلنــكار‬\n      ‫احلقــوق وال صــارت الكتابــة التــي أمــر اهلل بهــا ال فائــدة منهــا واملدعــى‬\n      ‫عليــه لــم يدفــع بدعــوى إكــراه أو إجبــار أوغيــره ممــا يعتبــر يف الشــريعة‬\n      ‫اإلســامية وقــد نــص الفقهــاء رحمهــم اهلل علــى أن مــن ألــزم نفســه‬\n      ‫بشــيء ألــزم بــه فكونــه لــم يقــرأ هــذا ال يعفيــه أبــد ًا مــن اإلدانــة ثــم أيضـ ًا‬\n      ‫بالنظــر إلــى لألدلــة ومــا يقويهــا فشــهادة الشــاهد صريحــة بذلــك ونظــر ًا‬\n      ‫ألن الرجــوع عــن اإلقــرار يف حقــوق اهلل التــي ال تــدرأ بالشــبهات ال يقبــل‬\n      ‫نــص علــى ذلــك يف شــرح منتهــى اإليــرادات (‪ )340/4‬وابــن قدامــه يف‬\n      ‫املغنــى (‪ )96/5‬وقــال ال نعلــم فيــه خالفـ ًا ويدخــل دخــو ًال أوليــا وقــد نــص‬\n      ‫عليــه الفقهــاء أيض ـ ًا احلقــوق املتعلقــة بالعبــاد واملبنيــة علــى املشــاحة ال‬\n      ‫املســاملة وحلرمــة هــذه األفعــال يف الشــريعة اإلســامية وملــا فيهــا مــن إثــارة‬\n      ‫الرعــب يف اآلمنــن واســتخفاف يف هــذه النعمــة العظيمــة وجتــرؤ عليهــا‬\n\n\n‫‪123‬‬\n\f‫وملــا يف هــذا الفعــل مــن اعتــداء علــى املســلم وقــد نهــى النبــي صلــى اهلل‬\n‫عليــه وســلم عــن ذلــك فقــد قــال علــي الصــاة والســام (كل املســلم‬\n‫علــى املســلم حــرام دمــه ومالــه وعرضــه ) أخرجــه مســلم وقــد قــال عليــه‬\n‫الصــاة والســام (إن دمائكــم وأموالكــم وأعراضكــم عليكــم‬\n‫حــرام ) وقــال عليــه الصــاة والســام (مــن أشــار إلــى أخيــه بحديــده )‬\n‫واألدلــة احملــذرة مــن هــذا الفعــل كثيــرة ثــم بالنظــر ملاضــي املدعــى عليــه‬\n‫وتعــدد ســوابقه واســتمراء اجلرميــة يف نفســه ممــا يســتلزم منــه تشــديد‬\n‫العقوبــة يف حقــه ملــا ســبق كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪.........‬‬\n‫باالعتــداء علــى أخيــه املســلم ‪ ............‬بتقطيــع كفــرات ســيارته وإطفــاء‬\n‫الكهربــاء عــن منزلــه وبانتحــال شــخصية الغيــر وقــررت تعزيــره علــى‬\n‫ذلــك مــع األخــذ باالعتبــار ســوابقه املتعــددة بســجنه ســنة حتســب منهــا‬\n‫مــدة اإليقــاف مــا لــم يكــن مســجون ًا يف قضيــة أخرى فتبدأ مدة الســجن‬\n‫هــذه بعــد انتهــاء القضيــة املســجون بســببها ويكــون الســجن مناصفــة‬\n‫بــن احلقــن العــام واخلــاص يبــدأ أوال باحلــق العــام وبجلــده ثالثمائــة جلــدة‬\n‫مفرقــه علــى ســت فتــرات متســاوية بواقــع خمســن جلــده يف كل فتــرة‬\n‫بــن كل فتــرة واألخــرى خمســة عشــر يومـ ًا مناصفــة بــن احلقــن العــام‬\n‫واخلــاص ويبــدأ أو ًال باحلــق العــام وبأخــذ التعهــد عليــه بعــدم العــودة ملثــل‬\n‫مــا بــدر منــه ومبــا ســبق كلــه حكمــت وبعــرض احلكــم علــى جميــع‬\n‫األطــراف قــرر املدعــي العــام االعتــراض مكتفي ـ ًا مبــا جــاء يف الئحــة‬\n‫الدعــوى كمــا قــرر املدعــي باحلــق اخلــاص قناعتــه باحلكم وقــرر املدعى‬\n‫عليــه اعتراضــه علــى احلكــم بالئحــة اعتراضيــة فجــرى منــي تســليمه‬\n‫ـراض عليــه خــال ثالثــن يومـ ًا مــن تاريــخ هــذا‬   ‫نســخة مــن القــرار لالعتـ ِ‬\n‫اليــوم وأفهمتــه بأنــه إذا لــم يتقــدم باعتراضــه خــال هــذه املــدة فــإن حقــه‬\n\n\n                                                                                           ‫‪124‬‬\n\f      ‫يف تقــدمي الالئحــة يســقط وترفــع املعاملــة حملكمــة االســتئناف ففهــم‬\n      ‫ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪ 1434/06/07‬هــ‪ .‬احلمــد هلل وحــده وبعــد فقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف برفقهــا قــرار احملكمــة ومضمونــه‬\n                                                         ‫املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪125‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":115,"source_page_end":125,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"abf4ecf146b65bd4360b94cec155ef2b4332a0057038c0cf9cab4c0b28109ef9","normalized_text_hash":"6da3b35ac926ea1747b2e1ed7937402f58cb06333b1ae63df47845f8a3167dee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p115-34234520"},{"id":"06f50e90-b6a9-549e-b087-257f383f54a6","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إحداث إصابة -تعزير بالسجن واجللد -أخذ تعهد بعدم تكرار ما بدر منه .","document_number":"34180038","case_number":"33562319","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف 126 احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/06","year":"1434","subject":"اعتداء -ضرب -إحداث إصابة -تعزير بالسجن واجللد -أخذ تعهد بعدم تكرار ما بدر منه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34180038:‬تاريخه‪1434/04/06 :‬هـ‬\n                    ‫رقم الدعوى‪33562319:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34214853‬تاريخه‪1434/05/18:‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬إحــداث إصابــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬أخــذ‬\n                                     ‫تعهــد بعــدم تكــرار مــا بــدر منــه ‪.‬‬\n\n\n\n\n                          ‫‪ -1‬الفائدة الفقهية « أن املرء مؤاخذ بإقراره »‬\n                  ‫‪ -2‬الفائدة الفقهية « إقراراإلنسان على نفسه مقبول »‬\n\n\n\n\n‫الئحــة الدعــوى العامــة ضــد املدعــى عليهمــا بأنــه مت القبــض عليهمــا‬\n‫بعــد بــاغ حــدوث مشــاجرة بينهمــا علــى إثــر ســوء تفاهــم ‪ ،‬نتــج عنــه‬\n‫إصابتهمــا وقــد أســفر التحقيــق عــن توجيــه اإلتهــام لهمــا باإلعتــداء علــى‬\n‫بعضهمــا و التســبب يف اإلصابــة التــي حلقــت بــكل منهمــا علــى إثــر ســوء‬\n‫تفاهــم وطلــب املدعــي العــام عقوبتهمــا بعقوبــة تعزيريــة ‪ ،‬أجــاب املدعــى‬\n‫عليهمــا باملصادقــة علــى دعــوى املدعــي العــام ‪،‬صــدر احلكــم بتعزيــر‬\n‫املدعــى عليــه األول بالســجن شــهر و جلــده مائــة جلــدة علــى دفعتــن و‬\n‫أخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه ‪ ،‬تعزيــر املدعــى عليــه الثاني‬\n‫بالســجن خمســة وعشــرين يومــا و جلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n‫وأخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه ‪ ،‬مت تصديــق احلكــم مــن‬\n                                                             ‫محكمــة االســتئناف‬\n\n                                                                                           ‫‪126‬‬\n\f      ‫احلمــد هلل وحــده وبعــد حضــر املدعــي العــام ‪ .....‬بالســجل املدنــي رقــم‬\n      ‫(‪ ).....‬وحضــر حلضــوره املدعــى عليهمــا ‪ .......‬الســعودي بالســجل املدنــي‬\n      ‫رقــم (‪ ).....‬و‪ .....‬الســعودي بالســجل املدنــي رقــم (‪ )...‬وبســؤال املدعــي‬\n      ‫العــام عــن دعــواه قــال بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام‬\n                                        ‫مبحافظــة األحســاء أدعــي علــى كل مــن‪/‬‬\n      ‫‪ ،...... .1‬البالغ من العمر(‪ )46‬عاماً‪ ،‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم (‪ ،)....‬عســكري باحلــرس الوطنــي‪ ،‬محصــن‪ ،‬قبــض عليــه‬\n      ‫بتاريــخ ‪1433/3/5‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ ‪1433/3/6‬ه ـ‬\n                                                  ‫يســكن محافظــة األحســاء‪............/‬‬\n      ‫‪ ، ...... .2‬البالغ من العمر(‪ )46‬عاماً‪ ،‬سعودي اجلنسية مبوجب السجل‬\n      ‫املدنــي رقــم (‪ ،)....‬عســكري باحلــرس الوطنــي‪ ،‬محصــن‪ ،‬قبــض عليــه‬\n      ‫بتاريــخ ‪1433/3/5‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ ‪1433/3/6‬ه ـ‬\n      ‫يســكن محافظــة األحساء‪/‬إســكان احلــرس الوطنــي إنــه بتاريــخ‬\n      ‫‪1433/3/5‬ه ـ قبــض عليهمــا مــن قبــل الشــرطة العســكرية التابعــة‬\n      ‫للحــرس الوطنــي مبحافظــة األحســاء إثــر ورود كتــاب قائــد مدفعيــة‬\n      ‫امليــدان الثانيــة املتضمــن حصــول مشــاجرة بــن املدعــى عليهمــا علــى إثــر‬\n      ‫ســوء تفاهــم بينهمــا ونتــج عنــه إصابتهمــا‪ ،‬وقــد صــدر بحــق األول تقريــر‬\n      ‫طبــي مــن الشــؤون الصحيــة باحلــرس الوطنــي رقــم (‪)03/06/1967‬‬\n      ‫وتاريــخ ‪2011/1/20‬م املتضمــن وجــود جــرح ســطحي باجلبهــة ومــده‬\n      ‫شــفائه أقــل مــن خمســة عشــر يوم ـاً‪ ،‬وقــد صــدر بحــق الثانــي تقريــر‬\n      ‫طبــي مــن الشــؤون الصحيــة باحلــرس الوطنــي رقــم (‪)42/10/1967‬‬\n\n‫‪127‬‬\n\f‫وتاريــخ ‪2011/3/29‬م املتضمــن وجــود جــرح بقمة الرأس(‪ )1,3‬ســطحي‬\n‫ومت خياطتــه ومــده شــفائه أكثــر مــن خمســة عشــر يومـاً‪ .‬وباســتجواب‬\n‫املدعــى عليــه األول‪ :‬أقــر باعتدائــه علــى املدعــى عليــه الثانــي علــى إثــر‬\n‫ســوء تفاهــم بينهمــا وقيامــه بضربــه علــى رأســه بواســطة ســيخ حديــدي‪.‬‬\n‫وباســتجواب املدعــى عليــه الثانــي‪ :‬أفــاد أنــه أثنــاء تواجــده مبقــر الرمايــة‬\n‫تعــرض لالعتــداء بالضــرب بواســطة ســيخ حديــدي علــى رأســه مــن قبــل‬\n‫املدعــى عليــه األول علــى إثــر ســوء تفاهــم بينهمــا‪ .‬وقــد أســفر التحقيــق‬\n‫عــن توجيــه االتهــام لهمــا باالعتــداء علــى بعضهمــا والتســبب باإلصابــة‬\n‫التــي حلقــت كل منهمــا علــى إثــر ســوء تفاهــم بينهمــا‪ ،‬وذلــك لألدلــة‬\n                                                                      ‫والقرائــن التاليــة‪:‬‬\n‫‪ .1‬أقوالهمــا املدونــة علــى الصفحــات رقــم(‪ )8،4،3‬مــن ملــف االســتدالل‬\n                                                                             ‫لفه رقــم(‪.)2‬‬\n    ‫‪ .2‬التقريران الطبيان املرفق صوره منهما على اللفتني رقم(‪.)11،10‬‬\n                                   ‫‪ .3‬محضر الواقعة املرفق على اللفة رقم(‪)13‬‬\n‫وببحــث ســوابقهما تبــن خلــو ســجلهما مــن الســوابق اجلنائيــة‪ .‬وحيــث إن‬\n                                                                                         ‫ما‬\n‫أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليهمــا واحلكــم‬\n‫عليهمــا بعقوبــة تعزيريــة لقــاء مــا أســند إليهمــا مــن اتهــام [علمـ ًا بــأن احلــق‬\n‫اخلــاص انتهــى بالتنــازل]‪ .‬هــذه دعواي وبســؤال املدعى عليــه األول ‪ ....‬عن‬\n‫دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام مــن قيامي‬\n‫باالعتــداء علــى املدعــى عليــه الثانــي وذلــك بضربــه بســيخ حديــدي علــى‬\n‫رأســه ممــا ســبب لــه اإلصابــة املذكــورة بالدعــوى فصحيــح وســبب ذلــك‬\n\n\n                                                                                              ‫‪128‬‬\n\f      ‫ســوء التفاهــم بينــي وبينــه هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي‬\n      ‫‪ ....‬عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العام من‬\n      ‫قيامــي باالعتــداء علــى املدعــى عليــه األول وذلــك بضربــه بســيخ حديــدي‬\n      ‫علــى رأســه ممــا ســبب لــه اإلصابــة املذكــورة بالدعــوى فصحيــح وســبب‬\n      ‫ذلــك ســوء تفاهــم بينــي وبينــه هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليهمــا بدعــوى املدعــي العــام‬\n      ‫ولكــون هــذا اإلقــرار قــد صــدر مــن مكلــف ‪ -‬عاقــل بالــغ ‪ -‬وللقاعــدة‬\n      ‫الفقهيــة ((أن املــرء مؤاخــذ بإقــراره)) والقاعــدة ((إقــرار اإلنســان علــى‬\n      ‫نفســه مقبــول)) املنثــور مــن القواعــد للزركشــي [ج‪ ]188/1‬واألشــباه‬\n      ‫والنظائــر للســيوطي [ج‪ ]465/1‬ودرر احلــكام [ج‪ ]79/1‬وبعــد االطــاع‬\n      ‫علــى التقريــر الطبــي لذلــك كلــه فقــد قــررت مــا يلــي‪ :‬القســم األول‪:‬‬\n      ‫مــا يتعلــق باملدعــى عليــه األول ‪ :...‬أوال‪ :‬ثبــت لــدي قيــام املدعــى عليــه‬\n      ‫األول باالعتــداء علــى املدعــى عليــه الثانــي وذلــك بضربــه بســيخ حديــدي‬\n      ‫علــى رأســه ممــا نتــج عنــه اإلصابــة املذكــورة بالدعــوى وقــررت تعزيــره‬\n      ‫لقــاء ذلــك بســجنه ملــدة شــهر وجلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n      ‫متســاويتني بــن كل دفعــة وأخــرى عشــرة أيــام ثانيــا‪ :‬أخــذ التعهــد‬\n      ‫الشــديد عليــه بعــدم تكــرار مــا بــدر منــه‪ .‬القســم الثانــي‪ :‬مــا يتعلــق‬\n      ‫باملدعــى عليــه الثانــي ‪ :....‬أوال‪ :‬ثبــت لــدي قيــام املدعــى عليــه الثانــي‬\n      ‫باالعتــداء علــى املدعــى عليــه األول وذلــك بضربــه بســيخ حديــدي علــى‬\n      ‫رأســه ممــا نتــج عنــه اإلصابــة املذكــورة بالدعــوى وقــررت تعزيــره لقــاء‬\n      ‫ذلــك بســجنه ملــدة خمســة وعشــرين يومــا وجلــده مائــة جلــدة مفرقــة‬\n      ‫علــى دفعتــن متســاويتني بــن كل دفعــة وأخــرى عشــرة أيــام ثانيــا‪:‬‬\n      ‫أخــذ التعهــد الشــديد عليــه بعــدم تكــرار مــا بــدر منــه ومبــا ســبق كلــه‬\n\n\n‫‪129‬‬\n\f‫حكمــت وبعرضــه علــى املدعــى عليهمــا قــررا القناعــة بــه كمــا قــرر‬\n‫املدعــي العــام املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن‬\n‫تقــدمي الئحــة اعتراضيــة وبذلــك تكــون القضيــة منتهيــة وقــررت بعــث‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم‬\n‫حســب املتبــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                  ‫وصحبــه وســلم تســليما كثيــرا‪.‬‬\n‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة ‪ ............‬علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1084905‬ج‪ 2‬وتاريــخ ‪1434/05/04‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 34623860‬وتاريــخ ‪1434/04/28‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪ ..... /‬املســجل‬\n‫برقــم ‪ 34180038‬وتاريــخ ‪1434/04/06‬ه ـ اخلــاص بدعوى‪/‬املدعــي‬\n‫كل مــن‪ ..../1‬و‪ ..... /2‬يف قضيــة مضاربــه وقــد تضمــن‬             ‫العــام ضــد ٍ‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                  ‫‪1434/05/18‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":126,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e9be0acb6f4129dfb7522ef2b9fad398118b5411e99c55c407545025f135e4b","normalized_text_hash":"daf9bfa5973f6ecfb6acfefa43c157107bf381abc465fd6eea56c2178943b13f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p126-34180038"},{"id":"87db280b-e132-5082-8037-c905fd452457","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -تسبب يف إصابات -تعزير بالسجن و اجللد ،تعزير بالتوبيخ -تعهد.","document_number":"3420263","case_number":"33567741","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية الثالثية الثانية رقم 3437333ج 2/وتاريخ","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/24","year":"1434","subject":"اعتداء -ضرب -تسبب يف إصابات -تعزير بالسجن و اجللد ،تعزير بالتوبيخ -تعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3420263:‬تاريخه‪1434/01/24 :‬هـ‬\n                          ‫رقم الدعوى‪33567741:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3437333‬تاريخه‪1434/02/13:‬هـ‬\n\n\n\n      ‫اعتــداء ‪-‬ضــرب ‪ -‬تســبب يف إصابــات‪ -‬تعزيــر بالســجن و اجللــد ‪ ،‬تعزيــر‬\n                                                             ‫بالتوبيــخ ‪ -‬تعهــد‪.‬‬\n\n\n\n\n                    ‫‪-1‬قول اهلل تعالى «وال تفسدوا يف األرض بعد إصالحها»‬\n                           ‫‪-2‬قوله تعالى «وال تعتدوا إن اهلل ال يحب املعتدين»‬\n      ‫‪-3‬قولــه صلــى اهلل عليــه وســلم «كل املســلم علــى املســلم حــرام دمــه‬\n                                                               ‫ومالــه و عرضــه»‬\n      ‫‪-4‬قولــه صلــى اهلل عليــه وســلم «فــان دمائكــم و أموالكــم و أعراضكــم‬\n                       ‫حــرام عليكــم كحرمــة يومكــم هــذا يف بلدكــم هــذا»‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد ســبعة أشــخاص‪ ،‬أربعــة مواطنــن وثالثــة‬\n      ‫وافديــن ‪ ،‬حيــث مت القبــض عليهــم بعــد بــاغ مــن الوافديــن الثالثــة مــن‬\n      ‫تعرضهــم للضــرب مــن قبــل املدعــى عليهــم املواطنــن األربعــه أثنــاء قيــام‬\n      ‫الوافديــن بالعمــل يف محــل حالقــة ‪ ،‬حيــث حــدث إعتــداء بالضــرب بــن‬\n      ‫الطرفــن وقــد أســفر التحقيــق معهــم عــن توجيــه اإلتهــام لهــم باإلعتــداء‬\n      ‫علــى بعضهــم البعــض بــأدوات حــادة مــن قبــل املواطنــن والتســبب لهــم‬\n      ‫باإلصابــات التــي حلقــت بهــم علــى إثــر ســوء تفاهــم بينهــم و طلــب املدعــي‬\n\n‫‪131‬‬\n\f‫العــام إثبــات مــا اســند إليهــم و احلكــم عليهــم بعقوبــة تعزيزيــة‪ ،‬أقــر‬\n‫املدعــي عليهــم األول والثانــي والثالــث بالدعــوى وأنكــر املدعــي عليــه‬\n‫الرابــع ‪ ،‬أفــاد املدعــي عليــه الوافــد اخلامــس بــان االعتــداء عليــه مت يف‬\n‫احملــل كمــا أفــاد املدعــي عليــه الســابع بأنــه ال صحــة مبشــاركته يف‬\n‫االعتــداء ‪،‬عــدم وجــود بينــة للمدعــي العــام تثبــت مــا اســند للمدعــى‬\n‫عليهــم الرابــع واخلامــس والســادس و الســابع ثبــوت إدانــة األول والثانــي‬\n‫والثالــث مبــا اســند إليهــم ‪ ،‬واحلكــم علــى األول بالســجن ثالثــة أشــهر‬\n‫واجللــد مائــة وعشــرين جلــدة مفرقــة علــى ثــاث دفعــات ‪ ،‬واحلكــم علــى‬\n‫الثانــي والثالــث بالســجن خمســة وأربعــن يومــا واجللــد ثمانــن جلــدة‬\n‫مفرقــة علــى دفعتــن ‪ ،‬عــدم ثبــوت إدانــة الرابــع واخلامــس والســادس‬\n‫والســابع باالشــتراك يف املضاربــة ورد دعــوى املدعــي العــام بإثبــات‬\n‫ذلك‪،‬وثبــوت إدانــة الرابــع واخلامــس والســادس والســابع بحصــول مشــادة‬\n‫كالميــة أدت للمضاربــة ومت تعزيرهــم بالتوبيــخ والتقريــع والتوجيــه‬\n‫بأخــذ التعهــد عليهــم بعــدم العــودة ملــا بــدر منهــم ‪،‬تصديــق احلكــم مــن‬\n                                                       ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫فلدي أنا‬\n     ‫َّ‬    ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى املعاملــة الواردة‬‫‪ .........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء واملقيــدة‬\n‫بهــذه احملكمــة برقــم‪ 331676227‬وتاريخ‪1433/09/10‬ه ـ واحملالــة‬\n‫إلينــا مــن فضيلــة الرئيــس برقم‪33567741‬وتاريخ‪1433/09/10‬ه ـ‬\n‫فتحــت اجللســة وفيهــا حضــر املدعــي العــام امل َُع ّمــد بالترافــع أمــام‬\n\n                                                                                        ‫‪132‬‬\n\f      ‫احملكمــة طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق‬\n      ‫ا‪:‬‬  ‫واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة اإلدعــاء العــام مبحافظــة األحســاء‬\n      ‫أدعــي علــى ‪ ........‬وأفــرج عنــه بالكفالــة احلضوريــة‪ ،.......‬قبــض عليــه‬\n      ‫وأفــرج عنــه بالكفالــة احلضوريــة ‪ ،‬قبــض عليــه وأفــرج عنــه بالكفالــة‬\n      ‫احلضوريــة ‪ ،‬وأفــرج عنــه بالكفالــة احلضوريــة ‪ ،‬وأفــرج عنــه بالكفالــة‬\n      ‫احلضوريــة‪ ،‬وأفــرج عنــه بالكفالــة احلضوريــة‪ ،‬قبــض عليــه وأفــرج عنــه‬\n      ‫بالكفالــة مت القبــض عليهــم علــى إثــر بــاغ مــن املدعــى عليــه اخلامــس‬\n      ‫والســادس والســابع عــن تعرضهــم للضــرب أثنــاء قيامهــم بالعمــل باحملــل‬\n      ‫املســمى الواقــع علــى مــن قبــل شــخصان ســعوديان بســبب خــاف‬\n      ‫بينهمــا وتعــرض كل مــن الطرفــن لإلصابــة‪ .‬باالنتقــال إلــى احملــل‪:‬‬\n      ‫شــوهد احملــل مبعثــر بالكامــل وعثــر علــى عــدد (‪ )2‬عصــى ( عجــرى‬\n      ‫) احدهمــا مكســورة كمــا شــوهد آلــة البخــار متعرضــة للتكســير‬\n      ‫ويوجــد بقــع دمــاء علــى أرضيــة احملــل ‪ .‬وقــد اثبــت التقريــر الطبــي رقــم‬\n      ‫بحــق املدعــى عليــه الســابع املتضمــن (يشــتكي مــن عضــه علــى اخلــد‬\n      ‫األيســر وكدمــات خفيفــه متفرقــة يف أنحــاء اجلســم ) ومــدة الشــفاء‬\n      ‫يومــان كمــا اثبــت التقريــر الطبــي رقــم (املتضمــن ( جــرح قطعــي يف‬\n      ‫فــروة الــرأس وقطــع أخــر يف اليــد اليســرى وكدمــات متفرقــة ) ومــدة‬\n      ‫الشــفاء ثالثــة أيــام مالــم حتــدث مضاعفــات ‪.‬و التقريــر الطبــي رقــم‬\n      ‫‪ ........‬مــن ذات املستشــفى بحــق املدعــى عليــه اخلامــس املتضمــن رض‬\n      ‫راســي و كســر باجلمجمــه مــع نــزف خــارج اجلافيــة ومــدة الشــفاء شــهر‬\n      ‫مالــم حتــدث مضاعفــات و التقريــر الطبــي الصــادر مــن بحــق املدعــى‬\n      ‫عليــه األول واملتضمــن جــرح قطعــي باجلهــة اليســرى مــن الوجــه بطــول (‬\n\n\n‫‪133‬‬\n\f‫‪ 2‬ســم) مــع فقــدان اجللــد وجــرح باخلــد األميــن بطــول (‪1‬ســم) هــذه اجلــروح‬\n‫علــى األغلــب نتيجــة األصابــة بآلــه حــادة ومــدة الشــفاء أســبوع مــا لــم‬\n‫حتــدث مضاعفــات ‪ .‬وباســتجواب املدعــى عليــه األول أفــاد بأنــه يف يــوم‬\n‫ذهــب إلــى صالــون وأثنــاء قيــام املدعــى عليــه اخلامــس بحالقتــة حــدث‬\n‫ســوء تفاهــم بينهمــا بســبب كثــرة الــكالم مــن املدعــى عليــه اخلامــس‬\n‫أثنــاء احلالقــة بلغــة اليفهمهــا ممــا ادى إلــى مشــادة بالــكالم فتجمعــوا‬\n‫حولــه مجموعــة أشــخاص مــن وقامــوا باالعتــداء عليــه وقــام ( املدعــى‬\n‫عليــه الرابــع ) بفــض النــزاع بينهمــا أعقبهــا توجهــه يف يــوم إلــى مغســلة‬\n‫ال مــن‬ ‫الكرامــه للمالبــس الواقعــة بجــوار ذلــك الصالــون وشــاهد ك ً‬\n‫اخلامــس والســابع يقومــان باالســتهزاء بــه بســبب مــا حصــل بينهما ســابق ًا‬\n‫فتوجــه إلــى ســيارته وأخــذ عصــا ( عجــرى ) ودخــل لهمــا بالصالــون وقــام‬\n‫بضــرب املدعــى عليــه الســابع علــى رأســه كذلــك قــام بضــرب املدعــى‬\n‫عليــه اخلامــس بقدمــه علــى وجهــه أثنــاء مــا شــاهده ســاقط علــى األرض‬\n‫علــى حــد زعمــه ‪ .‬وباســتجواب‪( /‬فــرزت لــه اوراق لالختــاف يف جهــة‬\n‫االختصــاص) أفــاد بانــه علــم عــن تعــرض ابــن عمه‪/‬املدعــى عليــه األول‬\n‫للضــرب مــن قبــل مجموعــة أشــخاص وعنــد زيارتــه لــه شــاهد شــقيقه‬\n‫املدعــى عليــه األول والثالــث عنــده‪ ،‬فتوجهــوا جميعـ ًا إلــى صالــون التــل‬\n‫لالخــذ بثأرهــم وبالدخــول للصالــون كان بحــوزة كل مــن ‪/‬املدعــى‬\n‫عليــه األول والثانــي والرابــع عصــا ( عجــرى ) ودوره كان االمســاك‬\n‫باألشــخاص حتــى يتمكــن زمالئــه مــن االعتــداء عليهــم‪ .‬وباســتجواب‬\n‫املدعــى عليــه الثانــي أفــاد بأنــه ذهــب الــى منــزل ابــن عمه‪/‬املدعــى عليــه‬\n‫األول مــن اجــل زيارتــه واالطمئنــان عليــه كونــه تعــرض للضــرب مــن‬\n‫قبــل مجموعــة أشــخاص يعملــون حالقــن فشــاهد عنده شــقيقه‪/‬املدعى‬\n\n\n                                                                                      ‫‪134‬‬\n\f      ‫عليــه الثالــث وابــن عمــه وأثنــاء التحــدث معــه فهــم منــه بأنــه يرغــب‬\n      ‫باالنتقــام مــن األشــخاص الذيــن قامــوا بضربــه وإحداث إصابــة يف وجهه‬\n      ‫فتوجهــوا معــه علــى ســيارته التــي مــن نــوع هايلكــس الــى صالــون التــل‬\n      ‫ونزلــوا ســوي ًا وكان بحوزتــه هــو و‪/‬املدعــى عليــه األول عصــا (عجــرى )‬\n      ‫فدخلــوا الصالــون وتوجــه املدعــى عليــه األول إلــى الشــخص الذي تســبب‬\n      ‫يف إصابتــه فقــام بضربــه وضــرب شــخص آخــر قــام بضربــه علــى رأســه‬\n      ‫وتبــن لــه الحقـ ًا بأنــه املدعــى عليــه اخلامــس وكان املدعــى عليــه الثالــث‬\n      ‫واقفــن علــى بــاب الصالــون مينعــون األشــخاص مــن اخلــروج مــن الصالون‪.‬‬\n      ‫وباســتجواب املدعــى عليــه الثالــث افــاد أنــه أثنــاء تواجــده مبنزلــه رفــق‬\n      ‫ال مــن لإلطمئنــان‬    ‫شــقيقه‪/‬املدعى عليــه األول حضــرا لزيارتهــم ك ً‬\n      ‫علــى شــقيقه‪/‬املدعى عليــه األول بســبب تعرضــه للضــرب مــن قبــل‬\n      ‫مجموعــة أشــخاص يعملــون بصالــون التــل وأثنــاء جلوســهم اتفقــوا علــى‬\n      ‫التوجــه الــى ذلــك الصالــون لالنتقــام وأخــذ حــق املدعــى عليــه املذكــور‬\n      ‫وعنــد وصولهــم قامــوا بالتهجــم علــى العاملــن بذلــك الصالــون وكان‬\n      ‫ال مــن املدعــى عليــه األول عصــى ( عجــرى ) حيــث اعتــدى‬          ‫بحــوزة ك ً‬\n      ‫املدعــى عليــه األول أحدهــم والــذي اتضــح بأنــه املدعــى عليــه الســابع‬\n      ‫وتســبب بإصابتــه كذلــك قام‪/‬املدعــى عليــه األول املذكــور باالعتــداء‬\n      ‫علــى األخــر والــذي اتضــح بأنــه يدعى‪/‬املدعــى عليــه اخلامــس وتســبب‬\n      ‫بإصابتــه وكان دوره املســاعده حيــث حصلــت مشــادة باأليــدي بينهمــا‬\n      ‫وبــن شــخص ثالــث ‪ .‬وباســتجواب املدعــى عليــه الرابــع أفــاد بأنــه أثنــاء‬\n      ‫تواجــده بصالــون التــل وانتظــاره دوره للحالقــه حصلــت مشــاجرة بــن‬\n      ‫أحــد الزبائــن وأحــد العاملــن وتوجــه جميــع العاملــن باحملــل إلــى جهــة‬\n      ‫املشــاجرة وتبــن لــه بــأن أحــد أطــراف املشــاجرة هــو املدعــى عليــه األول‬\n\n\n‫‪135‬‬\n\f‫وهــو أحــد أقاربــه فحــاول التفريــق بينهــم إال أنهــم قامــوا باالعتــداء عليــه‬\n‫أيضـ ًا فقــام بالدفــاع عــن نفســه والحــظ أحدهــم والــذي تبــن لــه الحقـ ًا‬\n‫بأنــه املدعــى عليــه الســابع املذكــور يحمــل بيــده أداه حــاده لــم يذكــر‬\n‫نوعهــا وحــاول ضــرب فقــام باالمســاك بــه وانتهــت تلك املضاربــة بحدوث‬\n‫اصابــات بســيطة يف كال الطرفــن وباســتجواب املدعــى عليــه اخلامــس‬\n‫والســادس والســابع أفــادوا بأنهــم أثنــاء قيامهــم بعملهــم بالصالــون حضر‬\n‫لــه املدعــى عليــه األول ) مــن أجــل حالقــة ذقنــه وعندمــا بــدأ بحالقتــه‬\n‫لــم تعجبــه احلالقــة وحــدث ســوء تفاهــم بينهــم نتــج عنــه مشــاده باأليــدي‬\n‫ال من‪/‬املدعــى‬   ‫بينهمــا وتدخلــوا زمالئــه املوجوديــن بالصالــون وهــم ك ً‬\n‫عليــه الســادس والســابع وزبــون آخــر كان جالــس ينتظــر دوره للحالقــه‬\n‫وأن املضاربــه التــي حدثــت يــوم الســبت املوافــق ‪1433/6/7‬ه ـ كان مــن‬\n                                          ‫ضمــن املشــاركني بهــا املدعــى عليــه‬\n‫الرابــع وكان عددهــم ثمانيــة أشــخاص ال يعــرف أحــد منهــم ســوى‬\n‫املذكــور ‪.‬جــرى عــرض كل مــن املدعــى عليــه األول ( واملدعــى عليــه‬\n‫الثانــي ) واملدعــى عليــه الثالــث بــن مجموعــة مــن املوقوفــن مقاربــن‬\n‫لهــم باألوصــاف الظاهريــة والبدنيــة علــى املدعــى اخلامــس والســادس‬\n‫واســتطاع املدعــى عليــه اخلامــس التعــرف علــى املدعو‪/‬املدعــى عليــه‬\n‫الثانــي بنســبة (‪ )%100‬وأفــاد بأنــه مــن ضمــن املعتديــن عليــه داخــل احملــل‬\n‫ولــم يســتطع التعــرف علــى أحــد خالفــه ‪،‬وكذلــك تعــرف املدعــى عليــه‬\n‫الســادس علــى املدعــى عليــه الثانــي وعلــى املدعــو املدعــى عليــه الثالــث‬\n‫بنســبة (‪ )%100‬وذكــر بأنهــم مــن ضمــن املعتديــن عليهــم ‪.‬وقــد أســفر‬\n‫التحقيــق معهــم عــن توجيــه االتهــام لهــم باالعتــداء علــى بعضهــم البعــض‬\n‫بــأدوات حــاده مــن قبــل املجموعــه االولــى والتســبب باالصابــات التــي‬\n\n\n                                                                                       ‫‪136‬‬\n\f      ‫حلقــت بهــم علــى اثــر ســوء تفاهــم حصــل بينهــم ‪ ،‬وذلــك لألدلــة والقرائــن‬\n                                                                                 ‫التاليــة‪:‬‬\n                   ‫‪ .1‬محضر تقدمي البالغ املدون على اللفتني رقم (‪. )115،138‬‬\n      ‫‪ .2‬محضر املعاينة املدون على الصفحة رقم (‪ )2،3‬من ملف االستدالل‬\n                ‫لفه رقم(‪ )8‬واللفه رقم(‪ )2،3‬من ملف االســتدالل لفه رقم(‪. )12‬‬\n      ‫‪ .3‬محضــر العــرض والتعــرف املــدون علــى الصفحــة رقــم ( ‪ )7‬مــن ملــف‬\n      ‫االســتدالل لفــة رقــم ( ‪ )12‬الصفحــة رقــم ( ‪ )15‬مــن ملــف االســتدالل‬\n                                                                         ‫لفــة رقــم ( ‪. )1‬‬\n      ‫‪ .4‬مــا جــاء يف أقوالهــم املدونــه علــى الصفحــات رقــم ( ‪10‬الــى‪ )16‬مــن‬\n      ‫ملــف االســتدالل لفــة (‪)8‬و الصفحــات رقــم (‪1‬الــى‪ )11‬مــن ملــف‬\n      ‫االســتدالل لفــة (‪)6‬و الصفحــات رقــم ( ‪5‬الــى‪ )1‬مــن ملــف االســتدالل‬\n      ‫لفــة (‪ )5‬الصفحــات رقــم ( ‪ )11،16‬مــن ملــف االســتدالل لفــة (‪)4‬‬\n      ‫التقاريــر الطبيــة املرفقــة علــى اللفــات رقــم من(‪95‬الــى‪ . )101‬وببحــث‬\n      ‫ســوابق الثالــث تبــن وجــود ســابقتني مســجله عليــه األول مضــارب‬\n      ‫جماعيــة والثانــي اعتــداء بالطعــن وببحــث ســوابق البقيــه تبــن خلــو‬\n      ‫ســجالتهم مــن الســوابق اجلنائيــة وحيــث إن مــا أقــدم عليــه املذكــورون ـ‬\n      ‫وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا ـ فعــل محــرم ومعاقــب عليه شــرع ًا‬\n      ‫‪ ،‬أطلــب إثبــات مــا أســند إليــه واحلكــم عليهــم بعقوبــة تعزيريــة لقــاء مــا‬\n      ‫ال بحســب فعلــه‪ .‬علمـ ًا بــأن احلــق اخلــاص انتهــى‬\n                                                          ‫أســند إليهــم مــن اتهــام ك ً‬\n      ‫بالتنــازل هكــذا ا َّدعــى ‪ .‬عليــه فقــد حضــر املدعــى عليهــم جميعـ ًا وبعــد‬\n      ‫التأكــد مــن هوياتهــم جــرى عــرض دعــوى املدعــي العــام عليهــم فأجــاب‬\n      ‫املدعــى عليــه األول بعــد التأكــد مــن هويتــه عــن دعــوى املدعــي العــام‬\n      ‫فأجــاب قائ ـاً‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باالشــتراك يف‬\n\n\n‫‪137‬‬\n\f‫املضاربــة فصحيــح وذلــك أننــي كنـ ُـت أحلــق رأســي يف احلــاق الــذي‬\n‫يعمــل فيــه املدعــى عليهــم اخلامــس والســادس والســابع وكان الــذي‬\n‫يقــوم بحالقتــي املدعــى عليــه اخلامــس وبعــد انتهــاء احلالقــة قلــت لــه إن‬\n‫حالقتــك ليســت جيــدة فحصــل بينــا مشــادة كالميــة أدت إلــى املضاربــة‬\n‫يف إصابــات وذهبــت إلــى املنــزل وبعدهــا بيــوم رجعــت‬    ‫باأليــدي وحصــل َّ‬\n‫بصحبــة املدعــى عليهمــا الثانــي والثالــث وكان معــي واملدعــى عليــه‬\n‫الثانــي عجــرا وقمــت بضــرب املدعــى عليــه اخلامس والســابع وتســببت يف‬\n‫اإلصابــات املوصوفــة بالتقاريــر الطبيــة املذكــورة وأنــا نــادم علــى مابــدر‬\n‫منــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه الثانــي قائـاً‪ :‬ماذكــره‬\n‫املدعــي العــام مــن اتهامــي باملشــاركة يف املضاربــة فصحيــح وذلــك أننــي‬\n‫كنــت يف منــزل املدعــى عليــه األول وكان مصاب ـ ًا فقمــت وذهبــت‬\n‫بســيارتي برفقــة األول والثالــث وكان معــي عجــرا وملــا وصلنــا إلــى‬\n‫احملــل قمــت بضــرب املدعــى عليــه اخلامــس بيــدي ولــم أســتخدم العصــا‬\n‫وأنــا نــادم علــى مابــدر منــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬\n‫الثالــث قائ ـاً‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باملشــاركة يف‬\n‫املضاربــة فصحيــح وذلــك أننــي قمــت بالذهــاب مــع املدعــى عليهمــا األول‬\n‫والثالــث وقمــت بضــرب املدعــى عليــه اخلامــس بيــدي كمــا قمــت‬\n‫بإمســاك بــاب احملــل حتــى اليخــرج أحــد منــه وصحيــح نســبة الســابقتني‬\n‫لــي وقــد أخــذت محكوميتهمــا هكــذا أجــاب كمــا أجــاب املدعــى‬\n‫ا ‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باالعتــداء علــى‬   ‫عليــه الرابــع قائـ ً‬\n‫اخلامــس والســادس والســابع بــأدوات حــادة والتســبب باإلصابــات التــي‬\n‫حلقــت بهــم غيــر صحيــح والصحيــح أننــي كنــت جالس ـ ًا يف الصالــون‬\n‫الــذي يعمــل فيــه املدعــى عليهــم األتــراك أنتظــر دوري يف احلالقــة‬\n\n\n                                                                                         ‫‪138‬‬\n\f      ‫وحصلــت مشــادة كالميــة بــن املدعــى عليــه األول واملدعــى عليهمــا‬\n      ‫اخلامــس والســادس وحاولــت فــك النــزاع بينهــم مــع املدعــى عليــه الســابع‬\n      ‫وأثنــاء ذلــك حصلــت بيننــا مضاربــة باأليــدي مــع شــدة النــزاع والعالقــة‬\n      ‫ـأي شــيء ســوى ذلــك هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬            ‫لــي بـ ِّ‬\n      ‫ا ‪ :‬ماذكــره املدعــي العــام يف دعــواه مــن حصــول‬      ‫اخلامــس فأجــاب قائـ ً‬\n      ‫أن املدعــى عليــه األول‬ ‫اعتــداء علينــا يف محــل احلالقــة فصحيــح وذلــك َّ‬\n      ‫كان يحلــق عندنــا وقــام بســبي والتكلــم علـ َّـي وأننــي ال أعــرف أعمــل‬\n      ‫وقــام برمــي الفلــوس يف وجهــي ثــم خــرج ورجــع وحصــل بينــه وبينــه‬\n      ‫املدعــى عليــه الســادس مضاربــة أ َّدت إلى اشــتباكنا جميعـ ًا وبعد يومني‬\n      ‫حضــر شــخص ال أدري مــن هــو وضربنــي علــى رأســي بعصــا وأنا منشــغل‬\n      ‫بحالقــة رأس زبــون ممــا أ َّدى إلــى إغمائــي وإصابتــي وال أعــرف مــاذا‬\n      ‫حــدث بعــد ذلــك هكــذا أجــاب كمــا أجــاب املدعــى عليــه الســابع‬\n      ‫ا ‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باملشــاركة يف‬          ‫‪ ............‬قائ ـ ً‬\n      ‫أن املدعــى عليــه األول كان يحلــق‬     ‫االعتــداء فغيــر صحيــح والصحيــح َّ‬\n      ‫عنــد املدعــى عليــه اخلامــس وحصلــت بينهمــا مشــادة كالميــة وحاولــت‬\n      ‫فــك النــزاع بينهمــا فقــام بعضــي علــى وجهــي فحاولــت الدفــاع عن نفســي‬\n      ‫وقمــت بعضــه وانتهــى النــزاع وبعــد يومــن حضــر املدعــى عليــه األول‬\n      ‫وبرفقتــه عــدة أشــخاص لــم يكــن املدعــى عليــه الرابــع مــن ضمنهــم‬\n      ‫وقامــوا بضربنــا بعصــي كانــت معهــم ولــم يكــن م َّنــا أي مدافعــة حيــث‬\n      ‫إنهــم أتونــا مفاجئــة هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام عــن‬\n      ‫بينتــه علــى مانفــاه املدعــى عليهــم الرابــع واخلامــس والســادس والســابع‬\n      ‫ـدي ســوى مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا‬    ‫فقــال ‪ :‬ليــس لـ َّ‬\n      ‫هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا‬\n\n\n‫‪139‬‬\n\f‫التقريــر الطبــي املوجــود علــى اللفــة(‪ )95‬الصــادر مــن مستشــفى امللــك‬\n‫فهــد بالهفــوف املتضمــن إصابــة املدعــى عليــه اخلامــس ‪ ............‬بــرض‬\n‫رأســي مــع حالــة تغيــم وعــي و كســرب اجلمجمــة مــع نــزف خــارج اجلافيــة‬\n‫صدغــي أميــن ومــدة الشــفاء غيــر محــددة كمــا جــرى االطــاع علــى‬\n‫التقريــر الطبــي املوجــود علــى اللفــة (‪ )96‬الصــادر مــن املستشــفى نفســه‬\n‫برقم ـ مــن ذات املستشــفى بحــق املدعــى عليــه اخلامــس املتضمــن إصابــة‬\n‫املدعــى عليــه املذكــور بــرض رأســي و كســر باجلمجمــة مــع نــزف خارج‬\n‫اجلافيــة صدغــي أميــن ومــدة الشــفاء شــهر مالــم حتــدث مضاعفــات كمــا‬\n‫جــرى االطــاع علــى التقريــر الطبــي املوجــود علــى اللفــة(‪ )97‬الصــادر‬\n‫مــن الوطنــي رقــم الصــادر بحــق املدعــى عليــه األول املتضمــن إصابتــه‬\n‫بجــرح قطعــي باجلهــة اليســرى مــن الوجــه بطــول ( ‪ 2‬ســم ) مــع فقــدان‬\n‫اجللــد وجــرح باخلــد األميــن بطــول (‪1‬ســم) هــذه اجلــروح علــى األغلــب نتيجة‬\n‫اإلصابــة بآلــة حــادة ومــدة الشــفاء أســبوع مــا لــم حتــدث مضاعفــات ‪.‬‬\n‫كمــا جــرى االطــاع علــى التقريــر الطبــي املوجــود علــى اللفــة (‪)98‬‬\n‫أن املدعــى عليــه الســابع يشــتكي مــن عضــة علــى‬  ‫الصــادر مــن املتضمــن َّ‬\n‫اخلــد األيســر وكدمــات خفيفــة متفرقــة يف أنحــاء اجلســم ومــدة الشــفاء‬\n‫يومــان كمــا جــرى االطــاع علــى التقريــر الطبــي املوجــود علــى‬\n‫اللفــة(‪ )99‬الصــادر مــن املستشــفى نفســه برقــم ـ مــن ذات املستشــفى‬\n‫بحــق املدعــى عليــه الســابع املتضمــن إصابــة املدعــى عليــه املذكــور‬\n‫بقطــع يف فــروة الــرأس وقطــع آخــر يف اليــد اليســرى وكدمــات متفرقــة‬\n‫ومــدة الشــفاء ثالثــة أيــام كمــا جــرى االطــاع علــى كــروت ســوابق‬\n‫املدعــى عليهــم فوجــد أ َّنهــا خاليــة مــن الســوابق ســوى املدعــى عليــه‬\n‫فوجــد عنــده ســابقتان األولــى مضاربــة جماعيــة والثانيــة اعتــداء بالطعن‬\n\n\n                                                                                     ‫‪140‬‬\n\f      ‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬             ‫فبنـ ً‬\n      ‫عليهــم والتأكــد مــن أهليتهــم وبعــد تأمــل أوراق املعاملــة ودراســتها ومبــا‬\n      ‫أن املدعــى عليــه األول أقـ َّـر بدعــوى املدعــي العــام وأ َّنــه قــام باالشــتراك‬           ‫َّ‬\n      ‫يف املضاربــة وأ َّنــه تســبب باإلصابــات التــي وجــدت يف املدعــى عليــه‬\n      ‫وأن املضاربــة حصلــت بســببه ومبــا‬            ‫اخلامــس حيــث ضربــه بعصــا غليظــة َّ‬\n      ‫أن املدعــى عليــه الثانــي أقـ َّـر بدعــوى املدعــي العــام وأ َّنــه قــام باالشــتراك‬     ‫َّ‬\n      ‫يف املضاربــة ونقــل املدعــى عليهمــا الثانــي والثالــث بســيارتي للمحــل‬\n      ‫الــذي يعمــل فيــه املعتــدى عليهــم وضــرب اخلامــس بيــده دون العصــا التــي‬\n      ‫أن املدعــى عليــه الثالــث أقـ َّـر بدعــوى املدعــي العــام‬         ‫كان يحملهــا ومبــا َّ‬\n      ‫وأ َّنــه قــام باالشــتراك يف املضاربــة وضــرب املدعــى عليــه اخلامــس بيــده‬\n      ‫واإلمســاك بالبــاب حتــى اليتمكــن أحـ ٌـد مــن الدخــول وال اخلــروج مــن‬\n      ‫أن َ املدعــى عليــه الرابــع أنكــر دعــوى املدعــي العــام باتهامــه‬          ‫احملــل ومبــا ّ‬\n      ‫باملشــاركة يف املضاربــة والبينــة للمدعــي العــام علــى ذلــك ومبــا أ َّنــه أقـ َّـر‬\n      ‫مبحاولــة فــك النــزاع الــذي حصــل بــن األول واملدعــى عليهمــا خلامــس‬\n      ‫والســادس والســابع وأ َّدى ذلــك إلــى اســتعمال األيــدي لفــك النــزاع وهــذا‬\n      ‫أن املدعــى عليــه اخلامــس واملدعــى عليــه‬           ‫الفعــل اليســتوجب عقوبــة ومبــا َّ‬\n      ‫الســادس واملدعــى عليــه الســابع أنكــروا دعــوى املدعــي العــام مــن‬\n      ‫ـأن املدعــى عليهــم الثالثــة‬        ‫اتهامهــم باالشــتراك يف املضاربــة ودفعــوا بـ َّ‬\n      ‫أي مقاومــة منهــم‬        ‫األول هــم َمــنْ جــاء إلــى محلهــم وقامــوا بضربهــم دون ِّ‬\n      ‫ومبــا أ َّنــه البينــة للمدعــي العــام علــى مــا أنكــروه ومبــا أ َّنهــم أقـ َّـروا‬\n      ‫بحصــول مشــادة كالميــة بينهــم أ َّدت إلــى نشــوء هــذه املضاربــة وهــذا‬\n      ‫ـاب واســع فأعالهــا‬         ‫أن التعزيــر بـ ٌ‬‫مــن احملـ َّـرم يســتوجب تعزيرهــم ومبــا َّ‬\n      ‫لقتــل وأدنــاه التوبيــخ ممــا يســتوجب تعزيرهــم بالتوبيــخ وأخــذ التعهــد‬\n\n\n‫‪141‬‬\n\f‫أن ماصــدر مــن املدعــى عليهــم األول والثانــي والثالــث مــن احملـ َّـرم‬                                         ‫ومبــا َّ‬\n‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا ) وقــال تعالــى‬        ‫ال ْر ِ‬‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬ ‫شــرع ًا قــال تعالــى‪َ :‬‬\n‫الل ال ُي ِ ُّحــب ْال ُْع َتدِ َيــن ) وقــال صلــى اهلل عليــه وســلم ‪:‬‬                ‫‪َ ( :‬وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n‫وعرضــه)) وقــال عليــه‬    ‫ُ‬             ‫دم ـ ُه وما ُل ـ ُه‬‫ـرام ُ‬\n                                                                 ‫((كلُّ املســلم علــى املســلم حـ ٌ‬\n‫كـ ْـم َحـ َـر ٌام‬   ‫َكـ ْـم َو َأ ْع َر َ‬\n                  ‫اض ُ‬                      ‫كـ ْـم َو َأ ْم َوال ُ‬‫‪((:‬ف ـ ِإ َّن د َِم َاء ُ‬\n                                                                                       ‫الصــاة والســام َ‬\n‫كـ ْـم‬  ‫ك ْم َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬    ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬         ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬\n                                                                                                         ‫كـ ْـم َ‬      ‫َع َل ْي ُ‬\n‫َهـ َـذا )) ممــا يســتوجب تعزيرهــم لقــاء ذلــك ويتوجــه أن يكــون املدعــى‬\n‫عليــه األول أشــدهم عقوبــة لكونــه املتســبب يف املضاربــة ولعظــم مــا‬\n‫صــدر منــه كمــا يتوجــه اســتواء الثانــي والثالــث يف العقوبــة الســتوائهما‬\n‫يف اجلــرم كمــا يراعــي يف العقوبــة انتهــاء احلقــوق اخلاصــة بالتنــازل لــذا‬\n‫كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليهــم مبــا يلــي ‪ :‬أو ًال ‪/‬‬\n‫ـدي إدانــة املدعــى عليــه األول باالشــتراك يف املضاربــة وضربــه‬                                           ‫ثبــت لـ َّ‬\n‫للمدعــى عليــه اخلامــس بعصــا غليظــة وتســببه باإلصابــات التــي وجــدت‬\n‫بــه ويعــزر ألجــل ذلــك بســجنه ثالثــة أشــهر حتتســب منهــا املــدة التــي‬\n‫أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائــة وعشــرون جلــدة مفرقــة‬\n‫علــى ثــاث دفعــات كل دفعــة أربعــون جلــدة وبــن كل دفعــة وأخــرى‬\n‫ـدي إدانــة املدعــى عليــه الثانــي‬             ‫مــدة التقــل عــن عشــرة أيــام ‪.‬ثانيـ ًا ‪ /‬ثبــت لـ َّ‬\n‫واملدعــى عليــه الثالــث باالشــتراك يف املضاربــة واالعتــداء علــى اخلامــس‬\n‫والســادس والســابع بأيديهــم وعــزرت كل واحــد منهمــا لقــاء ذلــك‬\n‫بســجنه ملــدة خمســة وأربعــن يومـ ًا حتتســب منهــا املــدة التــي أوقــف فيهــا‬\n‫كل واحــد منهمــا علــى ذمــة القضيــة ويجلــد كل واحــد منهمــا ثمانــون‬\n‫جلــدة مفرقــة علــى دفعتــن متســاويتني كل دفعــة أربعــون جلــدة وبــن‬\n‫ـدي‬\n ‫كل دفعــة وأخــرى مــدة التقــل عــن عشــرة أيــام ‪ .‬ثالث ـ ًا ‪ /‬لــم يثبــت لـ َّ‬\n\n                                                                                                                                    ‫‪142‬‬\n\f      ‫إدانــة املدعــى عليهــم الرابــع واملدعــى عليــه اخلامــس واملدعــى عليــه‬\n      ‫الســابع باالشــتراك يف املضاربــة وقــررت رد دعــوى املدعــي العــام بإثبــات‬\n      ‫ـدي إدانتهــم بحصــول مشــادة كالميــة أ َّدت إلــى‬        ‫ذلــك وإمنــا ثبــت لـ َّ‬\n      ‫املضاربــة وعزرتهــم بالتوبيــخ والتقريــع والتوجيــه داخــل املجلس الشــرعي‬\n      ‫مت ذلــك ‪ .‬رابعـ ًا ‪ /‬يؤخــذ عليهــم التعهــد بعــدم العــودة ملثــل مــا صــدر منهم‬\n                                                                                        ‫و َّ‬\n      ‫‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليهــم بحقهــم يف متييــز‬\n      ‫احلكــم قــرر املدعــى عليهــم جميع ـ ًا القناعــة بــه وطلــب املدعــي العــام‬\n      ‫رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون‬\n      ‫الئحـ ٍة اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى وصلى اهلل وسـلَّم‬\n      ‫‪.‬حـ ِـر َر يف ‪1434/01/07‬هـ‬   ‫علــى نبينــا محمــد وعلــى آله وصحبه أجمعني ُ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد ففــي‬\n      ‫يــوم األحــد ‪1434/03/15‬ه ـ فتحــت اجللســة الثانيــة الســاعة الثامنــة‬\n      ‫والنصــف وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم ‪34296669‬‬\n      ‫والتاريــخ ‪1434/03/01‬ه ـ مرفق ـ ًا بهــا قــرار أصحــاب الفضيلــة قضــاة‬\n      ‫الدائــرة اجلزائيــة الثالثيــة الثانيــة رقــم ‪ 3437333‬ج‪ 2/‬وتاريــخ‬\n      ‫مانصــه ‪ :‬بدراســة القــرار وصــورة ضبطــه‬    ‫ُّ‬     ‫‪1434/02/13‬ه ـ املتضمــن‬\n      ‫وأوراق املعاملــة لوحــظ أن صــورة الضبــط املرفقــة غيــر مكتملــة والبــد‬\n      ‫مــن إرفــاق صــورة الضبــط مكتملــة ملالحظــة مــا ذكر وإكمــال مايلزم‬\n      ‫ومــن ثــم إعــادة املعاملــة وبــاهلل التوفيــق قاضــي اســتئناف ختمــه وتوقيعــه‬\n      ‫‪ ،‬قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه أ‪.‬ه ـ‬\n      ‫عليــه أجيــب مشــائخي نفعنــي اهلل بعلمهــم بأنــه مت إجــراء الــازم حيــال‬\n      ‫هــذه املالحظــة وأقفلــت اجللســة الســاعة الثامنــة وخمســة وأربعــون دقيقــة‬\n\n\n‫‪143‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":131,"source_page_end":143,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bf677292b71719b1650613aa3a8a54fb63d163d4e2a02a7727c789fa9d4f3bfa","normalized_text_hash":"c1c9c43fe7a7d94aae3cf04e4e48de6557e33a83e53c373dfde132b832ec90a4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p131-3420263"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0dc1c76d-59f1-5fb3-bb73-325d8b2dcdc5","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -وجود سوابق على املدعى عليه -إقرار املدعى عليه -تغليظ العقوبة -تعزير بالسجن واجللد -اإلقرار حجة معتبرة شرع ا .","document_number":"34271857","case_number":"33393127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بأن احلكم قليل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/18","year":"1434","subject":"اعتداء -ضرب -وجود سوابق على املدعى عليه -إقرار املدعى عليه -تغليظ العقوبة -تعزير بالسجن واجللد -اإلقرار حجة معتبرة شرع ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34271857 :‬تاريخه‪1434/07/18:‬هـ‬\n                    ‫رقم الدعوى‪33393127:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34358482‬تاريخه‪1434/11/12:‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬وجــود ســوابق علــى املدعــى عليــه ‪ -‬إقــرار املدعــى‬\n                   ‫عليــه ‪ -‬تغليــظ العقوبــة ‪ -‬تعزيــر بالســجن واجللــد‬\n\n\n\n\n                                             ‫‪ -‬اإلقرار حجة معتبرة شرع ًا ‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــي عليــه بتوجيــه االتهــام لــه بضــرب آخــر‬\n‫عمــد ًا نتــج عــن ذلــك إصابتــه‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة ‪،‬‬\n‫مت القبــض علــى املدعــي عليــه بنــاء علــى شــكوى مــن شــخص تعــرض‬\n‫ـاء‬\n‫للضــرب وأصيــب بجــرح قطعــي باجلبهــة ومــدة الشــفاء ســبعة أيــام بنـ ً‬\n‫علــى التقريــر الطبــي ‪ ،‬مت اســتجواب املدعــي عليــه وأقــر بضــرب املجني‬\n‫عليــه وإصابتــه‪ ،‬مت عــرض الدعــوى على املدعى عليه وأنكر الدعوى‪،‬‬\n‫بنــاء علــى إقــراره لــدى هيئــة التحقيــق واالدعــاء العــام ولوجــود ســوابق‬\n‫فقــد صــدر احلكــم بثبــوت إدانتــه مبــا نســب إليــه واحلكــم بســجنه ســتة‬\n‫أشــهر وجلــده ثالثــن جلــدة تكــرر عليــه أربــع مــرات علــى دفعــات‪ ،‬مت‬\n‫رفــع احلكــم حملكمــه االســتئناف بنــاء علــى معارضــة املدعــي العــام ‪،‬‬\n‫صــدق قــرار محكمــة االســتئناف بــأن احلكــم قليــل‪ ،‬مت زيــادة مــدة‬\n‫الســجن شــهرين ليكــون كامــل املــدة ثمانيــة أشــهر وجعــل اجللــد‬\n\n                                                                                   ‫‪98‬‬\n\f     ‫خمســن جلــدة تكــرر علــى أربــع مــرات بينهــا أســبوع ‪ ،‬صــدق احلكــم‬\n                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫باملدينة املنورة وبناء على املعاملة املقيدة باحملكمة برقم ‪331090662‬‬\n     ‫وتاريــخ ‪ 1433/06/10‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/28‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 9 : 00‬وفيهــا حضــر املدعــي العــام ‪........‬‬\n     ‫ســعودي مبوجــب الســجل املدنــي رقــم (‪ )........‬والتعميــد رقــم (‪)........‬‬\n     ‫يف ‪1434/6/12‬ه ـ مــن اإلدعــاء العــام باملدينــة املنــورة وادعــى علــى‬\n     ‫‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬قائــا يف‬\n     ‫حتريــر أنــه بتاريــخ ‪1434/5/6‬ه ـ أبلــغ ‪........ /‬شــرطة ‪ ..........‬عــن تعرضه‬\n     ‫للضــرب مــن قبــل املدعــى عليــه املذكــور أعــاه ممــا نتــج عنــه إصابتــه‬\n     ‫بجــرح قطعــي يف اجلبهــه ومــدة الشــفاء ســبعة أيــام إســتنادا للتقريــر‬\n     ‫الطبــي الصــادر مــن مستشــفى اإلنصــار برقــم (‪ )........‬يف ‪1434/5/6‬ه ـ‬\n     ‫وبســماع أقــوال املدعــى عليــه أعتــرف أنــه ضــرب املدعــي وأنــه املتســبب‬\n     ‫يف إصابتــه وانتهــى التحقيــق الــى إتهامــه بضــرب ‪........‬عمــدا ممــا نتــج‬\n     ‫عنــه إصابتــه الــواردة يف التقريــر الطبــي املرفــق وذلــك لألدلــة التاليــة ‪-1‬‬\n     ‫إعترافــه املنــوه عنــه ‪ -2‬التقريــر الطبــي املشــار اليــه وحيــث أن ماأقــدم‬\n     ‫عليــه املتهــم فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبات ماأســند اليه‬\n     ‫واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ماأقــدم عليــه مــع طلــب تشــديد‬\n     ‫العقوبــة بحقــه لقــاء تعــدد ســوابقه اجلنائيــة علمــا بــأن احلــق اخلــاص‬\n     ‫اليــزال قائمــا ثــم أحضــر املتهــم مــن الســجن وبســؤاله عمــا نســب اليــه‬\n\n‫‪99‬‬\n\f‫إجــاب أنكــر ضــرب املدعــي والــذي حصــل أننــا متاســكت معــه عنــد‬\n‫بــاب إحــدى العمائــر وضربنــي وضربتــه وملــا هربــت وركبــت ســيارتي‬\n‫حلقنــي يجــري وارتطــم رأســه بالســيارة فحصلــت اإلصابــة وليــس لدي ما‬\n‫يثبــت ذلــك ولــم يحضــر املدعــي باحلــق اخلــاص رغــم الطلبــات املتكــررة‬\n‫وعليــه وبنــاء علــى مــا جــاء بالئحــة االتهــام والتــي انتهــى فيهــا التحقيــق‬\n‫الــى توجيــه االتهــام الــى ‪ ........‬ســعودي اجلنســية ‪ 30‬ســنه بضــرب ‪........‬‬\n‫عمــدا ممــا نتــج عنــه اصابتــه الــواردة يف التقريــر الطبــي املرفــق ولكــون‬\n‫مــا اقــدم عليــه فعــل محــرم ومعاقــب عليــه شــرعا طلــب املدعــي العــام‬\n‫اثبــات مااســند اليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مااقــدم عليــه‬\n‫مــع طلــب تشــديد العقوبــة لقــاء تعــدد ســوابقه اجلنائيــة علمــا بــان احلــق‬\n‫اخلــاص اليــزال قائمــا وبنــاء علــى مــا أجــاب بــه املتهــم حيــث انكــر‬\n‫تهمــة الضــرب واعتــرف بانــه متاســك مــع املدعــي عنــد احــدى العمائــر‬\n‫وتضاربــا وانــه أي املتهــم هــرب فلحــق بــه املدعــي وارتطــم راســه بالســيارة‬\n‫فحصلــت االصابــة وليــس لديــه اثبــات علــى ذلــك وحيــث جــرى االطــاع‬\n‫علــى اقوالــه لــدى هيئــة التحقيــق واالدعــاء العــام فوجــد معترفــا بضــرب‬\n‫املدعــي وانــه املتســبب يف اصابتــه وحيــث ان االقــرار حجــة معتبــرة‬\n‫شــرعا فيعامــل مبتقضــى اقــراره املعتبــر شــرعا ألنــه اقــرار اخــذ امــام‬\n‫جهــة رســمية مخولــه يف اخــذه ونظــرا لتعــدد ســوابقه مــن اجــل ماتقــدم‬\n‫حكمــت بادانــة املتهــم مبــا نســب اليــه واحلكــم بســجنه ســتة اشــهر‬\n‫اعتبــارا مــن مــدة توقيفــه وبجلــده ثالثــن جلــده تكــرر عليــه اربــع مــرات‬\n‫بينهــا اســبوع بــذا صــدر احلكــم وافهــم حســب االصــول فقــرر املتهــم‬\n‫قناعتــه وقــرر املدعــي العــام االعتــراض بالئحــة وصلــى اهلل علــى ســيدنا‬\n                 ‫ونبينــا محمــد وعلــى الــه وصحبــه حــرريف ‪1434/7/09‬ه ـ‬\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي انــا ‪........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة ففــي يــوم اخلميــس املوافــق ‪1434/10/8‬ه ـ أفتتحــت‬\n      ‫اجللســة الســاعة العاشــرة صباحــا وفيهــا جــرى اإلطــاع علــى قــرار‬\n      ‫املالحظــة رقــم ‪ 34316560‬يف ‪1434/9/10‬ه ـ الصــادر عــن أصحــاب‬\n      ‫الفضيلــة قضــاة اإلســتئناف الدائــرة اجلزائيــة الرابعــة مبكــة املكرمــة‬\n      ‫املشــتمل علــى املالحظــة علــى احلكــم الصــادر عنــا برقــم ‪341189434‬‬\n      ‫يف ‪1434/8/14‬ه ـ املتعلــق بدعــوى املدعــي العــام ضــد ‪........‬املتهــم يف‬\n      ‫ضــرب ‪........‬ومضمــون املالحظــة أن احلكــم علــى املدعــى عليــه مــن‬\n      ‫ســجن وجلــد قليــل وذلــك إلدانتــه بهــذه الدعــوى وملــا لــه مــن ســوابق‬\n      ‫ثمــان كلهــا يف املخــدرات والســرقات واإلعتــداء ومقاومــة رجــل االمــن‬\n      ‫لــذا يلــزم إعــادة النظــر وزيــادة عقوبتــه فاألحــكام الضعيفــه ألصحــاب‬\n      ‫الســوابق غيــر مجديــه واهلل املوفــق وبعــرض ذلــك علــى املتهــم أجــاب‬\n      ‫أمتســك باحلكم الصادر يف حقي وبعرض ذلك على املدعي العام ‪........‬‬\n      ‫أجــاب أمتســك مبــا جــاء بالالئحــة االعتراضيــه وعليــه ومتشــيا مــع ماجــاء‬\n      ‫مبالحظــة أصحــاب الفضيلــة قضــاة اإلســتئناف ولوجاهــة ماذكــر فقــد‬\n      ‫تقــرر زيــادة مــدة الســجن وزيــادة اجللــد وذلــك بجعل الســجن ثمانية أشــهر‬\n      ‫إعتبــارا مــن مــدة توقيفــه وبجعــل اجللــد خمســن جلــده تكــرر عليــه أربــع‬\n      ‫مــرات بينهــا أســبوع بــذا صــدر احلكــم وأفهــم حســب االصــول فقــرر‬\n      ‫املتهــم قناعتــه وقــرر املدعــي العــام ببقائــه علــى إعتراضــه ويلحــق ذلــك‬\n      ‫بالقرار رقم ‪ 34271857‬يف ‪1434/7/18‬هـ واهلل املســتعان وصلى اهلل‬\n                               ‫علــى ســيدنا ونبينــا محمــد حــرر يف ‪1434/10/8‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪........‬رئيــس احملكمــة اجلزائيــة باملدينــة‬\n      ‫املنــورة والقائــم بعمــل القاضــي ‪........‬أثنــاء إجازتــه ففــي يــوم االربعــاء‬\n\n\n‫‪101‬‬\n\f‫املوافــق ‪1434/12/3‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا‬\n‫وقــد عــادت املعاملــة مــن محكمــة اإلســتئناف مبكــة املكرمــة بالرقــم‬\n‫(‪ )341189434‬يف ‪1434/11/20‬ه ـ وبرفقــه احلكــم الصــادر مــن‬\n‫فضيلتــه بالرقــم (‪ )34271857‬يف ‪1434/7/18‬ه ـ واملتضمــن املصادقــة‬\n‫علــى احلكــم بالقــرار رقــم (‪ )34358482‬يف ‪1434/11/12‬ه ـ واملتعلــق‬\n‫باملتهــم ‪........‬املتهــم يف إيــذاء الغيــر ولكــي ال يخفــى جــرى التهميــش‬\n                                             ‫حــرر يف ‪1434/12/3‬ه ـ‬\n\n\n\n\n                                                                                 ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":98,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fde94e967d7766bdfd6f8cd789c86bdb10319f85dd39f62097c7eeb49228cba6","normalized_text_hash":"bbf5d335146dae2fac6e80902cd01124e2c64a799e61e707904ac3d09ed32b8b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p98-34271857"},{"id":"8258e5f2-82e5-5c2f-966b-0c450cc75489","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوجة زوجها -ثبوت إدانة املدعى عليها - تعزير بالسجن واجللد .","document_number":"3462879","case_number":"33397208","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"اعتداء -ضرب -ضرب الزوجة زوجها -ثبوت إدانة املدعى عليها - تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3462879 :‬تاريخه‪1434/3/15 :‬هـ‬\n                          ‫رقم الدعوى‪33397208:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34196942‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب‪ -‬ضــرب الزوجــة زوجهــا ‪ -‬ثبــوت إدانــة املدعــى عليهــا ‪-‬‬\n                                                        ‫تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪-1‬االعتــداء اجلســدي علــى اآلخريــن بالضــرب ونحــوه بــا مقتضــى‬\n                        ‫شــرعي موجــب للتعزيــر يف احلــق العــام واخلــاص‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليهــا بقيامهــا بضــرب‬\n      ‫زوجهــا بــكأس زجــاج علــى رأســه ‪ ،‬أدى لتمــزق بفــروة الــرأس بطــول‬\n      ‫عشــرة ســنتيمتر ‪ ،‬ومــدة الشــفاء أســبوع ‪ ،‬وطلــب إثبــات مــا أســند إليهــا‬\n      ‫وإيقــاع العقوبــة التعزيريــة عليهــا ‪ ،‬أقــرت املدعــى عليهــا بأنهــا قامــت‬\n      ‫بضــرب زوجهــا علــى وفــق مــا هــو مبــن آنف ـ ًا ‪ ،‬وذلــك لغضبهــا بعدمــا‬\n      ‫رفــض زوجهــا حضورهــا خلطبــة ابنتهــا ‪ ،‬وقيامــه بإنزالهــا مــن ســيارة‬\n      ‫األجــرة ‪ ،‬وأن املدعــي بعــد هــذه الواقعــة طلقهــا ‪ ،‬حضــر املدعــي اخلــاص‬\n      ‫وقــرر بــأن املدعيــة كانــت زوجتــه ومنعهــا مــن الذهــاب يف ســيارة‬\n      ‫األجــرة فلمــا دخــل البيــت قامــت بضربــه بــكأس زجاجــي علــى رأســه‬\n      ‫‪ ،‬ممــا أحــدث فيــه اإلصابــة وطلــب احلكــم عليهــا بتأديبهــا‪ ،‬جــرى‬\n      ‫محاولــة الصلــح بينهمــا ورفضــا الصلــح‪ ،‬باالطــاع علــى التقريــر الطبــي‬\n\n‫‪103‬‬\n\f‫املتضمــن الكشــف علــى املدعــى عليــه ووجــود متــزق بفــروة الــرأس طولــه‬\n‫ـاء علــى مــا‬\n           ‫عشــرة ســنتيمتر بآلــة غيــر حــادة ومــدة الشــفاء أســبوع‪ ،‬بنـ ً‬\n‫تقــدم مــن دعــوى املدعــي العــام واخلــاص فقــد قــررت احملكمــة ثبــوت‬\n‫إدانــة املدعــى عليهــا بضــرب املدعــي اخلــاص بــكأس زجــاج علــى رأســه‬\n‫أدى حلــدوث إصابــة بــه وحكمــت عليهــا بســجنها خمســة أيــام وجلدهــا‬\n‫خمــس جلــدات للحــق العــام ‪ ،‬وســجنها خمســة أيــام وجلدهــا خمــس‬\n‫جلــدات مقابــل احلــق اخلــاص‪ ،‬قــرر املدعــي العــام عــدم االعتــراض كمــا‬\n‫قــرر املدعــي اخلــاص القناعــة بينمــا اعترضــت املدعيــة وطلبــت اســتئناف‬\n‫احلكــم بالئحــة فأفهمــت بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                  ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/3/15‬ه ـ لــدي أنــا‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫‪........‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )33397208‬وتاريــخ ‪1433/6/11‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــرت ‪........‬ســعودية اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ( ‪ )..........‬واملعــرف بهــا مــن قبــل ابنهــا ‪........‬ســعودي اجلنســية‬\n‫مبوجــب ســجل مدنــي رقــم (………) وقــدم املدعــي العــام الئحــة‬\n‫االدعــاء املتضمنــة بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع‬\n‫الهيئــة باملنطقــة الشــرقية أدعــي علــى املذكــورة أعــاه فباالطــاع علــى‬\n‫تقريــر األحــوال األمنيــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدمــام‬\n‫تبــن أنــه بتاريــخ ‪1433/5/5‬ه ـ وردهــم بــاغ مــن أحــد املواطنــن يدعــى‬\n‫‪ -........ /‬ســعودي اجلنســية ‪ -‬يفيــد فيــه عــن تعرضــه للضــرب مــن قبــل‬\n                                                                                            ‫‪104‬‬\n\f      ‫زوجتــه املدعــى عليهــا اثــر ســوء تفاهم معها حيــث قامت بضربه بكأس‬\n      ‫وعمــل لــه ســبع غــرز وبســماع أقــوال‬\n                                             ‫زجــاج علــى رأســه وحلقــت بــه إصابــة ُ‬\n      ‫املدعــى عليهــا أفــادت عــن قيــام زوجهــا مــن منعهــا مــن حضــور خطوبــة‬\n      ‫ابنتهــا وقــام بدفعهــا مــن ســيارة الليموزيــن وإنزالهــا منــه بالقــوة وعنــد‬\n      ‫دخولهمــا البيــت عصبــت منــه وقامــت برميــه بكوب زجاج وباســتجوابها‬\n      ‫أفــادت مبثــل مــا ورد يف ســماع أقوالهــا األوليــة مضيفــة بــأن مــا ذكــر‬\n      ‫زوجهــا صحيــح حيــث قامــت بضربــه بــكأس زجــاج يف رأســه ممــا‬\n      ‫تســبب لــه بتمــزق بفــروة الــرأس ألنــه منعهــا مــن حضــور خطبــة ابنتهــا‬\n      ‫وقــد صــدر بحــق املدعــي ‪........ /‬التقريــر الطبــي رقــم (‪ )........‬الصــادر‬\n      ‫مــن مجمــع امللــك فهــد الطبــي العســكري املتضمــن أنــه بالكشــف‬\n      ‫عليــه اثــر ادعــاء مضاربــة وجــد مصابـ ًا بتمــزق بفــروة الــرأس حوالــي ‪10‬‬\n      ‫ســم بآلــة غيــر حــادة ومــدة الشــفاء أســبوع واحــد وانتهــى التحقيــق إلــى‬\n      ‫اتهــام املدعــى عليهــا برمــي زوجهــا بــكأس زجــاج علــى رأســه ممــا أدى‬\n      ‫إلــى حــدوث اإلصابــات املوضحــة يف التقريــر الطبــي املشــار إليــه وذلــك‬\n                                                            ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬مــا ورد يف اســتجوابها املرفــق علــى اللفتــن رقــم (‪ . )8-7‬وســماع‬\n      ‫أقوالهــا األوليــة املدونــة علــى الصفحتــن رقــم (‪ )12-11‬مــن محضــر‬\n                                          ‫االســتدالل املرفــق علــى اللفــة رقــم (‪.)1‬‬\n      ‫‪ -2‬التقريــر الطبــي املنــوه عنــه واملرفــق علــى اللفتــن رقــم (‪ ))3.2‬وحيــث‬\n      ‫إن مــا أقدمــت عليــه املدعــى عليهــا وهــي بكامــل أهليتهــا املعتبرة شــرع ًا‬\n      ‫ـب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتهــا مبــا ُنســب‬          ‫فعــلٌ محـ ٌ‬\n                                                                    ‫ـرم ومعاقـ ٌ‬\n      ‫إليهــا واحلكــم عليهــا بعقوبــة تعزيريــة تزجرهــا وتــردع غيرهــا وبــاهلل‬\n      ‫التوفيــق وبســؤال املدعــى عليهــا أجابــت بقولهــا مــا ذكــره املدعــي‬\n\n\n‫‪105‬‬\n\f‫العــام مــن ضربــي للمدعــي بــكأس مــن زجــاج علــى رأســه ممــا أدى إلــى‬\n‫حــدوث إصابــات بــه فهــذا صحيــح وذلــك ألنــه رفــض ذهابــي إلــى خطبــة‬\n‫ابنتــي وقــام بإنزالــي مــن ســيارة األجــرة فغضبــت عليــه وضربتــه وقــد قــام‬\n‫املدعــي بتطليقــي هــذه إجابتــي ويف نفــس اجللســة حضــر املدعــي باحلــق‬\n‫اخلــاص ‪........‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )........‬وبســؤاله عــن‬\n‫دعــواه ادعــى بقولــه إن املدعــى عليهــا كانــت زوجتــي ويف يــوم مــن األيــام‬\n‫منعتهــا مــن الذهــاب يف ســيارة أجــرة ثــم ملــا دخلــت البيــت قامــت بضربــي‬\n‫بــكأس زجاجــي علــى رأســي ممــا أحــدث فيــه إصابــة أطلــب احلكــم‬\n‫بتأديبهــا لقــاء اعتداءهــا علــي بالضــرب هــذه دعــواي وبســؤال املدعــى‬\n‫عليهــا أجابــت بقولهــا مــا ذكــره املدعــي صحيــح فقــد قمــت بضربــه‬\n‫علــى رأســه بــكأس مــن زجــاج لقــاء منعــه لــي مــن الذهــاب إلــى حفلــة‬\n‫ابنتــي هــذه إجابتــي وبعــد تدويــن مــا ســبق جــرى محاولــة اإلصــاح بــن‬\n‫الطرفــن ومت بــذل الوســع يف ذلــك وســبق أن مت تأجيــل اجللســة الســابقة‬\n‫حملاولــة اإلصــاح بينهمــا عــن طريــق مكتــب الصلــح باحملكمــة ولكن‬\n‫بــا فائــدة حيــث رفضــا الصلــح وعليــه جــرى االطــاع علــى التقريــر‬\n‫الطبــي الصــادر مــن مجمــع امللــك فهــد الطبــي العســكري برقــم (‪)........‬‬\n‫واملتضمــن أنــه بالكشــف علــى ‪........‬تبــن وجــود متــزق بفــروة الــرأس‬\n‫حوالــي (‪10‬ســم) بآلــة غيــر حــادة ومــدة الشــفاء أســبوع واحــد فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــرت املدعــى عليهــا بضــرب‬\n‫املدعــي باحلــق اخلــاص واملــرء مؤاخــذ بإقــراره و حيــث بــاءت جميــع‬\n‫محــاوالت الصلــح بالفشــل وبنــاء علــى التقريــر الطبــي املشــار إليــه أعــاه‬\n‫وحيــث إن مــا قامــت بــه املدعــى عليهــا فعــل محــرم وفيــه اعتــداء علــى‬\n‫ســامة اآلخريــن وأمنهــم وحيــث إن موجــب ذلــك التعزيــر وحيــث حصــر‬\n\n\n                                                                                     ‫‪106‬‬\n\f      ‫املدعــي باحلــق اخلــاص مطالبتــه بتأديــب املدعــى عليهــا لــذا فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليهــا بضــرب املدعــي باحلــق اخلــاص بــكأس زجــاج‬\n      ‫علــى رأســه ممــا أدى إلــى حــدوث إصابــات بــه وحكمــت عليهــا مبــا يلي ‪:‬‬\n      ‫‪ /1‬ســجنها خمســة أيــام وجلدهــا خمــس جلــدات للحــق العــام ‪ /2‬ســجنها‬\n      ‫خمســة أيــام وجلدهــا خمــس جلــدات للحــق اخلــاص وبعــرض احلكــم‬\n      ‫علــى أطــراف الدعــوى قــرر املدعــي باحلــق اخلــاص قناعتــه بــه بينمــا‬\n      ‫قــررت املدعــى عليهــا عــدم القناعــة وطلبــت االســتئناف فأجيبــت لطلبهــا‬\n      ‫وأفهمــت باملراجعــة يــوم الثالثــاء املوافق ‪1434/3/17‬هـ الســتالم نســخة‬\n      ‫مــن احلكــم وتقــدمي اعتراضهــا عليــه خــال مهلــة ثالثــن يومــا وأنــه إذا‬\n      ‫انتهــت هــذه املهلــة ولــم تتقــدم باعتراضهــا ســقط حقهــا يف ذلــك وســوف‬\n      ‫يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة وقــرر املدعــي‬\n      ‫العــام عــدم االعتــراض وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه‬\n      ‫حــرر يف ‪1434/3/15‬هــ‪.‬ويف يــوم األحــد املوافــق ‪1434/5/5‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة الثامنــة وخمــس وأربعــن دقيقــة وقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف برقــم (‪ )34/969294‬وتاريــخ ‪1434/4/29‬ه ـ‬\n      ‫املتعلقــة بدعــوى املدعــي العــام واملدعــي اخلــاص ضــد‪ ......../‬وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم (‪ )34196942‬وتاريــخ‬\n      ‫‪1434/4/24‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى إحلــاق ذلــك‬\n      ‫حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه أجمعــن ‪ .‬احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n      ‫الدائ ــرة اجلـزائي ــة الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫علــى املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/969294‬ج‪2‬وتاريــخ‬\n      ‫‪1434/4/21‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة‬\n\n\n‫‪107‬‬\n\f‫الدمــام برقــم ‪ 331103132‬وتاريــخ ‪1434/4/15‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪........ /‬املســجل برقــم‬\n‫‪ 3462879‬وتاريــخ ‪1434/3/15‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫واملدعــي اخلــاص ضــد‪......../‬يف قضيــة ضــرب زوجهــا وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                           ‫وســلم‪ .‬حــرر يف ‪1434/4/23‬هــ‪.‬‬\n\n\n\n\n                                                                                ‫‪108‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":103,"source_page_end":108,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1f3c63258442ba5ed1db040731d84bcc932fea816fcb5a70e9599ad495432a41","normalized_text_hash":"7b220ca8f3a1a5c688c48e8746c9692e85d3b5de15c181221ae86d1a4776ab03","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p103-3462879"},{"id":"282be075-721d-5bee-b117-435bf1bd712c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -سب يف مجلس احلكم -الدفع املقدم مبواجهة دعوى قائمة أمام قاض ليس هو من قبيل الشتم أو التنقص أمام الغير - التعزير إمنا يكون بثبوت كذب الدفع ال مبجرد عدم قدرة اخلصم على إثباته -صرف النظر عن دعوى املدعية.","document_number":"33434658","case_number":"33409909","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة :أنها مصابة باضطرابات عقلية وأنها حاولت االنتحار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/22","year":"1434","subject":"إيذاء -سب يف مجلس احلكم -الدفع املقدم مبواجهة دعوى قائمة أمام قاض ليس هو من قبيل الشتم أو التنقص أمام الغير - التعزير إمنا يكون بثبوت كذب الدفع ال مبجرد عدم قدرة اخلصم على إثباته -صرف النظر عن دعوى املدعية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33434658 :‬تاريخه‪1433/10/22:‬هـ‬\n                          ‫رقم الدعوى‪33409909:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3439781‬تاريخه‪1434/2/8 :‬هـ‬\n\n\n\n      ‫إيــذاء‪ -‬ســب يف مجلــس احلكــم ‪ -‬الدفــع املقــدم مبواجهــة دعــوى قائمــة‬\n      ‫أمــام قــاض ليــس هــو مــن قبيــل الشــتم أو التنقــص أمــام الغيــر ‪-‬‬\n      ‫التعزيــر إمنــا يكــون بثبــوت كــذب الدفــع ال مبجــرد عــدم قــدرة اخلصــم‬\n                            ‫علــى إثباتــه ‪ -‬صــرف النظــر عــن دعــوى املدعيــة‪.‬‬\n\n\n\n\n      ‫‪-‬مــا جــاء يف أســنى املطالــب‪) :)177/20( :‬ومنهــا أن أحــد اخلصمــن إذا‬\n      ‫قــال لصاحبــه ‪ :‬إنــه ظالــم أو فاجــر أو نحــوه يف حــال املخاصمــة يحتمــل‬\n               ‫ذلــك منــه أي وال يعــزر عليــه ذكــره النــووي يف شــرح مســلم)‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة أن املدعــى عليــه اتهمهــا أثنــاء نظــر قضيــة حضانــة‬\n      ‫أوالدهمــا املنظــورة يف احملكمــة العامــة‪ :‬أنهــا مصابــة باضطرابــات‬\n      ‫عقليــة وأنهــا حاولــت االنتحــار‪ ،‬وأن ناظــر القضيــة خاطــب مستشــفى‬\n      ‫الصحــة النفســية ثــم حكــم لهــا باحلضانــة ‪ -‬تطلــب تأديــب املدعــى‬\n      ‫عليــه علــى ذلــك ‪ -‬بعــرض الدعــوى علــى املدعــى عليــه أجــاب أن هــذا‬\n      ‫ليــس اتهــام بــل هــو حقيقــة وأن مطلقتــه املدعيــة كانــت تشــتكي ممــا‬\n      ‫ذكــر وعنــده تقاريــر طبيــة تثبــت مــا ذكــره وقــد قدمهــا لناظــر دعــوى‬\n      ‫احلضانــة وهــو بــدوره قدمهــا للمستشــفى وقــد ورد جــواب املستشــفى‬\n\n‫‪109‬‬\n\f‫بــأن مــا جــاء يف التقريــر صحيــح لكــن احلالــة قدميــة ومتاثلــت للشــفاء‬\n‫ولديــه تقريــر املستشــفى هكــذا أجــاب‪ ،‬جــرى االطــاع علــى صــورة‬\n‫مــن احلكــم املشــار لــه املبــرز مــن املدعيــة املتضمــن ورود جــواب مجمــع‬\n‫األمــل املتضمــن‪ ،‬اطــاع اللجنــة الطبيــة علــى التقاريــر املقدمــة مــن‬\n‫الــزوج الســابق والصــادرة بحــق املــرأة واملتضمــن أنهــا تعانــي مــن قرابــة‬\n‫ســبع ســنوات مــن أعــراض اكتئابيــة وأنهــا حاليــا ال تعانــي مــن أمــراض‬\n‫عقليــة‪ ،‬نظــر ًا ألنــه جــاء يف التقريــر الطبــي مــا يشــير إلــى حالــة مرضيــة‬\n‫ســابقة متاثلــت للشــفاء‪ ،‬وألن دفــع املدعــى عليــه بــأن املدعيــة مريضــة‬\n‫نفســيا دفــع قــدم مبواجهــة دعــوى قائمــة أمــام قــاض شــرعي للنظــر يف‬\n‫األحــق بحضانــة أوالدهمــا وليــس هــو مــن قبيــل الشــتم أو التنقــص أمــام‬\n‫الغيــر يف املجالــس ونحوهــا وبنــاء علــى أنــه يحــق للمتداعيــن الدفــاع عــن‬\n‫حقوقهمــا مبــا ال يتضمــن اخلــروج عــن احلــدود الشــرعية يف الدفــاع وهــذا‬\n‫الدفــع ال خــروج فيــه عــن احلــدود الشــرعية‪ ،‬والتعزيــر إمنــا يكــون بثبــوت‬\n‫كــذب الدفــع ال مبجــرد عــدم قــدرة اخلصــم علــى إثباتــه لذلــك كلــه مت‬\n‫احلكــم بصــرف النظــر عــن الدعــوى لعــدم االســتحقاق وبعــرض احلكــم‬\n‫علــى املدعيــة قــررت عــدم القناعــة وطلبــت اإلســتئناف فأجيبــت لطلبها‪،‬‬\n            ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33409909‬وتاريــخ ‪ 1433/06/17‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331144256‬وتاريــخ ‪ 1433/06/17‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/10/17‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيها حضرت ‪ ........‬نســبة ملطلقها الســابق باكســتانية اجلنسية مبوجب‬\n      ‫جــواز الســفر رقم‪........‬الصــادر مــن باكســتان ومعهــا زوجهــا حســب‬\n      ‫تعريفهمــا ‪........‬باكســتاني اجلنســية هويــة رقــم ‪ ........‬وحضــر حلضورهــا‬\n      ‫‪ ........‬باكســتاني اجلنســية هويــة رقــم ‪........‬كمــا حضــر املترجــم‬\n      ‫الرســمي ‪........‬هنــدي اجلنســية بالهويــة رقــم ‪ ........‬وادعــت ‪ ......‬قائلــة أثناء‬\n      ‫خصومــة بينــي وبــن املدعــى عليــه يف احملكمــة العامــة بالريــاض علــى‬\n      ‫حضانــة أوالدنــا قــام املدعــى عليــه باتهامــي باننــي مصابــة باضطرابــات‬\n      ‫عقليــة وحاولــت االنتحــار حــن كنــا يف…‪ ..‬وســجل هــذا االتهــام يف‬\n      ‫احلكــم الصــادر مــن احملكمــة برقــم ‪ 32177946‬يف ‪1432/7/24‬‬\n      ‫مــن احملكمــة العامــة وقــد خاطــب ناظــر القضيــة مستشــفى الصحــة‬\n      ‫النفســية ثــم حكــم لــي باحلضانــة أطلــب تأديبــه علــى قذفــه لــي هــذه‬\n      ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا هــذا ليــس‬\n      ‫اتهــام هــذا حقيقــة ومطلقتــي كانــت تشــتكي ممــا ذكــر ولــي تقاريــر‬\n      ‫طبيــة تثبــت مــا ذكرتــه وقــد قدمتهــا لناظــر دعــوى احلضانــة وهــو بــدوره‬\n      ‫قدمهــا للمستشــفى وقــد ورد جــواب املستشــفى بــأن مــا جــاء يف التقريــر‬\n      ‫صحيــح لكــن احلالــة قدميــة ومتاثلــت للشــفاء ولــدي تقريــر املستشــفى‬\n\n‫‪111‬‬\n\f‫هكــذا أجــاب وجــرى اطالعــي علــى صــورة مــن احلكــم املشــار لــه علــى‬\n‫لســان الطرفــن والصــورة قدمــت لــي مــن املدعية فوجدتهــا تتضمن ورود‬\n‫جــواب املديــر التنفيــذي ملجمــع االمــل رقــم ‪........‬يف ‪ 1432/6/26‬ومــن‬\n‫ضمــن مــا جــاء اطــاع اللجنــة الطبيــة علــى التقاريــر املقدمــة مــن الــزوج‬\n‫الســابق والصــادرة بحــق املــرأة وجــاء يف التقريــر مــا نصــه تبــن أنهــا‬\n‫تعانــي مــن قرابــة ســبع ســنوات مــن أعــراض اكتئابيــة ســابقة كمــا جــاء‬\n‫يف التقريــر أن املذكــورة حالي ـ ًا ال تعانــي مــن أمــراض عقليــة انتهــى مــا‬\n‫يحتــاج إليــه بنــاء علــى مــا تقــدم وحيــث قــد جــاء يف التقريــر الطبــي مــا‬\n‫يشــير الــى حالــة مرضيــة ســابقة متاثلــت للشــفاء وهــذا لوحــده كاف يف‬\n‫احلكــم ولــو لــم يوجــد هــذا اجلــواب يف التقريــر الطبــي فــإن دفــع املدعــى‬\n‫عليــه بــأن املدعيــة مريضــة نفســيا دفــع قــدم مبواجهــة دعــوى قائمــة أمــام‬\n‫قــاض شــرعي للنظــر يف االحــق بحضانــة أوالدهمــا وليــس هــو مــن قبيــل‬\n‫الشــتم أو التنقــص أمــام الغيــر يف املجالــس ونحوهــا وبنــاء علــى أنــه يحــق‬\n‫للمتداعيــن الدفــاع عــن حقوقهمــا مبــا ال يتضمــن اخلــروج عــن احلــدود‬\n‫الشــرعية يف الدفــاع وهــذا الدفــع ال خــروج فيــه عــن احلــدود الشــرعية‬\n‫جــاء يف أســنى املطالــب ‪( -‬ج ‪ / 20‬ص ‪ )177‬ومنهــا أن أحــد اخلصمــن‬\n‫إذا قــال لصاحبــه ‪ :‬إنــه ظالــم أو فاجــر أو نحــوه يف حــال املخاصمــة‬\n‫يحتمــل ذلــك منــه أي وال يعــزر عليــه ذكــره النــووي يف شــرح مســلم)‬\n‫انتهــى والتعزيــر امنــا يكــون بثبــوت كــذب الدفــع ال مبجــرد عــدم قــدرة‬\n‫اخلصــم علــى إثباتــه لذلــك كلــه حكمــت بصــرف النظــر عــن الدعــوى‬\n‫لعــدم االســتحقاق وبعــرض احلكــم علــى املدعيــة قــررت عــدم القناعــة‬\n‫وطلبــت االســتئناف فأجبتهــا لطلبهــا وأفهمتهــا بنظــام االعتــراض ثالثــن‬\n‫يومــا مــن تاريــخ طباعــة احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n                                                                                      ‫‪112‬‬\n\f      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/17‬ه ـ احلمــد‬\n      ‫هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪ 1433/11/13‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 01:45‬وقــد ســلمت املدعــى عليهــا الئحــة اعتراضية ورد‬\n      ‫فيهــا أنهــا تطعــن يف التقريــر الطبــي بأنــه مــزور وأنهــا طلبــت صــورة منــه‬\n      ‫مــن قاضــي احملكمــة العامــة ولــم يعطهــا وقدمــت قرائــن تــدل علــى أنــه‬\n      ‫مــزور مــن قبــل اســتحصالها علــى رخصــة قيــادة وعمــل ونحــوه وهــي أدلــة‬\n      ‫ال أرى أنهــا تــدل علــى التزويــر كمــا إن املدعــى عليها ذكرت بأن لديها‬\n      ‫شــهودا علــى أنهــا ليســت مريضــة نفســيا وهــذه أيضــا ال تأثيــر لهــا علــى‬\n      ‫احلكــم فشــهود النفــي هنــا شــهادتهم نفي مطلــق يف الزمان واملكان وال‬\n      ‫تقبــل لذلــك وبنــاء علــى أن التعزيــر إمنــا يكــون بثبــوت كــذب الدعــوى ال‬\n      ‫مبجــرد عــدم قــدرة اخلصــم علــى إثباتهــا لذلــك الزلــت علــى مــا حكمــت‬\n      ‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪ 1433/11/13‬ه ـ احلمــد هلل وحــده وبعــد ‪ ...‬فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة‬\n      ‫االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 331144256‬وتاريــخ ‪1434/1/12‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪........ /‬‬\n      ‫املســجل برقــم ‪ 33434658‬وتاريــخ ‪1433/10/22‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعيــة املــرأة ‪........ /‬ضــد ‪ (........ /‬باكســتانيي اجلنســية ) بشــأن مــا‬\n      ‫تدعــي بــه املدعيــة مــن قيــام املدعــى عليــه بالتلفــظ عليهــا وتطلــب تأديبــه‬\n      ‫علــى النحــو املوضــح بالصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل بــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n\n\n‫‪113‬‬\n\f‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                ‫‪114‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":109,"source_page_end":114,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cd158ba7bcaa8daa5af604b8fd09a3d3fabdb196b1948e6ac9cf463e8a664891","normalized_text_hash":"20841d91e97267d9292acb57e060337f08a2690c97161ca8718d907ecee02c45","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p109-33434658"},{"id":"82cd02b9-1cef-5751-98da-e86a9ded5e49","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعتداء -إتاف ملك الغير -انتحال شخصية الغير -دعوى عامة وخاصة -رجوع عن إقرار -وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا","document_number":"34234520","case_number":"33458139","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"إعتداء -إتاف ملك الغير -انتحال شخصية الغير -دعوى عامة وخاصة -رجوع عن إقرار -وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك ‪34234520 :‬تاريخه‪1434/6/7:‬هـ‬\n                          ‫رقم الدعوى‪33458139:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34279806‬تاريخه‪1434/7/25:‬هـ‬\n\n\n\n      ‫إعتــداء ‪ -‬إتــاف ملــك الغيــر ‪ -‬انتحــال شــخصية الغيــر ‪ -‬دعــوى عامــة‬\n      ‫وخاصــة ‪ -‬رجــوع عــن إقــرار ‪ -‬وجــود ســوابق قضائيــة ‪ -‬ثبــوت إدانــة‬\n      ‫املدعــى عليــه ‪ -‬تعزيــر بالســجن واجللــد وأخــذ تعهــد بعــدم العــودة ملــا‬\n                                                                           ‫بــدر منــه‪.‬‬\n\n\n\n      ‫‪-1‬قــول النبــي صلــى اهلل عليــه وســلم « كل املســلم علــى املســلم حــرام‬\n                                                ‫دمــه ومالــه وعرضــه» أخرجــه مســلم ‪.‬‬\n      ‫‪ -2‬حديــث جابــر ‪ -‬رضــي اهلل عنــه‪ -‬أن النبــي صلــى اهلل عليــه وســلم‬\n                          ‫قــال‪« :‬إن دماءكــم وأموالكــم حــرام» أخرجــه مســلم‪.‬‬\n      ‫‪-3‬حديــث أبــي هريــرة ‪-‬رضــي اهلل عنــه‪: -‬أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫تلع ُنــه ح َّتــى وإن‬            ‫قــال‪« :‬مــن أشــار إلــى أخيــه بحديــد ٍة ‪ ،‬فـ َّ‬\n                         ‫ـإن املالئك ـ َة َ‬\n                                          ‫وأمــه» أخرجــه مســلم‪.‬‬\n                                                              ‫كان أخــاه ألبيــه ِّ‬\n\n\n\n      ‫جــرى توجيــه اإلتهــام مــن اإلدعــاء العــام للمدعــى عليــه ‪ ،‬بعــد تلقــي‬\n      ‫بــاغ مــن املعتــدى عليــه واإلنتقــال للموقــع ومشــاهدة اإلطــارات مقطعــة‬\n      ‫واســتجوابه وســماع شــهادة الشــاهد ‪،‬لقيامــه بإتــاف إطــارات ســيارة‬\n      ‫املدعــي وقطــع التيــار الكهربائــي عــن منزلــه وانتحــال شــخصية الغيــر‬\n\n‫‪115‬‬\n\f‫‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة‬\n‫وادعــى عطفـ ًا علــى مــا ا ّدعــى بــه املدعــي‬\n                                             ‫عليــه ‪ ،‬حضــر املدعــي اخلــاص ّ‬\n‫العــام وطلــب إيقــاع العقوبــة التعزيريــة عليــه علــى قيامــه بقطــع التيــار‬\n‫الكهربائــي عنــه وطلــب إلزامــه بدفــع قيمــة اإلطــارات وقيمــة حتميــل‬\n‫ســيارته للورشــة ‪ ،‬رفــض املدعــى عليــه يف أول جلســة اإلجابــة وطلــب‬\n‫إحالــة املعاملــة إلــى أمــارة املنطقــة للتحقيــق يف القضيــة للشــفافية يف‬\n‫إجــراءات التحقيــق ‪ ،‬تقــدم أحــد الشــهود للشــهادة وأفــاد بقيــام املدعــى‬\n‫عليــه بالتعــدي علــى املجنــي عليــه وإحــداث تلفيــات ‪ ،‬قــام املدعــى عليــه‬\n‫بانتحــال شــخصية أخــرى حــن قبــض عليــه ‪ ،‬رجــع املدعــى عليــه عــن‬\n‫إقــراره بإنــكار الفعــل املؤثــم ‪ ،‬طلــب املدعــى اخلــاص تأديــب املدعــى‬\n‫عليــه وأفــاد بتنازلــه عــن قيمــة اإلطــارات ولكثــرة ســوابق املدعــى‬\n‫عليــه ممــا يســتوجب تشــديد العقوبــة عليــه وملجمــوع مــا تقــدم قــررت‬\n‫احملكمــة إثبــات إدانــة املدعــى عليــه باإلعتــداء علــى املدعــي اخلــاص‬\n‫بتقطيــع إطــارات ســيارته وإطفــاء الكهربــاء عــن منزلــه وانتحــال‬\n‫شــخصية غيــره وقــررت تعزيــره ألجلــه ولكثــرة ســوابقه بســجنه ســنة‬\n‫مــن تاريــخ إيقافــه مناصفــة بــن احلــق العــام واخلــاص يبــدأ أوال باحلــق العام‬\n‫ثــم اخلــاص وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات متســاوية‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا خمســة عشــر‬\n‫يومــا مناصفــة أيضــا بــن احلــق العــام واخلــاص ويبــدأ أوال باحلــق العــام‬\n‫كمــت ‪،‬‬   ‫وأخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه ومبــا ســبق َح َ‬\n‫بعــرض احلكــم علــى األطــراف قــرر املدعــي اخلــاص القناعــة بينمــا قــرر‬\n‫املدعــي العــام اإلعتــراض بــدون الئحــة وأمــا املدعــى عليــه فاإلعتــراض‬\n                       ‫بالئحــة ‪ ،‬صــدق احلكــم مــن محكمــة اإلســتئناف‪.‬‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33458139‬وتاريــخ ‪ 1433/12/26‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331297260‬وتاريــخ ‪ 1433/07/12‬ه ـ ففــي يــوم‬\n      ‫السبت املوافق‪ 1434/01/10‬هـ افتتحت اجللسة الساعة ‪ 09 : 45‬وفيها‬\n      ‫حضــر املدعــي العــام ‪ ..............‬ولــم يحضــر املدعــى عليــه لعــدم تبلغــه‬\n      ‫مبوعــد اجللســة لــذا رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي العام‬\n      ‫‪ ..........‬وادعــى قائــا‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة عنيــزة أدعــي علــى‪ ................ :‬البالــغ مــن العمــر (‪)48‬‬\n      ‫عامــا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )..........‬عــزب‬\n      ‫‪ ،‬متعلــم ‪ ،‬يقيــم يف محافظــة عنيــزة قبــض عليــه بتاريــخ ‪1433/5/4‬ه ـ‬\n      ‫وأفــرج عنــه بالكفالــة بتاريخ ‪1433/5/26‬هـ ‪.‬إنــه بتاريخ ‪1433/5/3‬هـ‬\n      ‫ورد بــاغ لشــرطة احملافظــة مــن املواطــن ‪ ، ........... /‬مفــاده ‪ /‬تعــرض‬\n      ‫إطــارات ســيارته للقطــع بســكني وإطفــاء طبلــون الكهربــاء عــن منزلــه‬\n      ‫مــن قبــل املدعــى عليــه ‪.‬وباالنتقــال للموقــع وجــدت ســيارة املدعــي مــن‬\n      ‫نــوع ‪ ...........‬ولوحــظ أن إطاراتهــا األربعــة مقطوعــة بســكني ‪.‬وبســماع‬\n      ‫شــهادة املواطــن ‪ ، ........... /‬أفــاد بأنــه شــاهد املدعــى عليــه يقــوم بتنســيم‬\n      ‫كفــرات املدعــي بســكني وقيامــه بإطفــاء الكهربــاء عــن منــزل‬\n      ‫املدعي‪.‬وباســتجوابه ‪ :‬أقــر بتقطيــع إطــارات ســيارة املدعــي وإطفــاء‬\n      ‫الكهربــاء عــن منزلــه وانتحــال شــخصية شــخص يدعــى ‪.............. /‬‬\n      ‫وانتهــى التحقيــق معــه إلــى اتهامــه بإتــاف إطــارات ســيارة املدعــي وقطع‬\n\n‫‪117‬‬\n\f‫الكهربــاء عــن منزلــه وانتحــال شــخصية الغير‪.‬وذلــك لألدلــة و القرائــن‬\n‫التاليــة ‪ -1:‬اعترافــه مبــا أســند إليــه املــدون علــى الصفحــة رقــم (‪)8‬‬\n‫مــن ملــف إجــراءات االســتالل رقــم (‪-2.)1‬شــهادة الشــاهد املدونــة علــى‬\n‫الصفحــة رقــم (‪ )3‬مــن اللفــة (‪-3.)1‬إقــراره املرفــق لفــه (‪-4.)6‬محضــر‬\n‫االنتقــال و املعاينــة املــدون علــى الصفحــة رقــم (‪ )1‬مــن ملــف إجــراءات‬\n‫االســتدالل لفــه رقــم (‪.)1‬وبالبحــث عمــا إذا كان لــه ســوابق عثر له على‬\n‫ثمــان ســوابق منهــا أربــع ســوابق ســرقة وأربــع ســوابق شــرب مســكر ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫‪ ،‬أطلــب إثبــات إدانتــه مبــا أســند إليــه و احلكــم عليــه بعقوبــة تعزيريــة‬\n‫تزجــره وتــردع غيــره وتشــديد العقوبــة عليــه لقــاء ســوابقه التــي لــم تردعه‬\n‫عقوبتهــا ‪.‬علمــا بــأن احلــق اخلــاص لــم ينتــه‪ .‬وادعــى املدعــي اخلــاص بقولــه‬\n‫أننــي أضــم دعــواي مــع املدعــي العــام وأطلــب معاقبتــه لقــاء مــا قــام به من‬\n‫إطفــاء الكهربــاء وقيمــة إتــاف اإلطــارات وقيمــة حتميــل ســيارتي إلــى‬\n‫الورشــة هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫أجــاب بقولــه أننــي أرفــض اإلجابــة علــى دعــوى املدعــي العــام واملدعــي‬\n‫اخلــاص وأطلــب إرســال معاملتــي إلــى إمــارة منطقــة القصيــم للتحقيــق‬\n‫يف املوضــوع هكــذا أجــاب ويف نفــس اجللســة حضــر ‪ .............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬وبســؤاله عمــا لديــه مــن‬\n‫شــهادة شــهد هلل بأنــه بالتاريــخ املذكــور يف الدعــوى وبعــد صــاة الظهــر‬\n‫بزمــن ســمعت صــوت طــق قــوي فلمــا خرجــت مــن بيتــي وجــدت املدعــى‬\n‫عليــه يقــوم بتقطيــع كفــرات ســيارة املدعــى اخلــاص فلمــا انتهــى قــام‬\n‫بطــرق بــاب جــاري وهــو املدعــي اخلــاص بســكن فلمــا ذهــب الغضــب‬\n‫عنــه مســكته وقــال أننــي ســأقتل صاحــب املنــزل هكــذا شــهد ولتأمــل‬\n\n\n                                                                                       ‫‪118‬‬\n\f      ‫القضيــة رفعــت اجللســةويف جلســة أخــرى حضراملدعــى العــام واملدعــى‬\n      ‫اخلــاص وحضــر حلضــوره املدعــى عليــه وجــرى ســؤال املدعــى عليــه هــل‬\n      ‫أحضــر إجابــة علــى الدعــوى فأبــرز ورقتــن هــذا نصهــا فأننــي أتقــدم‬\n      ‫لســماحتكم يف النظــر مبوضوعــي بعــن احلــق والعــدل واملســاوا ة وذلــك‬\n      ‫حيــث انــه قــد مت النظــر يف هــذه القضيــة مــن قبــل رئيــس احملكمــة يف‬\n      ‫‪1433 /9 /26‬هـ وقد مت توجيه رئيس احملكمة بخطاب رســمي وذلك‬\n      ‫للتحقيــق بدعــواي ضــد جــاري ‪ .....‬ملــا يوجــد لــدي مــن شــهود ضــده وهــم‬\n      ‫عســكري يف الشــرطة لقيامــة بســرقة منزلــي وأنــا موقــوف يف الشــرطة‬\n      ‫علــى ذمــة قضيــة بنشــر ســيارته املتوقفــة أمــام منزلــي علما بأننــي تقدمت‬\n      ‫إلــى عــدة ضبــاط ‪ 2‬وثالثهــم ضابــط الــذي قــد حقــق معــي ورفــض دعــواي‬\n      ‫عــدة مــرات ملــا بينــي ويوضــح معرفتــه خلصمــي والــدالل كثيــرة عليــه مبا‬\n      ‫يخــص حتيــزه وعــدم تنفيــذ االجــراءات القانونيــة وعــدم التحقيــق معــه‬\n      ‫وإشــعار جميــع الضبــاط بذلــك لــذى فانــي ارفــع تظلمــي إليكــم وأطالب‬\n      ‫برفــع كامــل األوراق إلــى أمــارة منطقــة القصيــم إلجــراء التحقيــق معــي‬\n      ‫ومــع ضبــاط القضيــة ‪ ........‬وخصمــي ‪ .........‬إلظهــار كافــة احلقــوق‬\n      ‫مــن كل جانــب وليــس مــن بــاب الواســطة واملعرفــة وقيامــه بتخريــب‬\n      ‫ممتلكاتــي وتكســير مواســير امليــاه بداخــل منزلــي وإتــاف إقفــال‬\n      ‫األبــواب اخلارجيــة عــدد ‪ 3‬أبــواب وإتــاف صحــن االســتقبال ورمــي‬\n      ‫حجــارة خرســانة وقــد رميــت مــن منزلــه علــى منزلــي وهــي موجــودة إلــى‬\n      ‫اآلن وكذلــك ســرقته خــزان امليــاه مــن داخــل منزلــي بواســطة رافعــة‬\n      ‫وكذلــك إفســاده زواجــي وهدمــه ملــا احــل اهلل مــن حــال باألكاذيــب‬\n      ‫وذلــك ألجــل االســتيالء علــى منزلــي باإلكــراه هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــى العــام واملدعــي اخلــاص أفــاد كل واحــد مبفــرده‬\n\n\n‫‪119‬‬\n\f‫إننــا مازلنــا علــى طلبنــا الســابق هكــذا أفــادوا ولتأمــل القضيــة رفعــت‬\n‫اجللســة احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n‫العامــة بعنيــزة افتتحــت اجللســة الســاعة احلاديــة عشــرة والنصــف صباحــا‬\n‫وفيهــا حضــر املدعــي العــام واملدعــي باحلــق اخلــاص واملدعــى عليــه‬\n‫وبتصفحــي للمعاملــة اطلعــت علــى محضــر االنتقــال واملعاينــة املــدون‬\n‫علــى الصفحــة ‪ 1‬مــن اللفــة ‪ 1‬مــن املعاملــة فوجدتــه يتضمــن مــا نصــه‬\n‫إنــه يف متــام الســاعة الرابعــة والنصــف يف مســاء يــوم االثنــن املوافــق‬\n‫‪1433/5/3‬ه ـ مت االنتقــال إلــى حــي الفيحــاء بعنيــزة وذلــك لوجــود بــاغ‬\n‫‪ ...........‬بشــأن تعــرض إطــارات ســيارته للقطــع بســكني وباالنتقــال‬\n‫وجــدت الســيارة مــن نــوع ‪ ...........‬واتضــح أن الكفــرات األربــع مقطوعــة‬\n‫بســكني وجميعهــن يف وضــع التنســيم ومت تصويرهــن ولــم يعثــر علــى‬\n‫آثــار تفيــد التحقيــق وحفظــا للواقــع جــرى إعــداد هــذا احملضــر انتهــى‬\n‫رقيــب ‪ .............‬توقيعــه نقيــب ‪ ................‬توقيعــه وعنــد وصــول القضيــة‬\n‫لهــذا احلــد رفعــت اجللســة للنطــق باحلكــم ‪ .‬احلمــد هلل وحــده وبعــد فلــدي‬\n‫أنــا ‪ ...............‬رئيــس احملكمــة العامــة بعنيــزة القائــم بعمــل فضيلــة‬\n‫القاضــي ‪ ..................‬أثنــاء تكليفــه بــدورة رســمية ففــي يــوم االثنــن‬\n‫املوافــق ‪ 1434/05/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ ............‬واملدعــي اخلــاص ‪ ..............‬واملدعــى عليــه‬\n‫وصــادق املدعيــان علــى مــا نســب لهمــا يف الدعــوى وجــرى ســؤال املدعــى‬\n‫عليــه عمــا ورد يف دعــوى املدعيــان فأجــاب قائــا مــا ذكــره املدعيــان يف‬\n‫دعواهمــا فكلــه غيــر صحيــح فلــم أتعــرض جلــاري املدعــي ‪ ...........‬بــأي‬\n‫ســوء وهــذه دعــوى كيديــه مــن أجــل أن يجبرنــي علــى بيــع اســتراحتي‬\n‫هكــذا أجــاب فســألت املدعيــان هــل لديهمــا زيــادة بينــة فأجابــا بأنــه‬\n\n\n                                                                                        ‫‪120‬‬\n\f      ‫ليــس لديهمــا ســوى مــا قدمــاه يف هــذه الدعــوى ويكتفيــان بــه هكــذا‬\n      ‫أجابــا وللتأمــل رفعــت اجللســة احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...............‬‬\n      ‫القاضــي املنتــدب املكلــف باملكتــب القضائــي اخلامــس يف احملكمــة‬\n      ‫العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بعنيــزة برقــم ‪ 33458139‬وتاريــخ ‪ 1433/12/26‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331297260‬وتاريــخ ‪ 1433/07/12‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/06/03‬ه ـ افتتحــت اجللســة الســابعة وفيهــا‬\n      ‫حضــر جميــع االطــراف املدعــي باحلــق العــام واملدعــي باحلــق اخلــاص‬\n      ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬واملدعــى‬\n      ‫عليــه وقــد جــرى منــي تــاوة مــامت ضبطــه ســابقا علــى جميــع أطــراف‬\n      ‫الدعــوى فصادقــوا عليــه جميعــا وقــرر املدعيــان باحلــق العــام واحلــق‬\n      ‫اخلــاص بقولهمــا إننــا مازلنــا علــى طلبنــا بتأديبــه لقــاء هــذه األعمــال‬\n      ‫كمــا أضــاف املدعــي باحلــق اخلــاص أننــي أطالــب بتعويضــي عــن‬\n      ‫تلفيــات اإلطــارات وقيمــة حمــل ســيارتي وأمــا بالنســبة للمدعــى عليــه‬\n      ‫فقــد صــادق علــى إنــكاره وقــرر قائــا ماذكــره املدعيــان يف دعواهمــا‬\n      ‫ضــدي فغيــر صحيــح جملــة وتفصيــا ثــم جــرى منــي ســؤال املدعــى عليــه‬\n      ‫عــن شــهادة الشــاهد فقــال غيــر صحيحــه فســألته عــن الشــاهد فقــال‬\n      ‫لــم أشــاهده يصلــي يف املســجد إطالقــا فســألته هــل بينــك وبينــه أي‬\n      ‫عــداوة فقــال ال فســألت املدعــي باحلــق اخلــاص هــل لديــك زيــادة بينــه‬\n      ‫فقــال ليــس لــدي ســوى مــا أحضــرت ومــا جــاء يف الئحــة املدعــي العــام‬\n      ‫فطلبــت منــه معدلــن لشــاهده فوعــد بإحضارهــم يف اجللســة القادمــة ثــم‬\n      ‫جــرى منــي االطــاع علــى أدلــة املدعــى العــام ومــن ذلــك إقــرار املدعــى‬\n      ‫عليــه املــدون علــى الصفحــة رقــم ‪ 8‬مــن اللفــة رقــم (‪ )1‬وهــذا نصــه (( أقــر‬\n\n\n‫‪121‬‬\n\f‫أنــا ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...........‬بأننــي‬\n‫انتحلــت شــخصية ‪ ............. /‬وذلــك ألنــه مت القبــض علــي وأنــا بحالــة‬\n‫غيــر طبيعيــة واخبرتهــم بــأن أســمي ‪ ................‬وهــذا غيــر صحيــح ألننــي‬\n‫أعــرف هــذا الشــخص حيــث كان يعمــل معــي بحــراج الريــاض وأعــرف‬\n‫أســمه رباعيــا وليــس لــي أي قصــد مــن هــذا كمــا أقــر وأعتــرف بأننــي‬\n‫قمــت بتقطيــع إطــارات ســيارة املدعــو‪ .........../‬األربــع وإطفــاء الكهربــاء‬\n‫علــى منزلــه وذلــك بســبب إيقــاف ســيارته أمــام االســتراحة اخلاصــة بــي‬\n‫وهــذا إقــرار منــي بذلــك وعليــه جــرى التوقيــع )) بصمتــه وبعرضــه علــى‬\n‫املدعــى عليــه قــال مــاورد فيــه غيــر صحيــح فســألته عــن ذلــك فقــال‬\n‫لــم أقــل مــا فيــه وقــد وقعــت عليــه ولــم أقــرأ مــا فيــه كمــا جــرى منــي‬\n‫عــرض اســتجوابه املــدون علــى الصفحــة رقــم ‪ 6‬مــن اللفــة رقــم ‪ 1‬وهــذا‬\n‫نصــه ((س‪ /‬ملــاذا قمــت بقطــع إطــارات ســيارة املدعــو ‪ .......‬؟ ج‪ /‬بســبب‬\n‫وقوفــه أمــام اســتراحتي وقــد حذرتــه بعــدم الوقــوف وهــو يرغــب بشــراء‬\n‫االســتراحة بالغصــب منــي وأنــا أرفــض ذلــك ‪ .‬س‪ /‬هــل قمــت بإطفــاء‬\n‫الكهربــاء عليــه ؟ ج‪ /‬نعــم ‪.‬س‪ /‬ملــاذا قمــت بتقطيــع الكفرات بســكني‬\n‫؟ ج‪ /‬ألنــه يرفــض اخلــروج وإخــراج ســيارته عــن بــاب اســتراحتي وقمــت‬\n‫بتقطيــع كفــرات ســيارته وإطفــاء الكهربــاء عليــه )) بصمتــه وبعرضــه‬\n‫عليــه قــال بصمــت عليــه ولــم أقــرأ مــا فيــه ومــا ورد فيــه غيــر صحيــح‬\n                        ‫هكــذا أجــاب والنتهــاء وقــت اجللســة رفعــت اجللســة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬ويف هــذه اجللســة حضــر جميــع‬\n‫األطــراف ثــم جــرى منــي ســؤال املدعــي باحلــق اخلــاص ‪ ............‬عــن‬\n‫ال مــن ‪ ...........‬ســعودي اجلنســية مبوجــب‬   ‫معدلــن للشــاهد فأحضــر ك ً‬\n‫الســجل املدنــي رقــم ‪...........‬و ‪ .............‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n                                                                                          ‫‪122‬‬\n\f      ‫املدنــي رقــم ‪ ..............‬وبســؤالهما عمــا لديهمــا شــهد كل واحــد منهمــا‬\n      ‫مبفــرده بقولــه أشــهد بــاهلل إن الشــاهد ثقــة عــدل مقبــول الشــهادة‬\n      ‫ا إننــي متنــازل عــن‬    ‫هكــذا شــهدا ثــم قــرر املدعــي باحلــق اخلــاص قائ ـ ً‬\n      ‫قيمــة إطــارات الســيارة وقيمــة حملهــا إلــى الورشــة وأطلــب فقــط تأديبــه‬\n      ‫علــى ذلــك هكــذا قــرر فبعــد ســماع الدعــوى واإلجابــة واالطــاع علــى‬\n      ‫أوراق املعاملــة ونظــر ًا إلنــكار املدعــى عليــه لدعــوى املدعــي العــام جملــة‬\n      ‫ا وبالنظــر ملــا قدمــه املدعــي العــام مــن بينــات موصلــة علــى‬            ‫وتفصي ـ ً‬\n      ‫دعــواه متمثلــة يف إقــرارات املدعــى عليــه حتقيق ـ ًا والتــي دون مضمونهــا‬\n      ‫يف اجللســة الســابقة وقــد جــرى منــي عرضهــا علــى املدعــى عليــه أال أنــه‬\n      ‫دفــع بعــدم صحتهــا وأنــه وقــع عليهــا ولــم يقــرأ مــا فيهــا وألن مــا دفــع‬\n      ‫بــه املدعــى عليــه دفــع وا ٍه وضعيــف وال ميكــن األخــذ بــه إذ لــو أخــذ بــه‬\n      ‫لضاعــت احلقــوق وألصبــح مثــل هــذا منهج ـ ًا لضعــاف النفــوس إلنــكار‬\n      ‫احلقــوق وال صــارت الكتابــة التــي أمــر اهلل بهــا ال فائــدة منهــا واملدعــى‬\n      ‫عليــه لــم يدفــع بدعــوى إكــراه أو إجبــار أوغيــره ممــا يعتبــر يف الشــريعة‬\n      ‫اإلســامية وقــد نــص الفقهــاء رحمهــم اهلل علــى أن مــن ألــزم نفســه‬\n      ‫بشــيء ألــزم بــه فكونــه لــم يقــرأ هــذا ال يعفيــه أبــد ًا مــن اإلدانــة ثــم أيضـ ًا‬\n      ‫بالنظــر إلــى لألدلــة ومــا يقويهــا فشــهادة الشــاهد صريحــة بذلــك ونظــر ًا‬\n      ‫ألن الرجــوع عــن اإلقــرار يف حقــوق اهلل التــي ال تــدرأ بالشــبهات ال يقبــل‬\n      ‫نــص علــى ذلــك يف شــرح منتهــى اإليــرادات (‪ )340/4‬وابــن قدامــه يف‬\n      ‫املغنــى (‪ )96/5‬وقــال ال نعلــم فيــه خالفـ ًا ويدخــل دخــو ًال أوليــا وقــد نــص‬\n      ‫عليــه الفقهــاء أيض ـ ًا احلقــوق املتعلقــة بالعبــاد واملبنيــة علــى املشــاحة ال‬\n      ‫املســاملة وحلرمــة هــذه األفعــال يف الشــريعة اإلســامية وملــا فيهــا مــن إثــارة‬\n      ‫الرعــب يف اآلمنــن واســتخفاف يف هــذه النعمــة العظيمــة وجتــرؤ عليهــا‬\n\n\n‫‪123‬‬\n\f‫وملــا يف هــذا الفعــل مــن اعتــداء علــى املســلم وقــد نهــى النبــي صلــى اهلل‬\n‫عليــه وســلم عــن ذلــك فقــد قــال علــي الصــاة والســام (كل املســلم‬\n‫علــى املســلم حــرام دمــه ومالــه وعرضــه ) أخرجــه مســلم وقــد قــال عليــه‬\n‫الصــاة والســام (إن دمائكــم وأموالكــم وأعراضكــم عليكــم‬\n‫حــرام ) وقــال عليــه الصــاة والســام (مــن أشــار إلــى أخيــه بحديــده )‬\n‫واألدلــة احملــذرة مــن هــذا الفعــل كثيــرة ثــم بالنظــر ملاضــي املدعــى عليــه‬\n‫وتعــدد ســوابقه واســتمراء اجلرميــة يف نفســه ممــا يســتلزم منــه تشــديد‬\n‫العقوبــة يف حقــه ملــا ســبق كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪.........‬‬\n‫باالعتــداء علــى أخيــه املســلم ‪ ............‬بتقطيــع كفــرات ســيارته وإطفــاء‬\n‫الكهربــاء عــن منزلــه وبانتحــال شــخصية الغيــر وقــررت تعزيــره علــى‬\n‫ذلــك مــع األخــذ باالعتبــار ســوابقه املتعــددة بســجنه ســنة حتســب منهــا‬\n‫مــدة اإليقــاف مــا لــم يكــن مســجون ًا يف قضيــة أخرى فتبدأ مدة الســجن‬\n‫هــذه بعــد انتهــاء القضيــة املســجون بســببها ويكــون الســجن مناصفــة‬\n‫بــن احلقــن العــام واخلــاص يبــدأ أوال باحلــق العــام وبجلــده ثالثمائــة جلــدة‬\n‫مفرقــه علــى ســت فتــرات متســاوية بواقــع خمســن جلــده يف كل فتــرة‬\n‫بــن كل فتــرة واألخــرى خمســة عشــر يومـ ًا مناصفــة بــن احلقــن العــام‬\n‫واخلــاص ويبــدأ أو ًال باحلــق العــام وبأخــذ التعهــد عليــه بعــدم العــودة ملثــل‬\n‫مــا بــدر منــه ومبــا ســبق كلــه حكمــت وبعــرض احلكــم علــى جميــع‬\n‫األطــراف قــرر املدعــي العــام االعتــراض مكتفي ـ ًا مبــا جــاء يف الئحــة‬\n‫الدعــوى كمــا قــرر املدعــي باحلــق اخلــاص قناعتــه باحلكم وقــرر املدعى‬\n‫عليــه اعتراضــه علــى احلكــم بالئحــة اعتراضيــة فجــرى منــي تســليمه‬\n‫ـراض عليــه خــال ثالثــن يومـ ًا مــن تاريــخ هــذا‬   ‫نســخة مــن القــرار لالعتـ ِ‬\n‫اليــوم وأفهمتــه بأنــه إذا لــم يتقــدم باعتراضــه خــال هــذه املــدة فــإن حقــه‬\n\n\n                                                                                           ‫‪124‬‬\n\f      ‫يف تقــدمي الالئحــة يســقط وترفــع املعاملــة حملكمــة االســتئناف ففهــم‬\n      ‫ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪ 1434/06/07‬هــ‪ .‬احلمــد هلل وحــده وبعــد فقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف برفقهــا قــرار احملكمــة ومضمونــه‬\n                                                         ‫املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪125‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":115,"source_page_end":125,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"abf4ecf146b65bd4360b94cec155ef2b4332a0057038c0cf9cab4c0b28109ef9","normalized_text_hash":"6da3b35ac926ea1747b2e1ed7937402f58cb06333b1ae63df47845f8a3167dee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p115-34234520"},{"id":"06f50e90-b6a9-549e-b087-257f383f54a6","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إحداث إصابة -تعزير بالسجن واجللد -أخذ تعهد بعدم تكرار ما بدر منه .","document_number":"34180038","case_number":"33562319","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف 126 احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/06","year":"1434","subject":"اعتداء -ضرب -إحداث إصابة -تعزير بالسجن واجللد -أخذ تعهد بعدم تكرار ما بدر منه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34180038:‬تاريخه‪1434/04/06 :‬هـ‬\n                    ‫رقم الدعوى‪33562319:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34214853‬تاريخه‪1434/05/18:‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬إحــداث إصابــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬أخــذ‬\n                                     ‫تعهــد بعــدم تكــرار مــا بــدر منــه ‪.‬‬\n\n\n\n\n                          ‫‪ -1‬الفائدة الفقهية « أن املرء مؤاخذ بإقراره »‬\n                  ‫‪ -2‬الفائدة الفقهية « إقراراإلنسان على نفسه مقبول »‬\n\n\n\n\n‫الئحــة الدعــوى العامــة ضــد املدعــى عليهمــا بأنــه مت القبــض عليهمــا‬\n‫بعــد بــاغ حــدوث مشــاجرة بينهمــا علــى إثــر ســوء تفاهــم ‪ ،‬نتــج عنــه‬\n‫إصابتهمــا وقــد أســفر التحقيــق عــن توجيــه اإلتهــام لهمــا باإلعتــداء علــى‬\n‫بعضهمــا و التســبب يف اإلصابــة التــي حلقــت بــكل منهمــا علــى إثــر ســوء‬\n‫تفاهــم وطلــب املدعــي العــام عقوبتهمــا بعقوبــة تعزيريــة ‪ ،‬أجــاب املدعــى‬\n‫عليهمــا باملصادقــة علــى دعــوى املدعــي العــام ‪،‬صــدر احلكــم بتعزيــر‬\n‫املدعــى عليــه األول بالســجن شــهر و جلــده مائــة جلــدة علــى دفعتــن و‬\n‫أخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه ‪ ،‬تعزيــر املدعــى عليــه الثاني‬\n‫بالســجن خمســة وعشــرين يومــا و جلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n‫وأخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه ‪ ،‬مت تصديــق احلكــم مــن‬\n                                                             ‫محكمــة االســتئناف‬\n\n                                                                                           ‫‪126‬‬\n\f      ‫احلمــد هلل وحــده وبعــد حضــر املدعــي العــام ‪ .....‬بالســجل املدنــي رقــم‬\n      ‫(‪ ).....‬وحضــر حلضــوره املدعــى عليهمــا ‪ .......‬الســعودي بالســجل املدنــي‬\n      ‫رقــم (‪ ).....‬و‪ .....‬الســعودي بالســجل املدنــي رقــم (‪ )...‬وبســؤال املدعــي‬\n      ‫العــام عــن دعــواه قــال بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام‬\n                                        ‫مبحافظــة األحســاء أدعــي علــى كل مــن‪/‬‬\n      ‫‪ ،...... .1‬البالغ من العمر(‪ )46‬عاماً‪ ،‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم (‪ ،)....‬عســكري باحلــرس الوطنــي‪ ،‬محصــن‪ ،‬قبــض عليــه‬\n      ‫بتاريــخ ‪1433/3/5‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ ‪1433/3/6‬ه ـ‬\n                                                  ‫يســكن محافظــة األحســاء‪............/‬‬\n      ‫‪ ، ...... .2‬البالغ من العمر(‪ )46‬عاماً‪ ،‬سعودي اجلنسية مبوجب السجل‬\n      ‫املدنــي رقــم (‪ ،)....‬عســكري باحلــرس الوطنــي‪ ،‬محصــن‪ ،‬قبــض عليــه‬\n      ‫بتاريــخ ‪1433/3/5‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ ‪1433/3/6‬ه ـ‬\n      ‫يســكن محافظــة األحساء‪/‬إســكان احلــرس الوطنــي إنــه بتاريــخ‬\n      ‫‪1433/3/5‬ه ـ قبــض عليهمــا مــن قبــل الشــرطة العســكرية التابعــة‬\n      ‫للحــرس الوطنــي مبحافظــة األحســاء إثــر ورود كتــاب قائــد مدفعيــة‬\n      ‫امليــدان الثانيــة املتضمــن حصــول مشــاجرة بــن املدعــى عليهمــا علــى إثــر‬\n      ‫ســوء تفاهــم بينهمــا ونتــج عنــه إصابتهمــا‪ ،‬وقــد صــدر بحــق األول تقريــر‬\n      ‫طبــي مــن الشــؤون الصحيــة باحلــرس الوطنــي رقــم (‪)03/06/1967‬‬\n      ‫وتاريــخ ‪2011/1/20‬م املتضمــن وجــود جــرح ســطحي باجلبهــة ومــده‬\n      ‫شــفائه أقــل مــن خمســة عشــر يوم ـاً‪ ،‬وقــد صــدر بحــق الثانــي تقريــر‬\n      ‫طبــي مــن الشــؤون الصحيــة باحلــرس الوطنــي رقــم (‪)42/10/1967‬‬\n\n‫‪127‬‬\n\f‫وتاريــخ ‪2011/3/29‬م املتضمــن وجــود جــرح بقمة الرأس(‪ )1,3‬ســطحي‬\n‫ومت خياطتــه ومــده شــفائه أكثــر مــن خمســة عشــر يومـاً‪ .‬وباســتجواب‬\n‫املدعــى عليــه األول‪ :‬أقــر باعتدائــه علــى املدعــى عليــه الثانــي علــى إثــر‬\n‫ســوء تفاهــم بينهمــا وقيامــه بضربــه علــى رأســه بواســطة ســيخ حديــدي‪.‬‬\n‫وباســتجواب املدعــى عليــه الثانــي‪ :‬أفــاد أنــه أثنــاء تواجــده مبقــر الرمايــة‬\n‫تعــرض لالعتــداء بالضــرب بواســطة ســيخ حديــدي علــى رأســه مــن قبــل‬\n‫املدعــى عليــه األول علــى إثــر ســوء تفاهــم بينهمــا‪ .‬وقــد أســفر التحقيــق‬\n‫عــن توجيــه االتهــام لهمــا باالعتــداء علــى بعضهمــا والتســبب باإلصابــة‬\n‫التــي حلقــت كل منهمــا علــى إثــر ســوء تفاهــم بينهمــا‪ ،‬وذلــك لألدلــة‬\n                                                                      ‫والقرائــن التاليــة‪:‬‬\n‫‪ .1‬أقوالهمــا املدونــة علــى الصفحــات رقــم(‪ )8،4،3‬مــن ملــف االســتدالل‬\n                                                                             ‫لفه رقــم(‪.)2‬‬\n    ‫‪ .2‬التقريران الطبيان املرفق صوره منهما على اللفتني رقم(‪.)11،10‬‬\n                                   ‫‪ .3‬محضر الواقعة املرفق على اللفة رقم(‪)13‬‬\n‫وببحــث ســوابقهما تبــن خلــو ســجلهما مــن الســوابق اجلنائيــة‪ .‬وحيــث إن‬\n                                                                                         ‫ما‬\n‫أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليهمــا واحلكــم‬\n‫عليهمــا بعقوبــة تعزيريــة لقــاء مــا أســند إليهمــا مــن اتهــام [علمـ ًا بــأن احلــق‬\n‫اخلــاص انتهــى بالتنــازل]‪ .‬هــذه دعواي وبســؤال املدعى عليــه األول ‪ ....‬عن‬\n‫دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام مــن قيامي‬\n‫باالعتــداء علــى املدعــى عليــه الثانــي وذلــك بضربــه بســيخ حديــدي علــى‬\n‫رأســه ممــا ســبب لــه اإلصابــة املذكــورة بالدعــوى فصحيــح وســبب ذلــك‬\n\n\n                                                                                              ‫‪128‬‬\n\f      ‫ســوء التفاهــم بينــي وبينــه هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي‬\n      ‫‪ ....‬عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العام من‬\n      ‫قيامــي باالعتــداء علــى املدعــى عليــه األول وذلــك بضربــه بســيخ حديــدي‬\n      ‫علــى رأســه ممــا ســبب لــه اإلصابــة املذكــورة بالدعــوى فصحيــح وســبب‬\n      ‫ذلــك ســوء تفاهــم بينــي وبينــه هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليهمــا بدعــوى املدعــي العــام‬\n      ‫ولكــون هــذا اإلقــرار قــد صــدر مــن مكلــف ‪ -‬عاقــل بالــغ ‪ -‬وللقاعــدة‬\n      ‫الفقهيــة ((أن املــرء مؤاخــذ بإقــراره)) والقاعــدة ((إقــرار اإلنســان علــى‬\n      ‫نفســه مقبــول)) املنثــور مــن القواعــد للزركشــي [ج‪ ]188/1‬واألشــباه‬\n      ‫والنظائــر للســيوطي [ج‪ ]465/1‬ودرر احلــكام [ج‪ ]79/1‬وبعــد االطــاع‬\n      ‫علــى التقريــر الطبــي لذلــك كلــه فقــد قــررت مــا يلــي‪ :‬القســم األول‪:‬‬\n      ‫مــا يتعلــق باملدعــى عليــه األول ‪ :...‬أوال‪ :‬ثبــت لــدي قيــام املدعــى عليــه‬\n      ‫األول باالعتــداء علــى املدعــى عليــه الثانــي وذلــك بضربــه بســيخ حديــدي‬\n      ‫علــى رأســه ممــا نتــج عنــه اإلصابــة املذكــورة بالدعــوى وقــررت تعزيــره‬\n      ‫لقــاء ذلــك بســجنه ملــدة شــهر وجلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n      ‫متســاويتني بــن كل دفعــة وأخــرى عشــرة أيــام ثانيــا‪ :‬أخــذ التعهــد‬\n      ‫الشــديد عليــه بعــدم تكــرار مــا بــدر منــه‪ .‬القســم الثانــي‪ :‬مــا يتعلــق‬\n      ‫باملدعــى عليــه الثانــي ‪ :....‬أوال‪ :‬ثبــت لــدي قيــام املدعــى عليــه الثانــي‬\n      ‫باالعتــداء علــى املدعــى عليــه األول وذلــك بضربــه بســيخ حديــدي علــى‬\n      ‫رأســه ممــا نتــج عنــه اإلصابــة املذكــورة بالدعــوى وقــررت تعزيــره لقــاء‬\n      ‫ذلــك بســجنه ملــدة خمســة وعشــرين يومــا وجلــده مائــة جلــدة مفرقــة‬\n      ‫علــى دفعتــن متســاويتني بــن كل دفعــة وأخــرى عشــرة أيــام ثانيــا‪:‬‬\n      ‫أخــذ التعهــد الشــديد عليــه بعــدم تكــرار مــا بــدر منــه ومبــا ســبق كلــه‬\n\n\n‫‪129‬‬\n\f‫حكمــت وبعرضــه علــى املدعــى عليهمــا قــررا القناعــة بــه كمــا قــرر‬\n‫املدعــي العــام املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن‬\n‫تقــدمي الئحــة اعتراضيــة وبذلــك تكــون القضيــة منتهيــة وقــررت بعــث‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم‬\n‫حســب املتبــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                  ‫وصحبــه وســلم تســليما كثيــرا‪.‬‬\n‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة ‪ ............‬علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1084905‬ج‪ 2‬وتاريــخ ‪1434/05/04‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 34623860‬وتاريــخ ‪1434/04/28‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪ ..... /‬املســجل‬\n‫برقــم ‪ 34180038‬وتاريــخ ‪1434/04/06‬ه ـ اخلــاص بدعوى‪/‬املدعــي‬\n‫كل مــن‪ ..../1‬و‪ ..... /2‬يف قضيــة مضاربــه وقــد تضمــن‬             ‫العــام ضــد ٍ‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                  ‫‪1434/05/18‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":126,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e9be0acb6f4129dfb7522ef2b9fad398118b5411e99c55c407545025f135e4b","normalized_text_hash":"daf9bfa5973f6ecfb6acfefa43c157107bf381abc465fd6eea56c2178943b13f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p126-34180038"},{"id":"87db280b-e132-5082-8037-c905fd452457","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -تسبب يف إصابات -تعزير بالسجن و اجللد ،تعزير بالتوبيخ -تعهد.","document_number":"3420263","case_number":"33567741","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية الثالثية الثانية رقم 3437333ج 2/وتاريخ","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/24","year":"1434","subject":"اعتداء -ضرب -تسبب يف إصابات -تعزير بالسجن و اجللد ،تعزير بالتوبيخ -تعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3420263:‬تاريخه‪1434/01/24 :‬هـ‬\n                          ‫رقم الدعوى‪33567741:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3437333‬تاريخه‪1434/02/13:‬هـ‬\n\n\n\n      ‫اعتــداء ‪-‬ضــرب ‪ -‬تســبب يف إصابــات‪ -‬تعزيــر بالســجن و اجللــد ‪ ،‬تعزيــر‬\n                                                             ‫بالتوبيــخ ‪ -‬تعهــد‪.‬‬\n\n\n\n\n                    ‫‪-1‬قول اهلل تعالى «وال تفسدوا يف األرض بعد إصالحها»‬\n                           ‫‪-2‬قوله تعالى «وال تعتدوا إن اهلل ال يحب املعتدين»‬\n      ‫‪-3‬قولــه صلــى اهلل عليــه وســلم «كل املســلم علــى املســلم حــرام دمــه‬\n                                                               ‫ومالــه و عرضــه»‬\n      ‫‪-4‬قولــه صلــى اهلل عليــه وســلم «فــان دمائكــم و أموالكــم و أعراضكــم‬\n                       ‫حــرام عليكــم كحرمــة يومكــم هــذا يف بلدكــم هــذا»‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد ســبعة أشــخاص‪ ،‬أربعــة مواطنــن وثالثــة‬\n      ‫وافديــن ‪ ،‬حيــث مت القبــض عليهــم بعــد بــاغ مــن الوافديــن الثالثــة مــن‬\n      ‫تعرضهــم للضــرب مــن قبــل املدعــى عليهــم املواطنــن األربعــه أثنــاء قيــام‬\n      ‫الوافديــن بالعمــل يف محــل حالقــة ‪ ،‬حيــث حــدث إعتــداء بالضــرب بــن‬\n      ‫الطرفــن وقــد أســفر التحقيــق معهــم عــن توجيــه اإلتهــام لهــم باإلعتــداء‬\n      ‫علــى بعضهــم البعــض بــأدوات حــادة مــن قبــل املواطنــن والتســبب لهــم‬\n      ‫باإلصابــات التــي حلقــت بهــم علــى إثــر ســوء تفاهــم بينهــم و طلــب املدعــي‬\n\n‫‪131‬‬\n\f‫العــام إثبــات مــا اســند إليهــم و احلكــم عليهــم بعقوبــة تعزيزيــة‪ ،‬أقــر‬\n‫املدعــي عليهــم األول والثانــي والثالــث بالدعــوى وأنكــر املدعــي عليــه‬\n‫الرابــع ‪ ،‬أفــاد املدعــي عليــه الوافــد اخلامــس بــان االعتــداء عليــه مت يف‬\n‫احملــل كمــا أفــاد املدعــي عليــه الســابع بأنــه ال صحــة مبشــاركته يف‬\n‫االعتــداء ‪،‬عــدم وجــود بينــة للمدعــي العــام تثبــت مــا اســند للمدعــى‬\n‫عليهــم الرابــع واخلامــس والســادس و الســابع ثبــوت إدانــة األول والثانــي‬\n‫والثالــث مبــا اســند إليهــم ‪ ،‬واحلكــم علــى األول بالســجن ثالثــة أشــهر‬\n‫واجللــد مائــة وعشــرين جلــدة مفرقــة علــى ثــاث دفعــات ‪ ،‬واحلكــم علــى‬\n‫الثانــي والثالــث بالســجن خمســة وأربعــن يومــا واجللــد ثمانــن جلــدة‬\n‫مفرقــة علــى دفعتــن ‪ ،‬عــدم ثبــوت إدانــة الرابــع واخلامــس والســادس‬\n‫والســابع باالشــتراك يف املضاربــة ورد دعــوى املدعــي العــام بإثبــات‬\n‫ذلك‪،‬وثبــوت إدانــة الرابــع واخلامــس والســادس والســابع بحصــول مشــادة‬\n‫كالميــة أدت للمضاربــة ومت تعزيرهــم بالتوبيــخ والتقريــع والتوجيــه‬\n‫بأخــذ التعهــد عليهــم بعــدم العــودة ملــا بــدر منهــم ‪،‬تصديــق احلكــم مــن‬\n                                                       ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫فلدي أنا‬\n     ‫َّ‬    ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى املعاملــة الواردة‬‫‪ .........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء واملقيــدة‬\n‫بهــذه احملكمــة برقــم‪ 331676227‬وتاريخ‪1433/09/10‬ه ـ واحملالــة‬\n‫إلينــا مــن فضيلــة الرئيــس برقم‪33567741‬وتاريخ‪1433/09/10‬ه ـ‬\n‫فتحــت اجللســة وفيهــا حضــر املدعــي العــام امل َُع ّمــد بالترافــع أمــام‬\n\n                                                                                        ‫‪132‬‬\n\f      ‫احملكمــة طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق‬\n      ‫ا‪:‬‬  ‫واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة اإلدعــاء العــام مبحافظــة األحســاء‬\n      ‫أدعــي علــى ‪ ........‬وأفــرج عنــه بالكفالــة احلضوريــة‪ ،.......‬قبــض عليــه‬\n      ‫وأفــرج عنــه بالكفالــة احلضوريــة ‪ ،‬قبــض عليــه وأفــرج عنــه بالكفالــة‬\n      ‫احلضوريــة ‪ ،‬وأفــرج عنــه بالكفالــة احلضوريــة ‪ ،‬وأفــرج عنــه بالكفالــة‬\n      ‫احلضوريــة‪ ،‬وأفــرج عنــه بالكفالــة احلضوريــة‪ ،‬قبــض عليــه وأفــرج عنــه‬\n      ‫بالكفالــة مت القبــض عليهــم علــى إثــر بــاغ مــن املدعــى عليــه اخلامــس‬\n      ‫والســادس والســابع عــن تعرضهــم للضــرب أثنــاء قيامهــم بالعمــل باحملــل‬\n      ‫املســمى الواقــع علــى مــن قبــل شــخصان ســعوديان بســبب خــاف‬\n      ‫بينهمــا وتعــرض كل مــن الطرفــن لإلصابــة‪ .‬باالنتقــال إلــى احملــل‪:‬‬\n      ‫شــوهد احملــل مبعثــر بالكامــل وعثــر علــى عــدد (‪ )2‬عصــى ( عجــرى‬\n      ‫) احدهمــا مكســورة كمــا شــوهد آلــة البخــار متعرضــة للتكســير‬\n      ‫ويوجــد بقــع دمــاء علــى أرضيــة احملــل ‪ .‬وقــد اثبــت التقريــر الطبــي رقــم‬\n      ‫بحــق املدعــى عليــه الســابع املتضمــن (يشــتكي مــن عضــه علــى اخلــد‬\n      ‫األيســر وكدمــات خفيفــه متفرقــة يف أنحــاء اجلســم ) ومــدة الشــفاء‬\n      ‫يومــان كمــا اثبــت التقريــر الطبــي رقــم (املتضمــن ( جــرح قطعــي يف‬\n      ‫فــروة الــرأس وقطــع أخــر يف اليــد اليســرى وكدمــات متفرقــة ) ومــدة‬\n      ‫الشــفاء ثالثــة أيــام مالــم حتــدث مضاعفــات ‪.‬و التقريــر الطبــي رقــم‬\n      ‫‪ ........‬مــن ذات املستشــفى بحــق املدعــى عليــه اخلامــس املتضمــن رض‬\n      ‫راســي و كســر باجلمجمــه مــع نــزف خــارج اجلافيــة ومــدة الشــفاء شــهر‬\n      ‫مالــم حتــدث مضاعفــات و التقريــر الطبــي الصــادر مــن بحــق املدعــى‬\n      ‫عليــه األول واملتضمــن جــرح قطعــي باجلهــة اليســرى مــن الوجــه بطــول (‬\n\n\n‫‪133‬‬\n\f‫‪ 2‬ســم) مــع فقــدان اجللــد وجــرح باخلــد األميــن بطــول (‪1‬ســم) هــذه اجلــروح‬\n‫علــى األغلــب نتيجــة األصابــة بآلــه حــادة ومــدة الشــفاء أســبوع مــا لــم‬\n‫حتــدث مضاعفــات ‪ .‬وباســتجواب املدعــى عليــه األول أفــاد بأنــه يف يــوم‬\n‫ذهــب إلــى صالــون وأثنــاء قيــام املدعــى عليــه اخلامــس بحالقتــة حــدث‬\n‫ســوء تفاهــم بينهمــا بســبب كثــرة الــكالم مــن املدعــى عليــه اخلامــس‬\n‫أثنــاء احلالقــة بلغــة اليفهمهــا ممــا ادى إلــى مشــادة بالــكالم فتجمعــوا‬\n‫حولــه مجموعــة أشــخاص مــن وقامــوا باالعتــداء عليــه وقــام ( املدعــى‬\n‫عليــه الرابــع ) بفــض النــزاع بينهمــا أعقبهــا توجهــه يف يــوم إلــى مغســلة‬\n‫ال مــن‬ ‫الكرامــه للمالبــس الواقعــة بجــوار ذلــك الصالــون وشــاهد ك ً‬\n‫اخلامــس والســابع يقومــان باالســتهزاء بــه بســبب مــا حصــل بينهما ســابق ًا‬\n‫فتوجــه إلــى ســيارته وأخــذ عصــا ( عجــرى ) ودخــل لهمــا بالصالــون وقــام‬\n‫بضــرب املدعــى عليــه الســابع علــى رأســه كذلــك قــام بضــرب املدعــى‬\n‫عليــه اخلامــس بقدمــه علــى وجهــه أثنــاء مــا شــاهده ســاقط علــى األرض‬\n‫علــى حــد زعمــه ‪ .‬وباســتجواب‪( /‬فــرزت لــه اوراق لالختــاف يف جهــة‬\n‫االختصــاص) أفــاد بانــه علــم عــن تعــرض ابــن عمه‪/‬املدعــى عليــه األول‬\n‫للضــرب مــن قبــل مجموعــة أشــخاص وعنــد زيارتــه لــه شــاهد شــقيقه‬\n‫املدعــى عليــه األول والثالــث عنــده‪ ،‬فتوجهــوا جميعـ ًا إلــى صالــون التــل‬\n‫لالخــذ بثأرهــم وبالدخــول للصالــون كان بحــوزة كل مــن ‪/‬املدعــى‬\n‫عليــه األول والثانــي والرابــع عصــا ( عجــرى ) ودوره كان االمســاك‬\n‫باألشــخاص حتــى يتمكــن زمالئــه مــن االعتــداء عليهــم‪ .‬وباســتجواب‬\n‫املدعــى عليــه الثانــي أفــاد بأنــه ذهــب الــى منــزل ابــن عمه‪/‬املدعــى عليــه‬\n‫األول مــن اجــل زيارتــه واالطمئنــان عليــه كونــه تعــرض للضــرب مــن‬\n‫قبــل مجموعــة أشــخاص يعملــون حالقــن فشــاهد عنده شــقيقه‪/‬املدعى‬\n\n\n                                                                                      ‫‪134‬‬\n\f      ‫عليــه الثالــث وابــن عمــه وأثنــاء التحــدث معــه فهــم منــه بأنــه يرغــب‬\n      ‫باالنتقــام مــن األشــخاص الذيــن قامــوا بضربــه وإحداث إصابــة يف وجهه‬\n      ‫فتوجهــوا معــه علــى ســيارته التــي مــن نــوع هايلكــس الــى صالــون التــل‬\n      ‫ونزلــوا ســوي ًا وكان بحوزتــه هــو و‪/‬املدعــى عليــه األول عصــا (عجــرى )‬\n      ‫فدخلــوا الصالــون وتوجــه املدعــى عليــه األول إلــى الشــخص الذي تســبب‬\n      ‫يف إصابتــه فقــام بضربــه وضــرب شــخص آخــر قــام بضربــه علــى رأســه‬\n      ‫وتبــن لــه الحقـ ًا بأنــه املدعــى عليــه اخلامــس وكان املدعــى عليــه الثالــث‬\n      ‫واقفــن علــى بــاب الصالــون مينعــون األشــخاص مــن اخلــروج مــن الصالون‪.‬‬\n      ‫وباســتجواب املدعــى عليــه الثالــث افــاد أنــه أثنــاء تواجــده مبنزلــه رفــق‬\n      ‫ال مــن لإلطمئنــان‬    ‫شــقيقه‪/‬املدعى عليــه األول حضــرا لزيارتهــم ك ً‬\n      ‫علــى شــقيقه‪/‬املدعى عليــه األول بســبب تعرضــه للضــرب مــن قبــل‬\n      ‫مجموعــة أشــخاص يعملــون بصالــون التــل وأثنــاء جلوســهم اتفقــوا علــى‬\n      ‫التوجــه الــى ذلــك الصالــون لالنتقــام وأخــذ حــق املدعــى عليــه املذكــور‬\n      ‫وعنــد وصولهــم قامــوا بالتهجــم علــى العاملــن بذلــك الصالــون وكان‬\n      ‫ال مــن املدعــى عليــه األول عصــى ( عجــرى ) حيــث اعتــدى‬          ‫بحــوزة ك ً‬\n      ‫املدعــى عليــه األول أحدهــم والــذي اتضــح بأنــه املدعــى عليــه الســابع‬\n      ‫وتســبب بإصابتــه كذلــك قام‪/‬املدعــى عليــه األول املذكــور باالعتــداء‬\n      ‫علــى األخــر والــذي اتضــح بأنــه يدعى‪/‬املدعــى عليــه اخلامــس وتســبب‬\n      ‫بإصابتــه وكان دوره املســاعده حيــث حصلــت مشــادة باأليــدي بينهمــا‬\n      ‫وبــن شــخص ثالــث ‪ .‬وباســتجواب املدعــى عليــه الرابــع أفــاد بأنــه أثنــاء‬\n      ‫تواجــده بصالــون التــل وانتظــاره دوره للحالقــه حصلــت مشــاجرة بــن‬\n      ‫أحــد الزبائــن وأحــد العاملــن وتوجــه جميــع العاملــن باحملــل إلــى جهــة‬\n      ‫املشــاجرة وتبــن لــه بــأن أحــد أطــراف املشــاجرة هــو املدعــى عليــه األول‬\n\n\n‫‪135‬‬\n\f‫وهــو أحــد أقاربــه فحــاول التفريــق بينهــم إال أنهــم قامــوا باالعتــداء عليــه‬\n‫أيضـ ًا فقــام بالدفــاع عــن نفســه والحــظ أحدهــم والــذي تبــن لــه الحقـ ًا‬\n‫بأنــه املدعــى عليــه الســابع املذكــور يحمــل بيــده أداه حــاده لــم يذكــر‬\n‫نوعهــا وحــاول ضــرب فقــام باالمســاك بــه وانتهــت تلك املضاربــة بحدوث‬\n‫اصابــات بســيطة يف كال الطرفــن وباســتجواب املدعــى عليــه اخلامــس‬\n‫والســادس والســابع أفــادوا بأنهــم أثنــاء قيامهــم بعملهــم بالصالــون حضر‬\n‫لــه املدعــى عليــه األول ) مــن أجــل حالقــة ذقنــه وعندمــا بــدأ بحالقتــه‬\n‫لــم تعجبــه احلالقــة وحــدث ســوء تفاهــم بينهــم نتــج عنــه مشــاده باأليــدي‬\n‫ال من‪/‬املدعــى‬   ‫بينهمــا وتدخلــوا زمالئــه املوجوديــن بالصالــون وهــم ك ً‬\n‫عليــه الســادس والســابع وزبــون آخــر كان جالــس ينتظــر دوره للحالقــه‬\n‫وأن املضاربــه التــي حدثــت يــوم الســبت املوافــق ‪1433/6/7‬ه ـ كان مــن‬\n                                          ‫ضمــن املشــاركني بهــا املدعــى عليــه‬\n‫الرابــع وكان عددهــم ثمانيــة أشــخاص ال يعــرف أحــد منهــم ســوى‬\n‫املذكــور ‪.‬جــرى عــرض كل مــن املدعــى عليــه األول ( واملدعــى عليــه‬\n‫الثانــي ) واملدعــى عليــه الثالــث بــن مجموعــة مــن املوقوفــن مقاربــن‬\n‫لهــم باألوصــاف الظاهريــة والبدنيــة علــى املدعــى اخلامــس والســادس‬\n‫واســتطاع املدعــى عليــه اخلامــس التعــرف علــى املدعو‪/‬املدعــى عليــه‬\n‫الثانــي بنســبة (‪ )%100‬وأفــاد بأنــه مــن ضمــن املعتديــن عليــه داخــل احملــل‬\n‫ولــم يســتطع التعــرف علــى أحــد خالفــه ‪،‬وكذلــك تعــرف املدعــى عليــه‬\n‫الســادس علــى املدعــى عليــه الثانــي وعلــى املدعــو املدعــى عليــه الثالــث‬\n‫بنســبة (‪ )%100‬وذكــر بأنهــم مــن ضمــن املعتديــن عليهــم ‪.‬وقــد أســفر‬\n‫التحقيــق معهــم عــن توجيــه االتهــام لهــم باالعتــداء علــى بعضهــم البعــض‬\n‫بــأدوات حــاده مــن قبــل املجموعــه االولــى والتســبب باالصابــات التــي‬\n\n\n                                                                                       ‫‪136‬‬\n\f      ‫حلقــت بهــم علــى اثــر ســوء تفاهــم حصــل بينهــم ‪ ،‬وذلــك لألدلــة والقرائــن‬\n                                                                                 ‫التاليــة‪:‬‬\n                   ‫‪ .1‬محضر تقدمي البالغ املدون على اللفتني رقم (‪. )115،138‬‬\n      ‫‪ .2‬محضر املعاينة املدون على الصفحة رقم (‪ )2،3‬من ملف االستدالل‬\n                ‫لفه رقم(‪ )8‬واللفه رقم(‪ )2،3‬من ملف االســتدالل لفه رقم(‪. )12‬‬\n      ‫‪ .3‬محضــر العــرض والتعــرف املــدون علــى الصفحــة رقــم ( ‪ )7‬مــن ملــف‬\n      ‫االســتدالل لفــة رقــم ( ‪ )12‬الصفحــة رقــم ( ‪ )15‬مــن ملــف االســتدالل‬\n                                                                         ‫لفــة رقــم ( ‪. )1‬‬\n      ‫‪ .4‬مــا جــاء يف أقوالهــم املدونــه علــى الصفحــات رقــم ( ‪10‬الــى‪ )16‬مــن‬\n      ‫ملــف االســتدالل لفــة (‪)8‬و الصفحــات رقــم (‪1‬الــى‪ )11‬مــن ملــف‬\n      ‫االســتدالل لفــة (‪)6‬و الصفحــات رقــم ( ‪5‬الــى‪ )1‬مــن ملــف االســتدالل‬\n      ‫لفــة (‪ )5‬الصفحــات رقــم ( ‪ )11،16‬مــن ملــف االســتدالل لفــة (‪)4‬‬\n      ‫التقاريــر الطبيــة املرفقــة علــى اللفــات رقــم من(‪95‬الــى‪ . )101‬وببحــث‬\n      ‫ســوابق الثالــث تبــن وجــود ســابقتني مســجله عليــه األول مضــارب‬\n      ‫جماعيــة والثانــي اعتــداء بالطعــن وببحــث ســوابق البقيــه تبــن خلــو‬\n      ‫ســجالتهم مــن الســوابق اجلنائيــة وحيــث إن مــا أقــدم عليــه املذكــورون ـ‬\n      ‫وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا ـ فعــل محــرم ومعاقــب عليه شــرع ًا‬\n      ‫‪ ،‬أطلــب إثبــات مــا أســند إليــه واحلكــم عليهــم بعقوبــة تعزيريــة لقــاء مــا‬\n      ‫ال بحســب فعلــه‪ .‬علمـ ًا بــأن احلــق اخلــاص انتهــى‬\n                                                          ‫أســند إليهــم مــن اتهــام ك ً‬\n      ‫بالتنــازل هكــذا ا َّدعــى ‪ .‬عليــه فقــد حضــر املدعــى عليهــم جميعـ ًا وبعــد‬\n      ‫التأكــد مــن هوياتهــم جــرى عــرض دعــوى املدعــي العــام عليهــم فأجــاب‬\n      ‫املدعــى عليــه األول بعــد التأكــد مــن هويتــه عــن دعــوى املدعــي العــام‬\n      ‫فأجــاب قائ ـاً‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باالشــتراك يف‬\n\n\n‫‪137‬‬\n\f‫املضاربــة فصحيــح وذلــك أننــي كنـ ُـت أحلــق رأســي يف احلــاق الــذي‬\n‫يعمــل فيــه املدعــى عليهــم اخلامــس والســادس والســابع وكان الــذي‬\n‫يقــوم بحالقتــي املدعــى عليــه اخلامــس وبعــد انتهــاء احلالقــة قلــت لــه إن‬\n‫حالقتــك ليســت جيــدة فحصــل بينــا مشــادة كالميــة أدت إلــى املضاربــة‬\n‫يف إصابــات وذهبــت إلــى املنــزل وبعدهــا بيــوم رجعــت‬    ‫باأليــدي وحصــل َّ‬\n‫بصحبــة املدعــى عليهمــا الثانــي والثالــث وكان معــي واملدعــى عليــه‬\n‫الثانــي عجــرا وقمــت بضــرب املدعــى عليــه اخلامس والســابع وتســببت يف‬\n‫اإلصابــات املوصوفــة بالتقاريــر الطبيــة املذكــورة وأنــا نــادم علــى مابــدر‬\n‫منــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه الثانــي قائـاً‪ :‬ماذكــره‬\n‫املدعــي العــام مــن اتهامــي باملشــاركة يف املضاربــة فصحيــح وذلــك أننــي‬\n‫كنــت يف منــزل املدعــى عليــه األول وكان مصاب ـ ًا فقمــت وذهبــت‬\n‫بســيارتي برفقــة األول والثالــث وكان معــي عجــرا وملــا وصلنــا إلــى‬\n‫احملــل قمــت بضــرب املدعــى عليــه اخلامــس بيــدي ولــم أســتخدم العصــا‬\n‫وأنــا نــادم علــى مابــدر منــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬\n‫الثالــث قائ ـاً‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باملشــاركة يف‬\n‫املضاربــة فصحيــح وذلــك أننــي قمــت بالذهــاب مــع املدعــى عليهمــا األول‬\n‫والثالــث وقمــت بضــرب املدعــى عليــه اخلامــس بيــدي كمــا قمــت‬\n‫بإمســاك بــاب احملــل حتــى اليخــرج أحــد منــه وصحيــح نســبة الســابقتني‬\n‫لــي وقــد أخــذت محكوميتهمــا هكــذا أجــاب كمــا أجــاب املدعــى‬\n‫ا ‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باالعتــداء علــى‬   ‫عليــه الرابــع قائـ ً‬\n‫اخلامــس والســادس والســابع بــأدوات حــادة والتســبب باإلصابــات التــي‬\n‫حلقــت بهــم غيــر صحيــح والصحيــح أننــي كنــت جالس ـ ًا يف الصالــون‬\n‫الــذي يعمــل فيــه املدعــى عليهــم األتــراك أنتظــر دوري يف احلالقــة‬\n\n\n                                                                                         ‫‪138‬‬\n\f      ‫وحصلــت مشــادة كالميــة بــن املدعــى عليــه األول واملدعــى عليهمــا‬\n      ‫اخلامــس والســادس وحاولــت فــك النــزاع بينهــم مــع املدعــى عليــه الســابع‬\n      ‫وأثنــاء ذلــك حصلــت بيننــا مضاربــة باأليــدي مــع شــدة النــزاع والعالقــة‬\n      ‫ـأي شــيء ســوى ذلــك هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬            ‫لــي بـ ِّ‬\n      ‫ا ‪ :‬ماذكــره املدعــي العــام يف دعــواه مــن حصــول‬      ‫اخلامــس فأجــاب قائـ ً‬\n      ‫أن املدعــى عليــه األول‬ ‫اعتــداء علينــا يف محــل احلالقــة فصحيــح وذلــك َّ‬\n      ‫كان يحلــق عندنــا وقــام بســبي والتكلــم علـ َّـي وأننــي ال أعــرف أعمــل‬\n      ‫وقــام برمــي الفلــوس يف وجهــي ثــم خــرج ورجــع وحصــل بينــه وبينــه‬\n      ‫املدعــى عليــه الســادس مضاربــة أ َّدت إلى اشــتباكنا جميعـ ًا وبعد يومني‬\n      ‫حضــر شــخص ال أدري مــن هــو وضربنــي علــى رأســي بعصــا وأنا منشــغل‬\n      ‫بحالقــة رأس زبــون ممــا أ َّدى إلــى إغمائــي وإصابتــي وال أعــرف مــاذا‬\n      ‫حــدث بعــد ذلــك هكــذا أجــاب كمــا أجــاب املدعــى عليــه الســابع‬\n      ‫ا ‪ :‬ماذكــره املدعــي العــام مــن اتهامــي باملشــاركة يف‬          ‫‪ ............‬قائ ـ ً‬\n      ‫أن املدعــى عليــه األول كان يحلــق‬     ‫االعتــداء فغيــر صحيــح والصحيــح َّ‬\n      ‫عنــد املدعــى عليــه اخلامــس وحصلــت بينهمــا مشــادة كالميــة وحاولــت‬\n      ‫فــك النــزاع بينهمــا فقــام بعضــي علــى وجهــي فحاولــت الدفــاع عن نفســي‬\n      ‫وقمــت بعضــه وانتهــى النــزاع وبعــد يومــن حضــر املدعــى عليــه األول‬\n      ‫وبرفقتــه عــدة أشــخاص لــم يكــن املدعــى عليــه الرابــع مــن ضمنهــم‬\n      ‫وقامــوا بضربنــا بعصــي كانــت معهــم ولــم يكــن م َّنــا أي مدافعــة حيــث‬\n      ‫إنهــم أتونــا مفاجئــة هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام عــن‬\n      ‫بينتــه علــى مانفــاه املدعــى عليهــم الرابــع واخلامــس والســادس والســابع‬\n      ‫ـدي ســوى مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا‬    ‫فقــال ‪ :‬ليــس لـ َّ‬\n      ‫هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا‬\n\n\n‫‪139‬‬\n\f‫التقريــر الطبــي املوجــود علــى اللفــة(‪ )95‬الصــادر مــن مستشــفى امللــك‬\n‫فهــد بالهفــوف املتضمــن إصابــة املدعــى عليــه اخلامــس ‪ ............‬بــرض‬\n‫رأســي مــع حالــة تغيــم وعــي و كســرب اجلمجمــة مــع نــزف خــارج اجلافيــة‬\n‫صدغــي أميــن ومــدة الشــفاء غيــر محــددة كمــا جــرى االطــاع علــى‬\n‫التقريــر الطبــي املوجــود علــى اللفــة (‪ )96‬الصــادر مــن املستشــفى نفســه‬\n‫برقم ـ مــن ذات املستشــفى بحــق املدعــى عليــه اخلامــس املتضمــن إصابــة‬\n‫املدعــى عليــه املذكــور بــرض رأســي و كســر باجلمجمــة مــع نــزف خارج‬\n‫اجلافيــة صدغــي أميــن ومــدة الشــفاء شــهر مالــم حتــدث مضاعفــات كمــا‬\n‫جــرى االطــاع علــى التقريــر الطبــي املوجــود علــى اللفــة(‪ )97‬الصــادر‬\n‫مــن الوطنــي رقــم الصــادر بحــق املدعــى عليــه األول املتضمــن إصابتــه‬\n‫بجــرح قطعــي باجلهــة اليســرى مــن الوجــه بطــول ( ‪ 2‬ســم ) مــع فقــدان‬\n‫اجللــد وجــرح باخلــد األميــن بطــول (‪1‬ســم) هــذه اجلــروح علــى األغلــب نتيجة‬\n‫اإلصابــة بآلــة حــادة ومــدة الشــفاء أســبوع مــا لــم حتــدث مضاعفــات ‪.‬‬\n‫كمــا جــرى االطــاع علــى التقريــر الطبــي املوجــود علــى اللفــة (‪)98‬‬\n‫أن املدعــى عليــه الســابع يشــتكي مــن عضــة علــى‬  ‫الصــادر مــن املتضمــن َّ‬\n‫اخلــد األيســر وكدمــات خفيفــة متفرقــة يف أنحــاء اجلســم ومــدة الشــفاء‬\n‫يومــان كمــا جــرى االطــاع علــى التقريــر الطبــي املوجــود علــى‬\n‫اللفــة(‪ )99‬الصــادر مــن املستشــفى نفســه برقــم ـ مــن ذات املستشــفى‬\n‫بحــق املدعــى عليــه الســابع املتضمــن إصابــة املدعــى عليــه املذكــور‬\n‫بقطــع يف فــروة الــرأس وقطــع آخــر يف اليــد اليســرى وكدمــات متفرقــة‬\n‫ومــدة الشــفاء ثالثــة أيــام كمــا جــرى االطــاع علــى كــروت ســوابق‬\n‫املدعــى عليهــم فوجــد أ َّنهــا خاليــة مــن الســوابق ســوى املدعــى عليــه‬\n‫فوجــد عنــده ســابقتان األولــى مضاربــة جماعيــة والثانيــة اعتــداء بالطعن‬\n\n\n                                                                                     ‫‪140‬‬\n\f      ‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬             ‫فبنـ ً‬\n      ‫عليهــم والتأكــد مــن أهليتهــم وبعــد تأمــل أوراق املعاملــة ودراســتها ومبــا‬\n      ‫أن املدعــى عليــه األول أقـ َّـر بدعــوى املدعــي العــام وأ َّنــه قــام باالشــتراك‬           ‫َّ‬\n      ‫يف املضاربــة وأ َّنــه تســبب باإلصابــات التــي وجــدت يف املدعــى عليــه‬\n      ‫وأن املضاربــة حصلــت بســببه ومبــا‬            ‫اخلامــس حيــث ضربــه بعصــا غليظــة َّ‬\n      ‫أن املدعــى عليــه الثانــي أقـ َّـر بدعــوى املدعــي العــام وأ َّنــه قــام باالشــتراك‬     ‫َّ‬\n      ‫يف املضاربــة ونقــل املدعــى عليهمــا الثانــي والثالــث بســيارتي للمحــل‬\n      ‫الــذي يعمــل فيــه املعتــدى عليهــم وضــرب اخلامــس بيــده دون العصــا التــي‬\n      ‫أن املدعــى عليــه الثالــث أقـ َّـر بدعــوى املدعــي العــام‬         ‫كان يحملهــا ومبــا َّ‬\n      ‫وأ َّنــه قــام باالشــتراك يف املضاربــة وضــرب املدعــى عليــه اخلامــس بيــده‬\n      ‫واإلمســاك بالبــاب حتــى اليتمكــن أحـ ٌـد مــن الدخــول وال اخلــروج مــن‬\n      ‫أن َ املدعــى عليــه الرابــع أنكــر دعــوى املدعــي العــام باتهامــه‬          ‫احملــل ومبــا ّ‬\n      ‫باملشــاركة يف املضاربــة والبينــة للمدعــي العــام علــى ذلــك ومبــا أ َّنــه أقـ َّـر‬\n      ‫مبحاولــة فــك النــزاع الــذي حصــل بــن األول واملدعــى عليهمــا خلامــس‬\n      ‫والســادس والســابع وأ َّدى ذلــك إلــى اســتعمال األيــدي لفــك النــزاع وهــذا‬\n      ‫أن املدعــى عليــه اخلامــس واملدعــى عليــه‬           ‫الفعــل اليســتوجب عقوبــة ومبــا َّ‬\n      ‫الســادس واملدعــى عليــه الســابع أنكــروا دعــوى املدعــي العــام مــن‬\n      ‫ـأن املدعــى عليهــم الثالثــة‬        ‫اتهامهــم باالشــتراك يف املضاربــة ودفعــوا بـ َّ‬\n      ‫أي مقاومــة منهــم‬        ‫األول هــم َمــنْ جــاء إلــى محلهــم وقامــوا بضربهــم دون ِّ‬\n      ‫ومبــا أ َّنــه البينــة للمدعــي العــام علــى مــا أنكــروه ومبــا أ َّنهــم أقـ َّـروا‬\n      ‫بحصــول مشــادة كالميــة بينهــم أ َّدت إلــى نشــوء هــذه املضاربــة وهــذا‬\n      ‫ـاب واســع فأعالهــا‬         ‫أن التعزيــر بـ ٌ‬‫مــن احملـ َّـرم يســتوجب تعزيرهــم ومبــا َّ‬\n      ‫لقتــل وأدنــاه التوبيــخ ممــا يســتوجب تعزيرهــم بالتوبيــخ وأخــذ التعهــد‬\n\n\n‫‪141‬‬\n\f‫أن ماصــدر مــن املدعــى عليهــم األول والثانــي والثالــث مــن احملـ َّـرم‬                                         ‫ومبــا َّ‬\n‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا ) وقــال تعالــى‬        ‫ال ْر ِ‬‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬ ‫شــرع ًا قــال تعالــى‪َ :‬‬\n‫الل ال ُي ِ ُّحــب ْال ُْع َتدِ َيــن ) وقــال صلــى اهلل عليــه وســلم ‪:‬‬                ‫‪َ ( :‬وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n‫وعرضــه)) وقــال عليــه‬    ‫ُ‬             ‫دم ـ ُه وما ُل ـ ُه‬‫ـرام ُ‬\n                                                                 ‫((كلُّ املســلم علــى املســلم حـ ٌ‬\n‫كـ ْـم َحـ َـر ٌام‬   ‫َكـ ْـم َو َأ ْع َر َ‬\n                  ‫اض ُ‬                      ‫كـ ْـم َو َأ ْم َوال ُ‬‫‪((:‬ف ـ ِإ َّن د َِم َاء ُ‬\n                                                                                       ‫الصــاة والســام َ‬\n‫كـ ْـم‬  ‫ك ْم َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬    ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬         ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬\n                                                                                                         ‫كـ ْـم َ‬      ‫َع َل ْي ُ‬\n‫َهـ َـذا )) ممــا يســتوجب تعزيرهــم لقــاء ذلــك ويتوجــه أن يكــون املدعــى‬\n‫عليــه األول أشــدهم عقوبــة لكونــه املتســبب يف املضاربــة ولعظــم مــا‬\n‫صــدر منــه كمــا يتوجــه اســتواء الثانــي والثالــث يف العقوبــة الســتوائهما‬\n‫يف اجلــرم كمــا يراعــي يف العقوبــة انتهــاء احلقــوق اخلاصــة بالتنــازل لــذا‬\n‫كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليهــم مبــا يلــي ‪ :‬أو ًال ‪/‬‬\n‫ـدي إدانــة املدعــى عليــه األول باالشــتراك يف املضاربــة وضربــه‬                                           ‫ثبــت لـ َّ‬\n‫للمدعــى عليــه اخلامــس بعصــا غليظــة وتســببه باإلصابــات التــي وجــدت‬\n‫بــه ويعــزر ألجــل ذلــك بســجنه ثالثــة أشــهر حتتســب منهــا املــدة التــي‬\n‫أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائــة وعشــرون جلــدة مفرقــة‬\n‫علــى ثــاث دفعــات كل دفعــة أربعــون جلــدة وبــن كل دفعــة وأخــرى‬\n‫ـدي إدانــة املدعــى عليــه الثانــي‬             ‫مــدة التقــل عــن عشــرة أيــام ‪.‬ثانيـ ًا ‪ /‬ثبــت لـ َّ‬\n‫واملدعــى عليــه الثالــث باالشــتراك يف املضاربــة واالعتــداء علــى اخلامــس‬\n‫والســادس والســابع بأيديهــم وعــزرت كل واحــد منهمــا لقــاء ذلــك‬\n‫بســجنه ملــدة خمســة وأربعــن يومـ ًا حتتســب منهــا املــدة التــي أوقــف فيهــا‬\n‫كل واحــد منهمــا علــى ذمــة القضيــة ويجلــد كل واحــد منهمــا ثمانــون‬\n‫جلــدة مفرقــة علــى دفعتــن متســاويتني كل دفعــة أربعــون جلــدة وبــن‬\n‫ـدي‬\n ‫كل دفعــة وأخــرى مــدة التقــل عــن عشــرة أيــام ‪ .‬ثالث ـ ًا ‪ /‬لــم يثبــت لـ َّ‬\n\n                                                                                                                                    ‫‪142‬‬\n\f      ‫إدانــة املدعــى عليهــم الرابــع واملدعــى عليــه اخلامــس واملدعــى عليــه‬\n      ‫الســابع باالشــتراك يف املضاربــة وقــررت رد دعــوى املدعــي العــام بإثبــات‬\n      ‫ـدي إدانتهــم بحصــول مشــادة كالميــة أ َّدت إلــى‬        ‫ذلــك وإمنــا ثبــت لـ َّ‬\n      ‫املضاربــة وعزرتهــم بالتوبيــخ والتقريــع والتوجيــه داخــل املجلس الشــرعي‬\n      ‫مت ذلــك ‪ .‬رابعـ ًا ‪ /‬يؤخــذ عليهــم التعهــد بعــدم العــودة ملثــل مــا صــدر منهم‬\n                                                                                        ‫و َّ‬\n      ‫‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليهــم بحقهــم يف متييــز‬\n      ‫احلكــم قــرر املدعــى عليهــم جميع ـ ًا القناعــة بــه وطلــب املدعــي العــام‬\n      ‫رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون‬\n      ‫الئحـ ٍة اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى وصلى اهلل وسـلَّم‬\n      ‫‪.‬حـ ِـر َر يف ‪1434/01/07‬هـ‬   ‫علــى نبينــا محمــد وعلــى آله وصحبه أجمعني ُ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد ففــي‬\n      ‫يــوم األحــد ‪1434/03/15‬ه ـ فتحــت اجللســة الثانيــة الســاعة الثامنــة‬\n      ‫والنصــف وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم ‪34296669‬‬\n      ‫والتاريــخ ‪1434/03/01‬ه ـ مرفق ـ ًا بهــا قــرار أصحــاب الفضيلــة قضــاة‬\n      ‫الدائــرة اجلزائيــة الثالثيــة الثانيــة رقــم ‪ 3437333‬ج‪ 2/‬وتاريــخ‬\n      ‫مانصــه ‪ :‬بدراســة القــرار وصــورة ضبطــه‬    ‫ُّ‬     ‫‪1434/02/13‬ه ـ املتضمــن‬\n      ‫وأوراق املعاملــة لوحــظ أن صــورة الضبــط املرفقــة غيــر مكتملــة والبــد‬\n      ‫مــن إرفــاق صــورة الضبــط مكتملــة ملالحظــة مــا ذكر وإكمــال مايلزم‬\n      ‫ومــن ثــم إعــادة املعاملــة وبــاهلل التوفيــق قاضــي اســتئناف ختمــه وتوقيعــه‬\n      ‫‪ ،‬قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه أ‪.‬ه ـ‬\n      ‫عليــه أجيــب مشــائخي نفعنــي اهلل بعلمهــم بأنــه مت إجــراء الــازم حيــال‬\n      ‫هــذه املالحظــة وأقفلــت اجللســة الســاعة الثامنــة وخمســة وأربعــون دقيقــة‬\n\n\n‫‪143‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":131,"source_page_end":143,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bf677292b71719b1650613aa3a8a54fb63d163d4e2a02a7727c789fa9d4f3bfa","normalized_text_hash":"c1c9c43fe7a7d94aae3cf04e4e48de6557e33a83e53c373dfde132b832ec90a4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p131-3420263"}]$archive_payload$::jsonb) AS x LIMIT 25
